/* cotTruyen q07 (141 chương) — engine-API cotTruyen */
window.__LIBQ=window.__LIBQ||{};window.__LIBQ["pham-nhan-tu-tien"]=window.__LIBQ["pham-nhan-tu-tien"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q07"]=window.__LIBQ["pham-nhan-tu-tien"]["q07"]||{};window.__LIBQ["pham-nhan-tu-tien"]["q07"]["cotTruyen"]=[{"chuong":1121,"tieuDe":"Trọng Phản Cố Địa Hư Thiên Điện","tomTat":"Hàn Lập dùng Tam diễn phiến chém thủng quầng sáng giam giữ rồi lấy Đại na di lĩnh kích hoạt Cổ truyền tống trận, khiến hắn, Băng phượng, Ngũ tử ma và nhân hình Khôi lỗi cùng biến mất khỏi Hư Linh điện. Tại chiến trường còn lại, hóa thân Xa lão yêu điều khiển Vạn yêu phiên tấn công Tiểu Cực cung cung chủ, nhưng Hoàng tuyền Quỷ Mẫu đứng ra nghênh chiến và cung chủ cũng dùng xích hồng lôi hỏa tham gia. Hàn Lập cùng các trợ lực xuất hiện trong một thạch phòng kín với Băng phượng, song hai bên đều kiêng dè thực lực của đối phương và tránh tử chiến. Băng phượng dùng thần thông không gian rời khỏi phòng, còn nhân hình Khôi lỗi phá vách để mở đường cho Hàn Lập. Qua cửa đá và ngã tư thông đạo quen thuộc, Hàn Lập nhận ra mình đã từ cực bắc Đại Tấn truyền tống tới nội điện Hư Thiên điện tại Loạn Tinh Hải, nơi hắn từng lấy Hư thiên đỉnh. Hắn kết luận Hư Linh điện và Hư Thiên điện có quan hệ sâu xa, đồng thời dự định rời khỏi điện và khôi phục Truyền Tống trận cũ để trở về Thiên Nam. Trên đường bay trong cự tháp năm tầng, hắn không gặp Khôi Lỗi thủ vệ, cấm chế hay cơ quan hoạt động và suy đoán toàn bộ đã tạm thời được thu hồi vì chưa tới kỳ mở điện."},{"chuong":1122,"tieuDe":"Liên Thủ","tomTat":"Hàn Lập dùng Minh Thanh Linh Mục vượt qua các ảo cảnh trong mê cung và tìm đến những tàng bảo thất, nhưng không thể hóa giải cấm chế cố định bảo vật nên đành từ bỏ ý định vét sạch nơi này. Hắn tiến lên tầng năm, suy đoán khu vực khống chế pháp trận nằm gần Hàn Ly thai, song tìm kiếm suốt hai ngày vẫn không có kết quả. Băng Phượng quay lại và cho biết hai người không đủ sức cưỡng ép phá các cấm chế của Hư Thiên Điện, vì vậy họ chỉ còn cách tạm gác ân oán để hợp tác. Trong cuộc trao đổi, nàng hé lộ Băng Phách tiên tử là người sáng tạo Kiền Lam Băng Diễm và là tổ sư khai phái Tiểu Cực Cung. Hàn Lập xác nhận tiểu đỉnh trong tay chính là Hư Thiên Đỉnh, vật cần dùng để khống chế pháp trận. Băng Phượng dẫn hắn trở lại Hàn Ly thai, nói Băng Lan đảo của nhất tộc mình có một thạch thai tương tự rồi gọi ra hơn mười trận kỳ trắng. Dưới tác động của các trận kỳ, pháp trận ẩn lấy tế đàn làm trung tâm hiện ra và trải rộng gần như toàn bộ thạch thai."},{"chuong":1123,"tieuDe":"Khốn Địa Tiềm Tu","tomTat":"Hàn Lập nhận ra đại trận trên thạch đài là pháp trận khống chế Hư Thiên điện và đưa Hư Thiên Đỉnh vào trận nhãn để thử vận hành. Bảo đỉnh phóng lớn rồi hút pháp lực dữ dội, nhưng dù Băng Phượng cùng hỗ trợ, hai người vẫn không đủ sức mở đại trận và phải dừng lại. Băng Phượng đề xuất dùng bí thuật dung hợp pháp lực của nhiều nguồn dưới sự điều khiển của nàng, song Hàn Lập cự tuyệt vì phương án ấy buộc hắn giao quyền sử dụng Hư Thiên Đỉnh. Hàn Lập tiết lộ Hư Thiên điện sẽ tự mở sau mỗi ba trăm năm và quyết định ở lại tiềm tu thay vì liều lĩnh tìm đường thoát ngay. Có hy vọng rời đi về sau, Băng Phượng cũng từ bỏ việc dùng bí thuật tự tổn để cưỡng ép lên Hóa Thần và chọn luyện tiếp những bí thuật còn dang dở. Hàn Lập trở lại mật thất tầng hai có Linh Nhãn Chi Tuyền, phong ấn Truyền tống trận và dùng trận kỳ che giấu nơi bế quan của mình."},{"chuong":1124,"tieuDe":"Thiên Triệu","tomTat":"Hàn Lập nhận thấy giao Hư Thiên Đỉnh cho Băng Phượng sẽ khiến đối phương có thể luyện tầng thứ hai của Thông Bảo Quyết và trở thành mối đe dọa khó chống đỡ. Vì nội đan Hỏa Thiềm thú có thể trì hoãn phong hồn chú của Nam Cung Uyển trong hai đến ba trăm năm, hắn tạm hoãn việc trở về Thiên Nam và bế quan bên Linh Nhãn Chi Tuyền suốt tám mươi năm. Tại Nội Hải, các tu sĩ bàn luận cuộc tranh chấp giữa Tinh Cung và Nghịch Tinh Minh, trong đó Nghịch Tinh Minh chiếm phần lớn đảo nhỏ còn Tinh Cung thắng nhiều trận hơn nhờ uy thế của Thiên Tinh Song Thánh quanh Thiên Tinh đảo. Một thiên tượng dữ dội bất ngờ xuất hiện ngoài hải cảng, tạo ra mây rực rỡ, linh áp kinh người, sóng cao hơn trăm trượng và làm cả hải đảo rung chuyển. Ba tu sĩ Kết Đan nghi ngờ có bảo vật xuất thế, nhưng trung niên nhân mù cảnh báo họ không đủ sức tranh đoạt và cho biết Hỗn lão ma đang ở gần. Ông đồng thời nhận định dị tượng phần lớn không phải thiên triệu của bảo vật. Khi không gian giữa vùng mây bị vặn vẹo, một góc cung điện trắng bí ẩn hiện ra trong ánh sáng trong suốt."},{"chuong":1125,"tieuDe":"Hậu Kỳ Sơ Thành","tomTat":"Hư Thiên Điện bất ngờ xuất hiện trên Loạn Tinh Hải khi còn chưa tới chu kỳ ba trăm năm, khiến Cam Lâm cùng ba môn nhân Hoàng Sa Môn kinh ngạc theo dõi. Một pháp trận trong cột sáng truyền tống Hàn Lập, Băng Phượng và Hư Thiên Đỉnh ra ngoài, sau đó cung điện nhanh chóng biến mất. Hỗn Lão Ma lập tức bỏ chạy nhưng vẫn bị Băng Phượng dùng hơn trăm đạo kiếm quang phá bảo vật, phân thây và diệt cả nguyên thần. Cam Lâm nhận ra Hàn Lập là Đại tu sĩ Nguyên Anh hậu kỳ nên chủ động nghênh đón và mời hắn tới Hoàng Sa Môn. Trong hơn tám mươi năm mắc kẹt, Hàn Lập đã tu tới Nguyên Anh trung kỳ đỉnh phong, củng cố tu vi rồi thuận lợi đột phá hậu kỳ, đồng thời luyện thành tầng hai Thông Thiên Bảo Quyết và tế luyện lại Bát Linh Xích cùng Hư Thiên Đỉnh. Chính Hàn Lập, Băng Phượng, Ngũ tử ma và nhân hình Khôi Lỗi đã hợp lực khống chế pháp trận, tạm đưa Hư Thiên Điện ra khỏi hư không để thoát vây. Sau khi nhận thấy Hàn Lập đã tiến giai, Băng Phượng từ bỏ ý định đối phó hắn và tự đi tìm đường trở về Đại Tấn, còn Hàn Lập tiếp tục giữ kín Thượng Cổ truyền tống trận dẫn về Thiên Nam."},{"chuong":1126,"tieuDe":"Hoàng Sa Môn","tomTat":"Sau khi chia tay Băng Phượng và thu lại Hư Thiên Đỉnh, Hàn Lập tới Khổ Môn Đảo để xác định vị trí và tìm hiểu tình hình Loạn Tinh Hải. Cam Lâm, đại trưởng lão Hoàng Sa Môn, mời hắn vào đảo rồi cho biết lộ trình tới Khôi Tinh Đảo phải đi qua Thiên Tinh Thành. Tại trụ sở Hoàng Sa Môn, Hàn Lập che giấu phần lớn trải nghiệm trong Hư Thiên Điện và đề nghị dùng viên hoàn màu bạc cùng cổ qua màu vàng đổi lấy tài liệu và linh thạch. Cam Lâm tiết lộ một khoáng mạch linh thạch lớn tại Ngoại Tinh Hải từng gây ra cuộc đại chiến giữa Tinh Cung, Nghịch Tinh Minh và yêu thú cao giai, trước khi ba phe tạm chia nhau khu mỏ. Vì số cao giai linh thạch dùng cho nhân hình Khôi lỗi đã gần cạn, Hàn Lập quyết định dùng truyền tống trận của Tinh Cung để tới khu khoáng mạch. Sau khi Hoàng Sa Môn giao gần đủ vật tư cùng bảy tám khối cao giai linh thạch, Hàn Lập rời Khổ Môn Đảo, khiến các tu sĩ ở lại mới trút được nỗi lo."},{"chuong":1127,"tieuDe":"Lời Đồn","tomTat":"Sau khi Hàn Lập rời Khổ Môn Đảo, Thạch Tuyên nhận ra hắn là Kết Đan tu sĩ từng bị Nghịch Tinh Minh ban Tiểu Sát Lệnh gần hai trăm năm trước và dùng ngọc giản lưu ảo ảnh để chứng minh. Tu sĩ họ Cam xác nhận thân phận này, lập tức cấm các môn nhân rời đi trong mười năm và ra lệnh âm thầm phong bế sơn môn để tránh tai họa. Ông cũng từ bỏ ý định tiết lộ việc Hàn Lập có thể đang giữ Hư Thiên Đỉnh vì biết mình không đủ sức tranh bảo vật và có thể chuốc họa sát thân. Trong lúc đó, tin Hư Thiên Điện hiện thế lan rộng khắp Loạn Tinh Hải, nhưng chuyện Băng Phượng giết Hỗn Lão Ma bị xuyên tạc qua nhiều lần truyền miệng. Dấu vết Hàn Lập khu sử Hư Thiên Đỉnh vẫn khiến nhiều tu sĩ Nguyên Anh và tông môn lần ra thân phận cũ rồi nảy lòng nhòm ngó hắn. Không biết mình đã trở thành mục tiêu, Hàn Lập ghé nhiều đảo đổi bảo vật và tài liệu quý lấy hơn hai mươi viên linh thạch cao giai. Sau hơn một tháng, hắn tới gần Thiên Tinh Thành và bắt gặp một đội tu sĩ có một Nguyên Anh sơ kỳ mang khí tức quen thuộc, khiến hắn dừng lại quan sát."},{"chuong":1128,"tieuDe":"Mật Ngữ","tomTat":"Trên đường tới Thiên Tinh Thành, Hàn Lập gặp đội tu sĩ Tinh Cung do Lăng Ngọc Linh dẫn đầu và nhận ra người quen từng được mình cứu năm xưa nay đã kết anh, trở thành trưởng lão. Lăng Ngọc Linh kinh ngạc khi biết hắn đã đạt Nguyên Anh trung kỳ trong chưa đầy hai trăm năm, rồi trao lệnh bài để hắn sử dụng một trong hai truyền tống trận còn hoạt động đi ngoại hải. Sau khi hai bên chia tay, nàng bí mật dùng độn âm phù báo tin và đề nghị người trong Thánh Sơn chiêu mộ Hàn Lập làm trợ thủ cho Tinh Cung. Hàn Lập đã sai nhân hình Khôi Lỗi chặn phù, nhờ đó biết chuyện mình sở hữu Hư Thiên Đỉnh đã lan khắp Loạn Tinh Hải, nên đổi dung mạo thành một đại hán da ngăm trước khi vào thành. Tuy nhiên, nam tử trong động quật dưới Thánh Sơn vẫn phục hồi được hỏa cầu truyền tin đã bị phá và cùng một nữ tử xem xét mật báo. Hai người xác nhận Hàn Lập chính là tu sĩ từng đoạt Hư Thiên Đỉnh và cứu Lăng Ngọc Linh, đồng thời nhận định tu vi hiện tại của hắn không thể xem nhẹ. Dựa trên tốc độ tu luyện khác thường và cuộc điều tra cũ, nữ tử nghi Hàn Lập là tu sĩ ngoại lai có thể xuất thân từ một đại tông môn tại Đại Tấn."},{"chuong":1129,"tieuDe":"Nguyên Từ Thần Quang","tomTat":"Cát Thiên Lôi và nữ tử đồng tu thừa nhận họ đã vượt qua ba cửa ải của Nguyên Từ Thần Quang nhưng thất bại trước điều kiện linh căn ở bước cuối, khiến con đường tiến giai Hóa Thần gần như đoạn tuyệt. Bí thuật huyết tế bảo vật đơn thuộc tính do Cát Thiên Lôi tìm được chỉ thay thế được một linh căn nên không đủ giải quyết khó khăn của hai người mang Thiên Linh Căn. Khi thọ nguyên chỉ còn chưa tới trăm năm, họ quyết định tập trung bồi dưỡng Lăng Ngọc Linh lên Nguyên Anh trung kỳ để chấp chưởng Tinh Cung, đồng thời chuẩn bị diệt Lục Đạo và Vạn Tam Cô. Hai người cũng định lôi kéo Hàn Lập, đặt cấm chế và lấy Hư Thiên Đỉnh nếu hắn thuận theo, còn nếu từ chối thì sẽ trực tiếp giết bỏ; nữ tử bí ẩn nhận nhiệm vụ ra tay tại Nguyên Từ Sơn. Trong khi đó, Hàn Lập vào Thiên Tinh Thành, che giấu tu vi rồi đợi canh ba dùng độn thuật và bí thuật ẩn nấp lẻn lên Tinh Không Điện. Trước khi phá cấm chế tiến vào, hắn phát hiện một nhóm gồm hai tu sĩ Kết Đan, bốn tu sĩ Trúc Cơ và một tu sĩ Luyện Khí đang bí mật tiếp cận cung điện. Nam tu cao gầy kích hoạt trận bàn lục bích, còn nữ tu thon thả dùng tiểu kỳ màu vàng phóng sương che giấu cả nhóm, khiến Hàn Lập ngạc nhiên vì dường như nhận ra pháp khí này."},{"chuong":1130,"tieuDe":"Chặn Lại","tomTat":"Hàn Lập âm thầm theo nhóm họ Điền vào Tinh Không điện và nhận ra Văn Tư Nguyệt dưới lớp che giấu. Điền đạo hữu mua chuộc hai chấp sự Tinh Cung để đưa vợ, con gái cùng bốn đệ tử tới Ngân Sa đảo tìm nội đan Bạch Ương Ngư Yêu chữa bệnh. Sau khi nhận bảy Truyền Tống Phù, cả nhóm tiến lên pháp trận nhưng bị nữ cung chủ Ôn Thanh bất ngờ chặn lại. Vợ chồng họ Điền liều mình bảo vệ con gái và xông vào Truyền Tống Trận, song bị quang hà đánh bật đến thổ huyết, trong khi thiếu nữ vẫn bình an. Ôn Thanh tiếp đó gọi thẳng Hàn Lập đang ẩn mình, buộc hắn công khai hiện thân trước mọi người. Nàng kinh hãi khi nhận ra hắn đã đạt Nguyên Anh hậu kỳ, còn Văn Tư Nguyệt cũng chấn động khác thường khi nhìn thấy khuôn mặt hắn. Cuối chương, Ôn Thanh nghiêm túc xác minh Hàn Lập có thật sự mang họ Hàn hay không, nhưng hắn chỉ hỏi ngược liệu nàng có chờ nhầm người."},{"chuong":1131,"tieuDe":"Kiêng Kỵ","tomTat":"Ôn Thanh dựa vào Nguyên Từ Thần Quang và Nguyên Từ Sơn nhưng từ bỏ ý định giao thủ vì không chắc có thể giết Hàn Lập, trong khi Hàn Lập cũng đề phòng việc bị các tu sĩ đồng giai của Tinh Cung vây công. Khi Ôn Thanh âm thầm phát truyền âm phù, Hàn Lập lập tức bắt giữ phù lục và cảnh cáo nàng không gọi thêm viện trợ. Hai bên lấy chuyện Hàn Lập từng cứu Lăng Ngọc Linh làm lý do hòa hoãn, qua đó Ôn Thanh công khai xác nhận Lăng Ngọc Linh là con của phu phụ Thiên Tinh Song Thánh. Nàng trao cho Hàn Lập khách khanh lệnh bài để hắn sử dụng tài nguyên Tinh Cung tại hải ngoại và mời hắn tới trao đổi tâm đắc đột phá Hóa Thần, nhưng hắn từ chối vì lo ngại cấm chế và pháp trận mai phục. Trước khi rời đi, Hàn Lập gặp lại Văn Tư Nguyệt, biết nàng đã kết thành Kim Đan nhờ đan dược và công pháp mình lưu lại, rồi đồng ý cho nhóm của nàng cùng sử dụng truyền tống trận. Hàn Lập thi triển Súc Địa Thuật, lấy Đại Na Di Lệnh và hỏi danh tính nữ tử che mặt; nàng tự xưng là Ôn Thanh ngay trước khi hắn biến mất trong bạch quang. Sau đó Ôn Thanh lệnh cho hai tu sĩ trông coi pháp trận đưa nhóm Văn Tư Nguyệt đi hải ngoại rồi trở về chấp pháp điện, mỗi người chịu hai mươi roi hạ lôi."},{"chuong":1132,"tieuDe":"Viện Thủ","tomTat":"Sau khi biết vợ chồng Văn Tư Nguyệt có quan hệ với Hàn Lập, Âm Lệ hán tử và Hoàng lão giả đổi sang thái độ lấy lòng, nhanh chóng vận hành truyền tống trận đưa cả đoàn bảy người ra hải ngoại. Văn Tư Nguyệt tìm được Hàn Lập tại đầu truyền tống bên kia và cầu xin hắn cứu con gái đang bị kỳ độc đe dọa tính mạng. Nàng cho biết đan dược luyện từ nội đan Bạch Lộ Ngư yêu chỉ có thể kéo dài sự sống, không thể giải độc hoàn toàn, đồng thời tiết lộ cha mình đã mất tích nhiều năm. Vì tình cố nhân, Hàn Lập đồng ý tới khách sạn kiểm tra bệnh trạng của cô gái trước khi quyết định phương pháp cứu chữa. Trong động quật Thánh sơn tại Thiên Tinh Thành, Ôn Thanh và phu quân xác nhận Hàn Lập đã đạt Nguyên Anh hậu kỳ với tốc độ tu luyện khác thường. Kết hợp Hư Thiên Đỉnh với dự cảm nguy hiểm do Linh Minh Quyết mang lại, Thiên Tinh Song Thánh nhận định Hàn Lập đủ sức uy hiếp trực tiếp họ và vẫn còn che giấu thủ đoạn đáng sợ."},{"chuong":1133,"tieuDe":"Đã Từng Quen Biết","tomTat":"Ôn Thanh và phu quân nhận định Hàn Lập vừa tiến giai Nguyên Anh hậu kỳ nhưng có thần thông không thể xem thường, vì vậy bàn cách thu phục hoặc tiêu diệt hắn. Họ dự tính theo dõi Khách khanh lệnh bài, chờ Hàn Lập từ Hải Ngoại truyền tống về Tinh Không Điện rồi dùng Nguyên Từ Sơn phong tỏa đường lui. Ôn Thanh còn đề xuất để Hàn Lập kết thành bạn lữ với Lăng Ngọc Linh, lấy Tinh Cung làm của hồi môn và giao hắn quyền chưởng quản, đồng thời chuẩn bị một cạm bẫy bí mật nhắm vào mong muốn đột phá Hóa Thần của hắn. Hai người muốn giải quyết cả Hàn Lập, Lục Đạo và Vạn Tam Cô trước khi tọa hóa để con gái thuận lợi chấp chưởng Loạn Tinh Hải. Trong nhà gỗ thanh tĩnh, Hàn Lập kiểm tra Điền Cầm Nhi và phát hiện kỳ độc giống vật sống đang cắn nuốt linh lực, khiến nàng chỉ còn khoảng ba tháng sinh cơ nếu không được cứu, nhưng hắn xác nhận mình có thể khu trừ độc tố. Sự trấn định và hiểu biết trận pháp của Điền Cầm Nhi khiến Hàn Lập nhớ tới Tân Như Âm. Khi nhìn thấy nốt ruồi đỏ như máu giữa lòng bàn tay nàng, hắn thất thanh kinh ngạc và sắc mặt lập tức biến đổi."},{"chuong":1134,"tieuDe":"Luân Hồi Chi Hoặc","tomTat":"Hàn Lập kiểm tra nốt ruồi đỏ trong lòng bàn tay Điền Cầm Nhi và xác định nàng mang Long Ngâm Chi Thể, còn độc tính Chí Dương chỉ khiến thể chất nguy hiểm này phát tác sớm. Sau khi cho vợ chồng Văn Tư Nguyệt ra ngoài và làm Điền Cầm Nhi bất tỉnh, hắn nhận thấy nàng có nhiều điểm tương đồng với một người khác nên nảy sinh nghi vấn về linh hồn luân hồi. Hàn Lập dùng mười ngân châm, pháp quyết ngũ sắc quang võng và kim quang lôi pháp để lấy ra rồi tiêu hủy độc vật, khu trừ được phần lớn độc tính. Hắn cho biết phần dư độc cần được thanh trừ bằng nội đan Bạch Lộ Ngư Yêu dùng sống. Một đạo Huyền Âm Linh Lực được truyền vào cơ thể Điền Cầm Nhi để tạm cân bằng dương khí, nhưng nàng phải ngừng tu luyện nếu muốn tránh phản phệ và kéo dài tuổi thọ. Muốn tiếp tục tu luyện, nàng cần một tu sĩ Nguyên Anh thường xuyên truyền âm khí, luôn ở gần để được hỗ trợ và phải dùng lượng đan dược ngày càng lớn. Nhận ra vợ chồng mình khó đáp ứng những điều kiện ấy hoặc tìm được một sư phụ Nguyên Anh cho con, Văn Tư Nguyệt hoàn toàn thất vọng."},{"chuong":1135,"tieuDe":"Ước Định","tomTat":"Hàn Lập cho vợ chồng Văn Tư Nguyệt biết tu vi Kết Đan sơ kỳ của họ chưa đủ để áp chế dương khí cắn trả trong cơ thể Điền Cầm Nhi, nhưng có thể thử khi cả hai đạt hậu kỳ và chấp nhận tổn hại tu vi. Hắn giao Pháp trận yếu quyết của Tân Như Âm để Điền Cầm Nhi tự lĩnh hội, coi kết quả là điều kiện cân nhắc nhận nàng làm đệ tử và trợ giúp nàng Trúc Cơ hoặc Kết Đan. Điền Cầm Nhi còn phải ngừng tu luyện, mỗi tháng dùng một viên Từ niệm hoàn, trong khi cha mẹ nàng tìm Bạch Lộ Yêu Đan rồi tới Khôi Tinh Đảo chờ cuộc hẹn sau một năm. Rời Ngân Sa đảo, Hàn Lập suy xét những điểm tương đồng giữa Điền Cầm Nhi và Tân Như Âm, nghi nàng có thể là chuyển thế hoặc có quan hệ sâu xa với cố nhân, đồng thời dự tính bồi dưỡng nàng thành Trận pháp tông sư nếu đủ thiên phú. Qua hải vực đồ, hắn xác định Bích Linh Đảo nằm rất xa về phía bắc và biết khoáng mạch nơi đó đã bị yêu thú biển, Thiên Tinh Cung cùng Nghịch Tinh Minh phân chia. Trên hành trình dự kiến kéo dài khoảng ba tháng, Hàn Lập chém chết một yêu thú biển tập kích và thu lấy yêu đan. Hơn một tháng sau, hắn dừng điều tức trên một tiểu đảo đá ngầm thì toàn đảo bất ngờ rung chuyển, tiếp đó tiếng gầm lớn vang lên từ đáy biển."},{"chuong":1136,"tieuDe":"Cự Cầm","tomTat":"Hàn Lập nghe thấy tiếng thú rống dưới một tiểu đảo và dùng thần niệm dò xuống biển, nhưng bị sức hút bí ẩn cưỡng ép lấy mất một phần thần niệm. Khi hắn chuẩn bị rời đi, tiếng kêu bén nhọn của một cự cầm xuyên qua quang tráo khiến hắn choáng váng, may nhờ tử sắc hỏa diễm cùng kim hồ tự phát hộ thể mới tỉnh lại. Một móng vuốt xanh biếc khổng lồ thò qua vết nứt không gian, khiến Hàn Lập lập tức dùng Phong Lôi Sí rời xa khu vực. Tiểu đảo sau đó chìm xuống, để lộ xoáy nước phun ra Quỷ Vụ mà Hàn Lập nhận ra là loại từng cuốn mình vào Âm Minh Chi địa. Cự cầm phóng năm cột sáng xanh xuống, còn Quỷ Vụ hóa thành miệng lớn cắn đứt chúng rồi dùng điện giao xuyên qua vết nứt đánh bị thương đối thủ. Cự cầm kêu thảm, làm rơi một cây Thanh vũ và thu móng lại, trong khi Quỷ Vụ bị xoáy nước cuốn xuống đáy biển, để mặt biển nhanh chóng trở lại bình lặng."},{"chuong":1137,"tieuDe":"Thanh Vũ","tomTat":"Sau khi xác nhận cự cầm đã biến mất, Hàn Lập nối thần niệm với nhân hình Khôi Lỗi và phái nó xuống vùng đáy biển sâu nơi Quỷ vụ từng xuất hiện. Khôi Lỗi phát hiện một Thanh vũ có linh tính và biết thuấn di, khiến Hàn Lập phải trực tiếp xuống biển, dùng Tịch Tà Thần Lôi cùng phù lục được gia trì bằng tinh huyết để phong bế nó. Linh vũ sau đó thu nhỏ còn khoảng một thước và bộc lộ phong linh lực cực kỳ tinh khiết, được hắn cất vào hộp ngọc. Trên đường tới Bích Linh Đảo, Hàn Lập suy đoán Quỷ vụ và Âm Minh Chi Địa có thể liên quan đến ma vật La Miên, còn cự cầm có khả năng là tồn tại đến từ Linh giới hoặc một giới diện khác. Hai tháng sau, hắn bắt gặp Thần Kinh cùng hai tu sĩ Trúc Cơ hậu kỳ đang bị một Anh Lý Thú cấp sáu truy sát. Thần Kinh tưởng Hàn Lập là tu sĩ Kết Đan đi ngang nên cầu cứu và hứa hậu tạ, trong khi Anh Lý Thú nhận ra tu vi thật của hắn, lập tức phóng hàng trăm lôi cầu yểm hộ rồi lao xuống biển bỏ chạy."},{"chuong":1138,"tieuDe":"Lôi Không Đảo","tomTat":"Hàn Lập dùng phi kiếm chém nát Anh Lý Thú lục cấp, diệt cả Nguyên Thần và thu lấy yêu đan, qua đó giải vây cho ba tu sĩ Thanh Dương Môn. Người dẫn đầu là Thần Kinh tự giới thiệu mình làm môn hạ Tam Dương Thượng Nhân và cho biết các phường thị gần Bích Linh Đảo có thể bán cao giai linh thạch. Hàn Lập trao yêu đan cho Thần Kinh làm thù lao dẫn đường, rồi cùng ba người bay hơn mười ngày tới Lôi Không Đảo. Trên đường và sau khi tới nơi, Thần Kinh giải thích rằng Nghịch Tinh Minh cùng Tinh Cung đang kiềm chế lẫn nhau tại đây, còn Bích Vân Môn và nhiều thế lực khác cũng muốn tranh quyền chiếm đảo. Hàn Lập còn biết Diệu Hạc Chân Nhân từng được Bích Vân Môn cứu sau khi mất thân thể, đã đoạt xá tu luyện lại và hiện có mặt trên đảo để đại diện môn phái. Đoàn người tiến vào tiểu thành mới xây ở trung tâm đảo, nơi tập trung phần lớn trong khoảng ba bốn vạn tu sĩ và có phường thị nằm về phía nam. Hàn Lập chú ý tới tám thạch tháp vận hành đại trận phòng hộ có uy lực ngang trấn phái đại trận, sau đó chuẩn bị tới phường thị tìm mua cao giai linh thạch."},{"chuong":1139,"tieuDe":"Thần Niệm Phụ Linh","tomTat":"Hàn Lập yêu cầu nhóm Thần Kinh giữ kín hành tung rồi bí mật cho một con Phệ Kim Trùng mang thần niệm bám theo họ. Tại động phủ ngoài thành, Ngôn sư điệt đề nghị báo Thanh Dương Môn điều tra Hàn Lập, nhưng Thần Kinh bác bỏ vì sư tổ đang bế quan và môn phái khó che chở họ trước một tu sĩ Nguyên Anh. Phệ Kim Trùng xuyên qua cấm chế mà không gây cảnh báo, giúp Hàn Lập thu nhận toàn bộ cuộc đối thoại và xác định ba người không có ý tiết lộ tin tức. Sau đó, hắn cải trang thành một lão giả cao gầy, áp chế tu vi xuống Kết Đan hậu kỳ và tiến vào phường thị phía nam tiểu thành. Từ sáu cửa hàng của Lục Liên Điện, hắn nhận ra Nghịch Tinh Minh vẫn có ảnh hưởng lớn tại Bích Linh Đảo dù chưa chiếm được đảo. Khi định tránh khỏi khu vực này, Hàn Lập bất ngờ nhìn thấy Diệu Hạc Chân Nhân đã đoạt xá trọng sinh bước ra cùng một hoàng sam lão giả Nguyên Anh sơ kỳ."},{"chuong":1140,"tieuDe":"Ôm Cây Đợi Thỏ","tomTat":"Hàn Lập giả trang thành một lão giả gầy gò, đi ngang Lục Liên Điện mà không bị Diệu Hạc chân nhân và Hoàng bào lão giả nhận ra, sau đó mua đủ vật cần dùng tại năm cửa hàng và đổi tài liệu lấy hơn một trăm khối cao giai linh thạch. Phát hiện nhiều tu sĩ Kết Đan bí mật bám theo, hắn công khai rời Thạch thành rồi dùng pháp thuật ẩn nấp cắt đuôi, đồng thời tha mạng cho họ để tránh kinh động các tu sĩ Nguyên Anh trong thành. Hàn Lập tìm một khe núi vắng vẻ, dựng trận pháp ẩn nấp và thi triển Thần Thức Hóa Thiên, chia thần thức thành hơn một ngàn thần niệm bám lên đàn Phệ Kim Trùng để giám sát phạm vi rộng. Một tuần sau, nhóm áo choàng đen do Bạch huynh dẫn đầu được thủ vệ mở cấm chế cho bí mật rời thành trong đêm. Khi cả nhóm đã đi xa, Bạch huynh phát hiện một Phệ Kim Trùng bám theo và dùng Bạch Ti Châm đánh nó rơi, nhưng hai thuộc hạ không tìm thấy xác linh trùng. Nhận ra mình đang bị cao nhân giám sát, nhóm áo choàng đen lập tức triển khai bích lục tiểu chùy cùng bạch ti hộ thân, còn Bạch huynh phóng khí thế và công khai gọi người theo dõi ra mặt."},{"chuong":1141,"tieuDe":"Chặn Giết","tomTat":"Nhóm tu sĩ che mặt do Diệu Hạc chân nhân và Hoàng Côn dẫn đầu bí mật rời Bích Linh đảo nhưng bị đàn Phệ Kim Trùng bao vây. Hàn Lập lộ diện, tuyên bố muốn giải quyết ân oán với Diệu Hạc và yêu cầu đối phương giao toàn bộ linh thạch đang mang theo. Diệu Hạc nhận ra hắn là người từng đoạt Hư Thiên Đỉnh, đồng thời kinh hãi khi cố nhân năm xưa đã đạt Nguyên Anh trung kỳ. Biết khó đối phó, Diệu Hạc và Hoàng Côn bí mật bàn kế bỏ mặc các đệ tử để chạy trốn, song cuộc truyền âm bị Hàn Lập nghe thấu. Hàn Lập lập tức dùng Phong Lôi Sí thi triển lôi độn áp sát, khiến Diệu Hạc phải dựng thuẫn bài phòng ngự và thúc giục ngọc chùy tấn công, còn Hoàng Côn kết bạch sắc quang ti thành lưới. Được tử sắc hỏa diễm bao phủ, Hàn Lập trực tiếp lao vào lưới quang ti, mở đầu cuộc giao chiến với hai tu sĩ Nguyên Anh sơ kỳ."},{"chuong":1142,"tieuDe":"Tin Tức Của Cực Âm","tomTat":"Hàn Lập dùng Tử sắc quang diễm áp chế tế châm, đóng băng Bích Ngọc Chuy và phong kín toàn thân Hoàng bào lão giả, đồng thời giết bốn tu sĩ Kết Đan đang chia nhau chạy trốn. Hắn tiếp tục dùng Tịch Tà thần Lôi phá thân thể đối phương, ngăn Nguyên Anh thuấn di rồi dùng phù triện phong bế linh lực. Diệu Hạc chân nhân bỏ chạy về phía Thạch Thành nhưng bị khôi lỗi hình người mai phục đánh trọng thương và bắt sống. Sau khi sưu hồn hai tù binh, Hàn Lập thu được hơn một trăm khối cao giai linh thạch và biết Nghịch Tinh Minh đang bí mật tập trung tài nguyên cùng lực lượng Nguyên Anh tại Bích Linh Đảo. Hắn còn phát hiện Cực Âm Tổ Sư hiện là trưởng lão trú trên đảo, phụ trách thủ hộ mạch khoáng. Vì mối đại thù cũ, Hàn Lập tạm hoãn việc trở lại nội hải và quyết định lẻn lên đảo giết Cực Âm Tổ Sư. Ba ngày sau, hắn tới vùng biển phụ cận Bích Linh Đảo."},{"chuong":1143,"tieuDe":"Âm Sát Huyết Thi","tomTat":"Hàn Lập tới ngoài Bích Linh Đảo và nhận ra dao động linh mạch của hòn đảo đã bị một thủ đoạn quy mô lớn che giấu. Đợi tới ban đêm, hắn dùng bí thuật ẩn độn, dựa vào ký ức lấy được từ nhóm Diệu Hạc để tránh các cấm chế và cảnh vệ của Nghịch Tinh Minh. Khi phát hiện cấm đoạn đại trận bao phủ ngọn núi đá trung tâm, hắn định dùng Tam Diễm Phiến cưỡng ép phá trận nhưng tạm dừng vì thấy Phí tiền bối dẫn hai nam tử áo trắng tới. Hàn Lập bám theo nhóm này qua khe trận, nghe được tin các tu sĩ được triệu tập sẽ hội họp tại Vân Yên điện vào hôm sau, trong khi Diệu Hạc và Hoàng Côn vẫn chưa tới. Một ma thi áo trắng bất ngờ cắn cổ, hút cạn máu một cảnh vệ Trúc Cơ, còn Phí tiền bối ngăn những người khác phản kháng rồi thiêu sạch thi thể cùng tinh hồn nạn nhân. Quan sát toàn bộ sự việc, Hàn Lập nhận ra hai nam tử áo trắng chính là Âm Sát Huyết Thi và biết việc nuôi loại ma thi này có thể khiến âm sát khí phản phệ chủ nhân."},{"chuong":1144,"tieuDe":"Tái Kiến Cực Âm","tomTat":"Hàn Lập nhận ra hai Âm Sát Huyết Thi đi theo một tu sĩ đầu bạc nhờ kiến thức trong luyện thi pháp quyết lấy từ Càn lão ma, nhưng không can thiệp khi đối phương chưa cản đường. Để xác định nơi ẩn náu của Cực Âm, hắn bắt một cảnh vệ Trúc Cơ kỳ của Nghịch Tinh Minh, cưỡng ép sưu hồn rồi diệt khẩu. Hàn Lập bí mật đột nhập lầu hắc thạch trên đỉnh núi, phá lớp âm khí bảo vệ và giết đệ tử Kết Đan đang canh giữ. Không tìm thấy Cực Âm trong lầu, hắn dùng Ngọc Như Ý hộ thân, phá màn sáng và tiến vào thông đạo bí mật dưới lòng núi. Tại đây, Minh Thanh Linh Mục giúp hắn phát hiện vật chất màu bạc trong đá xanh có khả năng giam giữ linh khí, qua đó giải thích vì sao quặng linh thạch từng bị che giấu. Cuối thông đạo, Hàn Lập bắt gặp Cực Âm đang dùng âm hỏa tra tấn một Nguyên Anh màu vàng. Cực Âm nhận ra hắn và nhớ tới Hư Thiên Đỉnh, lập tức hóa ma khí thành cự mãng tấn công, còn Hàn Lập vận kim sắc hồ quang nghênh chiến."},{"chuong":1145,"tieuDe":"Cầm Ma","tomTat":"Hàn Lập dùng Ích Tà Thần Lôi phá hắc mãng rồi lấy kim sắc Tiểu Kiếm chém gãy huyết sắc trường đao, khiến Cực Âm Tổ Sư nhận ra hắn đã đạt Nguyên Anh hậu kỳ. Nhắc lại ân oán năm xưa, Hàn Lập triệu Hư Thiên Đỉnh và tuyên bố sẽ khiến lão ma chết dưới chính bảo vật từng khiến mình bị truy sát. Cực Âm dốc Huyền Âm ma công và thập bát đô thi để phá vây, nhưng các luyện thi bị Kiền Lam Băng Diễm đóng băng rồi phá hủy. Lão tiếp tục dùng tinh huyết thi triển Thiên Bộ Thi Hỏa, song Hàn Lập vận Thông bảo quyết phong kín cửa đá và dùng thanh ti trói chặt đối phương. Ngọc bội của Cực Âm bị đoạt vào Hư Thiên Đỉnh, còn thi hỏa bị băng liên dập tắt trước khi toàn thân lão ma bị phong kín trong lam băng. Khi Hàn Lập chuẩn bị dùng phi kiếm kết liễu Cực Âm, một giọng nói quen thuộc tự xưng Man mỗ xin được tự tay báo thù cho cả tộc. Một Nguyên Anh màu vàng sau đó phá băng bay ra và đối diện Hàn Lập, nhưng danh tính thật vẫn chưa được xác nhận."},{"chuong":1146,"tieuDe":"Trao Đổi","tomTat":"Hàn Lập nhận ra Nguyên Anh vừa thoát khỏi cấm chế của Cực Âm Tổ Sư chính là Man Hồ Tử và lập tức khống chế đối phương để đề phòng bỏ trốn. Man Hồ Tử cho biết mình đã gần cạn tinh nguyên, đồng thời kể lại việc bị người gọi là gia hỏa lục đạo dùng Lục Cực Chân Ma Công đánh trọng thương, rồi bị Cực Âm hủy thân thể và giam giữ hơn trăm năm. Cực Âm dùng bí thuật kéo dài sự tồn tại của Nguyên Anh để tra hỏi Bổ Thiên Đan cùng tài vật, nhưng Thiên Ma công giúp Man Hồ Tử giữ chặt thần niệm và chống cưỡng ép sưu hồn. Do hồn lực gần cạn và đứng trước nguy cơ mất cơ hội luân hồi, Man Hồ Tử xin được cắn nuốt tinh nguyên Nguyên Anh Cực Âm để thử tìm đường chuyển thế. Hắn đề nghị đổi Thiên Ma công, Khóa Hồn Bí Thuật, tài liệu quý hiếm và vị trí kho cất giấu lấy quyền xử trí Cực Âm. Hàn Lập đồng ý sau khi nhắc lại Hoàng Lân giáp từng cứu mạng mình và coi ân oán cũ với Man Hồ Tử đã được xóa bỏ. Man Hồ Tử cũng xác nhận Bổ Thiên Đan đã được dùng từ lâu nhưng hiệu quả rất ít, còn Cực Âm vì hiểu lầm đan vẫn tồn tại nên mới kiên trì tra hỏi. Cuối cùng, Hàn Lập hỗ trợ Man Hồ Tử ổn định trạng thái và nhận một phần khẩu quyết Thiên Ma công được sao chép vào ngọc giản."},{"chuong":1147,"tieuDe":"Loạn Khởi","tomTat":"Hàn Lập dùng thần niệm xem ngọc giản Thác Thiên Ma Công và nhận ra điểm khác thường khiến hắn từ kinh ngạc chuyển sang kinh hỉ, nhưng không giải thích phát hiện của mình cho Man Hồ Tử. Sau khi nói rõ lai lịch truyền thừa đơn mạch của công pháp, Man Hồ Tử cắn nuốt Nguyên Anh Cực Âm Tổ Sư để báo thù, bí mật truyền vị trí động phủ cho Hàn Lập rồi tọa hóa giữa những điểm kim quang. Hàn Lập dùng kim sắc lôi điện phá nát thân xác Cực Âm, kiểm tra không còn phân hồn hay đệ nhị nguyên thần rồi thiêu sạch tàn tích. Khi hắn phá mật môn trở lại tầng một Giản Lâu, một tu sĩ Kết Đan của Nghịch Tinh Minh xông vào báo tin có yêu thú tập kích và lập tức bị hắn chém đôi. Hàn Lập thu liễm khí tức, che giấu hành tung rồi quan sát chiến trường hỗn loạn quanh Thiết Thạch Phong. Tại đó, nhiều Hải tộc hóa hình đang giao chiến với lực lượng Nghịch Tinh Minh, còn Đầu Đà béo công khai ép Đường tính lão giả giao Đỉnh giai Cực Phẩm Linh Thạch. Đường tính lão giả vừa dùng gương xanh và phi kiếm lam chống trả vừa phủ nhận đang sở hữu linh thạch, khiến cuộc đối đầu tiếp tục căng thẳng."},{"chuong":1148,"tieuDe":"Kim Giao Vương","tomTat":"Bàn Tử thừa nhận phe Hải tộc đã sát hại và sưu hồn Lý hộ pháp để lấy tin về cực phẩm linh thạch, đồng thời tuyên bố toàn bộ lực lượng tinh nhuệ đã được huy động nhằm thu hồi đảo linh quặng. Khi yêu vụ cùng đại quân yêu thú kéo tới bao vây, các tu sĩ cấp thấp của Nghịch Tinh Minh phân tán tháo chạy, còn tu sĩ Nguyên Anh vừa chống đỡ vừa tìm đường phá vây. Hàn Lập nghe tin cực phẩm linh thạch liền từ bỏ ý định rời đi, tiếp tục ẩn thân để chờ yêu thú ép người giữ bảo vật lộ diện rồi ra tay cướp lấy. Kim Giao Vương, một Giao Long yêu tu thập cấp đại thành, xuất hiện với kim giáp và kim thương rồi dùng thần niệm bao phủ toàn bộ thạch lĩnh. Hắn tuyên bố nhân tộc đã ba nghìn năm không xuất hiện tu sĩ Hóa Thần nên ước định cũ không còn đáng tuân thủ trước lợi ích của đỉnh bậc linh thạch. Hàn Lập nhận ra Quy Yêu trong nhóm đi cùng Kim Giao Vương nhưng kiềm chế không dò xét để tránh bại lộ. Trong lúc giao chiến với Bàn Tử, Đường tính lão giả tự bạo lam sắc phi kiếm cổ bảo để mở đường, sau đó dùng cẩm khăn màu tím hóa thành tử hồng lao khỏi vòng chiến."},{"chuong":1149,"tieuDe":"Kim Giao Hung Diễm","tomTat":"Kim Giao Vương dùng Kim Thương truy kích Đường tính lão giả, liên tiếp phá thanh nguyệt và tử quang hộ thân của đối phương. Khi lão giả phun viên châu xanh biếc phản kích, yêu vương thi triển Hóa Long Quyết, khiến bàn tay mọc móng cùng vảy vàng rồi bóp nát pháp bảo, làm chủ nhân của nó chịu phản phệ. Kim Giao Vương tiếp tục đánh lão xuyên qua lầu các, dùng Kim Thương xuyên ngực rồi biến móng tay thành đinh vàng ghim tứ chi và phong ấn cả Nguyên Anh. Hàn Lập ẩn gần đại môn từng định bắt lão giả để tìm cực phẩm linh thạch nhưng kịp từ bỏ, sau đó âm thầm dịch chuyển tránh trảo mang khi Kim Giao Vương cảm ứng được nguy hiểm. Không tìm thấy vật cần thiết trong túi trữ vật của tù binh, Kim Giao Vương để một yêu tu bát cấp vảy lam lại giám thị Thạch Phong rồi đích thân truy đuổi người đang hóa thành huyết vụ đào tẩu. Cuối chương, yêu tu vảy lam và Hàn Lập cùng phát hiện một đạo hoàng quang đang bay tới, bên trong có yêu thú dường như bưng theo một vật; Hàn Lập lập tức dùng Minh Thanh Linh Mục quan sát."},{"chuong":1150,"tieuDe":"Đoạt Bảo","tomTat":"Hàn Lập nhận ra túi trữ vật do yêu thú bốn tay mang theo chứa vật mình cần, liền dùng Phong Lôi Sí áp sát, giết yêu thú và đoạt lấy cực phẩm linh thạch. Bát cấp yêu tu mặt lam nhạt đòi hắn trả linh thạch nhưng bị mộc thước xanh biếc triệu Phật quang phong bế, sau đó mất mạng dưới kim quang; đoàn lục hỏa thoát khỏi thi thể cũng bị Hàn Lập thu giữ. Tiếng cầu viện khiến hai Hóa hình yêu tu bỏ đôi tu sĩ nam nữ đang giao chiến, trong khi Kim Giao Vương cùng số đông yêu thú quay lại chiến trường. Thấy linh thạch đã vào tay và viện quân yêu tộc đang hội tụ, Hàn Lập quyết định không mạo hiểm thêm mà lập tức rút lui. Hai Hóa hình yêu tu huyễn hóa phong giao ngăn đường nhưng không theo kịp, còn kim thương của Kim Giao Vương bị Hàn Lập dùng tiểu thuẫn chặn và phản chấn. Trên đường thoát đi, hắn chạm mặt Quy yêu; đối phương hoảng sợ đổi hướng né tránh, nhưng thanh hồng của Hàn Lập bất ngờ biến mất ngay trước mắt nó."},{"chuong":1151,"tieuDe":"Cực Phẩm Linh Thạch","tomTat":"Hàn Lập hiện thân gần Quy yêu, dùng ba mươi sáu tiểu kiếm dựng kiếm võng và đánh thẳng vào thần thức khiến đối phương không thể thi triển độn thuật. Quy yêu nhận ra hắn là tu sĩ họ Lệ năm xưa và gọi Kim Giao Vương cầu cứu, nhưng lập tức bị chém nát cả thân xác lẫn yêu hồn. Hàn Lập rời khỏi Bích Linh Đảo, còn Kim Giao Vương truy đuổi không kịp và phải quay lại. Từ lời cuối của Quy yêu cùng tin tức về Hư Thiên Đỉnh, các yêu tu nghi Hàn Lập chính là tu sĩ họ Hàn từng dùng tên giả họ Lệ và đánh giá cần nhiều cường giả hợp lực mới có thể đối phó hắn. Hải tộc tạm gác việc báo thù, củng cố quyền kiểm soát mỏ linh quặng Bích Linh Đảo và chuẩn bị chống Nghịch Tinh Minh cùng Tinh Cung phản công. Trên đường bay về Ngân Sa Đảo, Hàn Lập lấy khối linh thạch xanh ra kiểm tra, xác nhận đó là cực phẩm linh thạch Mộc thuộc tính rồi bắt đầu thử hấp thu linh khí bên trong."},{"chuong":1152,"tieuDe":"Trở Về Ngân Sa Đảo","tomTat":"Hàn Lập thử hấp thu linh khí từ cực phẩm linh thạch và nhận thấy chỉ một lần ngắn ngủi đã tương đương nửa tháng khổ tu, nhưng hắn vẫn cất vật này để dành cho lúc phá bình cảnh. Sau vài tháng phi hành, hắn trở lại vùng biển quanh Ngân Sa đảo và phát hiện đảo đã mở đại trận phòng hộ vì vừa bị yêu thú tập kích. Tại cửa vào, một tu sĩ Kết Đan của Tinh Cung dùng thần niệm kiểm tra hắn nhưng bị phản chấn, rồi giải thích rằng mọi người trở về đều phải xác minh thân phận. Hàn Lập xuất trình Khách khanh Đồng lệnh bài do Thiên Tinh Song Thánh cấp và được cho vào đảo. Hắn biết Tinh Cung đã phổ biến dung mạo của mình cho các đệ tử đóng quân tại đây, trong khi Trữ trưởng lão đã ra ngoài điều tra nguyên nhân đàn yêu thú tấn công. Triệu trưởng lão, người đã chờ hắn nhiều tháng theo lệnh Song Thánh, đưa hắn tới một ngọn núi nhỏ để nói chuyện riêng. Cuộc trao đổi kết thúc ở câu hỏi bất ngờ về việc thọ nguyên của Hàn Lập có còn chưa tới một trăm năm hay không, còn nội dung đại hảo sự mà Tinh Cung muốn đề nghị vẫn chưa được tiết lộ."},{"chuong":1153,"tieuDe":"Song Tu Chi Sự","tomTat":"Triệu trưởng lão thay mặt Tinh Cung đề nghị Hàn Lập kết thành bạn lữ song tu với Lăng Ngọc Linh, đồng thời đưa quyền kế nhiệm Tinh Cung ra làm điều kiện. Hàn Lập dứt khoát khước từ vì đã có một bạn lữ mang tu vi Nguyên Anh. Triệu trưởng lão sau đó chuyển lời mời của Thiên Tinh Song Thánh, muốn gặp Hàn Lập để trao đổi về cửa ải đột phá Hóa Thần. Hàn Lập chấp nhận và chọn một đảo san hô vô danh cách phía bắc Tinh Thành ba nghìn dặm làm nơi gặp sau ba ngày. Hắn nhận Truyền Tống Phù từ Phi Phát tu sĩ rồi dùng Truyền Tống Trận trở về nội hải, trong khi những tu sĩ trông trận hiểu sai cảnh giới và địa vị của hắn. Đến ngày hẹn, Hàn Lập dùng thần niệm kiểm tra kỹ vùng biển quanh đảo vì kiêng dè khả năng liên thủ cùng Nguyên Từ Thần Quang của Song Thánh. Gần giữa trưa, hai đạo độn quang xuất hiện ở cuối chân trời và bay thẳng về phía đảo."},{"chuong":1154,"tieuDe":"Điều Kiện Của Song Thánh","tomTat":"Hàn Lập hội kiến Thiên Tinh Song Thánh, gồm Ôn Thanh và phu quân Lăng Khiếu Phong, trên vùng biển ngoài tiểu đảo. Từ thông tin về đạo lữ của hắn, Lăng Khiếu Phong suy đoán Hàn Lập đến từ Đại Tấn và tiết lộ Tinh Cung đang kiểm soát một thượng cổ Truyền Tống Trận bí mật nối hai khu vực. Để đổi lấy bí thuật cùng tâm đắc đột phá Hóa Thần, Song Thánh trước hết muốn Hàn Lập bảo hộ Lăng Ngọc Linh lâu dài, nhưng hắn từ chối vì việc này có thể kéo dài hàng trăm năm. Hắn cũng không chấp nhận liên thủ giết Lục Đạo Cực Thánh và Vạn Tam Cô vì hai người đều là đại tu sĩ lâu năm, đồng thời khẳng định không muốn can dự vào tranh chấp tại Loạn Tinh Hải. Sau khi tiếp tục thương lượng, hai bên thống nhất Hàn Lập sẽ cứu viện Lăng Ngọc Linh ba lần khi tính mạng nàng bị đe dọa và tình thế nằm trong khả năng của hắn. Lăng Khiếu Phong chia ba tấm Vạn Lý Phù thành sáu nửa, giao ba nửa cho Hàn Lập làm phương tiện cầu viện, còn hắn kiểm tra rồi cất chúng vào túi trữ vật."},{"chuong":1155,"tieuDe":"Yêu Thú Chi Loạn","tomTat":"Ôn Thanh trao cho Hàn Lập Bích Lục Ngọc Giản chứa tâm đắc và nhiều bí thuật đột phá Hóa Thần do Thiên Tinh Song Thánh tổng kết; sau khi xác nhận nội dung là thật, Hàn Lập nhận vật rồi rời đi. Khi hắn đã đi xa, Ôn Thanh và Lăng Khiếu Phong thừa nhận phương pháp khả quan nhất sẽ dẫn tới Nguyên Từ Thần Quang, qua đó buộc người tu phải dựa vào Nguyên Từ Sơn và khó rời Tinh Thành. Hai người còn chuẩn bị truyền phương pháp tế luyện thần sơn cho Lăng Ngọc Linh, tìm đạo lữ song tu cùng đan dược để giúp nàng tiến lên Nguyên Anh hậu kỳ và duy trì quyền chấp chưởng Tinh Cung. Trước biến động ngoại hải, họ định lợi dụng mâu thuẫn giữa Giao Long Nhất Tộc và Toan Oản Vương Tộc, đồng thời tập trung lực lượng tại nội hải nhưng vẫn mở Truyền Tống Trận để tán tu cùng Nghịch Tinh Minh ra giao chiến với yêu thú. Bích Linh đảo đã bị cao giai yêu tu chiếm vì mạch khoáng xuất hiện Cực Phẩm Linh Thạch, Quế trưởng lão bị Kim Giao Vương giết và lực lượng từng xuất phát từ Ngân Sa đảo gần như bị tiêu diệt. Sau tối hậu thư buộc nhân loại rời các đảo ngoại hải trong một tháng, Tinh Cung, Nghịch Tinh Minh, các thế lực và vô số tán tu đồng loạt đưa người ra ngoài, trong khi yêu thú cũng tập kết dày đặc quanh Bích Linh đảo. Thiên Tinh Song Thánh dự tính chờ Nghịch Tinh Minh hao tổn rồi ra tay nhổ tận gốc, đồng thời tiết lộ từ lực Nguyên Từ Sơn sẽ biến mất một tháng sau mỗi chu kỳ trăm năm, cho phép họ rời Tinh Thành để thanh toán Lục Đạo và Vạn Tam Cô. Giữa lúc đại chiến nhân yêu sắp bùng nổ, tin đồn Hư Thiên Đỉnh tái hiện cùng linh đan giúp tu sĩ tăng tiến tu vi cực nhanh bất ngờ lan khắp Loạn Tinh Hải."},{"chuong":1156,"tieuDe":"Ma Hồ Đảo","tomTat":"Ma Hồ Đảo là một tiểu đảo hẻo lánh gần Nội Tinh Hải, nổi tiếng trong phạm vi nhỏ nhờ Ma Hồ sản sinh tài liệu luyện khí Thúy Đồng. Quanh hồ, năm sáu chục tu sĩ cấp thấp đang bố trí một pháp trận phức tạp theo sự thuê mướn của ba đệ tử Man Hồ Tử gồm Ngô sư huynh, Huyết Thủ Ma và Thái sư tỷ. Trong lúc chờ phá tầng cấm chế cuối cùng, Ngô sư huynh kể rằng Kim Minh Lâu đã suy yếu, còn Huyết Thủ Ma chất vấn nguồn gốc tin tức về động phủ tàng bảo. Thái sư tỷ phô bày Tử Băng Trạc khiến hai đồng môn phải kiêng dè, rồi tiết lộ mình từng là thị thiếp của Man Hồ Tử và nghe được vị trí động phủ qua lời nói mê của ông. Ngô sư huynh ra bờ hồ kiểm tra pháp trận, Huyết Thủ Ma lặn xuống đáy hồ xem xét, trong khi Thái sư tỷ âm thầm để lộ vẻ lạnh lẽo. Khi ba người vừa tụ họp trở lại và chuẩn bị phá cấm, một đạo thanh hồng chói mắt bất ngờ lao thẳng về phía Ma Hồ."},{"chuong":1157,"tieuDe":"Kim Hoa Lão Tổ","tomTat":"Hàn Lập tới Ma Hồ Đảo và nhanh chóng nhận ra các tu sĩ bên hồ đang vận hành một pháp trận bài trừ cấm chế chứ không đơn thuần vớt Thúy Đồng. Từ dấu vết Thiên Ma Công, hắn xác định Ngô sư huynh, Thái sư muội và Huyết Thủ Ma đều là đệ tử của Man Hồ Tử, đồng thời vạch trần mục tiêu bảo khố dưới đáy hồ. Hàn Lập sau đó phát hiện Kim Hoa Lão Tổ ẩn trong ngọn đồi gần đó, dùng thanh quang buộc lão phải tung kim thuẫn và kim trảo chống đỡ rồi hiện thân. Thái sư muội lập tức đứng về phía Kim Hoa Lão Tổ, công khai phản bội hai đồng môn và vạch trần những kế hoạch riêng mà họ chuẩn bị để độc chiếm bảo vật. Nàng cho biết Kim Hoa Lão Tổ đã bố trí nhân thủ chặn lực lượng bên ngoài, đồng thời hứa cưới nàng sau khi thành công. Dù không nhìn thấu tu vi Hàn Lập, Kim Hoa Lão Tổ vẫn chất vấn mục đích của hắn. Hàn Lập thẳng thừng tuyên bố toàn bộ đồ dưới đáy hồ là mục tiêu của mình và yêu cầu đối phương rời đi, khiến xung đột giữa hai bên trở nên trực tiếp."},{"chuong":1158,"tieuDe":"Kim Hoa, Quỷ Cưu","tomTat":"Kim Hoa Lão Tổ nhận thấy Hàn Lập quen mắt nên từ bỏ ý định tranh giành địa điểm và định đưa diễm lệ nữ tử rời đi. Hàn Lập đoán đối phương đã nhận ra mình và biết chuyện Hư Thiên Đỉnh, vì vậy lập tức ra tay diệt khẩu. Kim Hoa Lão Tổ dùng kim phù, Kim Sắc Thuẫn Bài và Kim Sắc Tiểu Chung chống đỡ, nhưng Hàn Lập vẫn dùng thần niệm cùng Thanh Nguyên Kiếm Khí ép hắn hiện hình. Đại hán gọi Quỷ Cưu đã được tế luyện bằng Quỷ Tu Bí Thuật ra giao chiến, rồi tự chặt hai đoạn ngón tay để dùng huyết quang kích thích quỷ cầm. Đề Hồn Thú hóa thành cự viên, dùng hoàng sắc hà quang thu Quỷ Cưu thành hắc khí và nuốt vào bụng. Sau đó đôi Lục Sắc Ngọc Câu bị kim kiếm đánh vỡ, còn Kim Sắc Tiểu Chung dần không ngăn nổi Hàng Ma Trượng. Kim Hoa Lão Tổ lại kích phát kim phù bỏ chạy, nhưng Hàn Lập đã chuẩn bị Phong Lôi sí và lập tức biến mất để truy theo."},{"chuong":1159,"tieuDe":"Diệt Sát","tomTat":"Kim Hoa Lão Tổ tìm cách độn vào hư không nhưng bị Hàn Lập đánh bật, buộc phải dùng Kim Phù hóa thành đàn độc phong để cản đường rồi tháo chạy. Hàn Lập dùng Hư Thiên Đỉnh thu hết độc phong, đồng thời phái mười tám con Lục Dực Sương Công chia thành ba nhóm truy kích ba đệ tử của Man Hồ Tử đang bỏ trốn. Hắn vận dụng Phong Lôi Sí đuổi kịp Kim Hoa Lão Tổ, lấy Tử La Cực Hỏa đóng băng pháp bảo, hủy thân thể và tiêu diệt cả Nguyên Anh của đối phương. Sau khi thu túi trữ vật của Kim Hoa Lão Tổ, Hàn Lập chờ ba nhóm linh trùng lần lượt trở về với những dấu vết cho thấy chúng đã trải qua giao chiến. Hắn thu hồi toàn bộ linh trùng cùng Đề Hồn Thú rồi lặn xuống Ma Hồ. Dù thị lực và thần niệm đều bị nước hồ xanh biếc hạn chế, Hàn Lập vẫn dựa vào vị trí Man Hồ Tử cung cấp để tìm thấy một dải đá ngầm bình thường dưới đáy hồ."},{"chuong":1160,"tieuDe":"Ngân Khoa Văn Tự","tomTat":"Hàn Lập phá lớp huyễn thuật che giấu đá ngầm rồi phối hợp với khôi lỗi hình người cưỡng ép đánh tan cấm chế Ngũ Hành do Man Hồ Tử để lại. Trước khi dùng truyền tống trận tiến vào động phủ, hắn thả phần lớn Lục Dực Sương Công canh giữ đường lui và dùng thần thức xác nhận bên trong không có người ẩn nấp. Tàng bảo trong động phủ đem lại cho hắn nhiều linh thạch, bảo vật, điển tịch bí thuật và đặc biệt là khối Canh Tinh đủ để khảm toàn bộ bảy mươi hai phi kiếm, mở đường tạo thành Đại Canh kiếm trận. Trên đường rời đi, Hàn Lập lấy kim phù của Kim Hoa Lão Tổ từ Hư Thiên Đỉnh ra nghiên cứu và phát hiện những ký tự màu bạc kỳ lạ ở bốn góc. Đồng tử trú trong đỉnh nhận diện chúng là Ngân Khoa văn, một hệ chữ hiếm người hiểu ngay cả tại Linh Giới. Biết Hàn Lập đang có linh vũ Du Thiên Côn Bằng, Đồng tử thay đổi thái độ và chủ động đề nghị hai bên tiến hành giao dịch. Cuộc đối đáp sau đó cũng xác nhận Đồng tử hiện chỉ là phân thần của một yêu tu Linh Giới, mang tu vi bát cấp yêu thú tại Nhân Giới và còn rất xa mới khôi phục Hóa Thần kỳ."},{"chuong":1161,"tieuDe":"Côn Bằng Chi Vũ","tomTat":"Phân thân Thiên Giải Thánh Thú trong Hư Thiên Đỉnh đã khai mở linh trí và khôi phục phần lớn ký ức sau hơn trăm năm bị giam giữ. Hàn Lập nhớ lại rằng sau khi luyện thông tầng thứ hai của Thông Thiên Bảo Quyết, hắn mở được nắp đỉnh, nhưng phân thân dù dùng độn thuật chạy thoát vẫn bị kéo trở lại vì khí tức đã bị đỉnh đồng hóa. Thánh thú tiết lộ bản thể tại Linh Giới đã đưa phân thần xuống Nhân Giới để giữ một đường sống trước đại kiếp, đồng thời giải thích phương pháp vượt giới cần Hóa Giới Thạch và có xác suất thành công cực thấp. Khi Hàn Lập cân nhắc hạ sát, nó cảnh cáo có thể gieo ấn ký vào nguyên thần để bản thể truy tìm hắn sau khi phi thăng, khiến hắn phải từ bỏ ý định ra tay ngay lúc đó. Sau đó, thánh thú xác nhận chiếc linh vũ trong tay Hàn Lập rơi từ Du Thiên Côn Bằng trong cuộc giao thủ cách giới với La Miên Thú và chứa lực Phong cùng dấu vết thiên địa pháp tắc. Nó cũng hé lộ Hỗn Độn Vạn Linh Bảng là chuẩn xếp hạng Thông Thiên Linh Bảo chân chính tại Linh Giới. Cuối cùng, phân thân đề nghị truyền cho Hàn Lập phương pháp dùng Côn Bằng Linh Vũ hoàn thiện Phong Lôi Sí, nhưng điều kiện giao dịch chưa được công bố."},{"chuong":1162,"tieuDe":"Kim Khuyết Ngọc Thư","tomTat":"Hàn Lập chấp thuận giao ước với Thiên Lan Thánh Thú phân thân: hắn sẽ giải trừ sự đồng hóa của Hư Thiên Đỉnh trước khi tọa hóa hoặc phi thăng, đồng thời bảo vệ và trợ giúp đối phương vượt Lôi kiếp hóa hình, còn thánh thú sẽ truyền Ngân Khoa Văn cùng phương pháp luyện chế. Khi kiểm tra di vật của Kim Hoa Lão Tổ, Hàn Lập không tìm được ghi chép về kim phù nhưng phát hiện một hộp gỗ phong kín nửa khối ngọc bài màu trắng ngà. Ngọc bài vừa được lấy ra liền hóa thành ngân mang bỏ chạy, song bị Hàn Lập dùng thanh quang áp chế và bắt lại. Thiên Lan Thánh Thú kinh hãi nhận ra đó là tàn trang Kim Khuyết Ngọc Thư, một tiên gia chi vật lưu truyền từ Tiên giới. Nó giải thích toàn bộ ngọc thư có 108 trang, gồm 36 trang Nội thư ghi công pháp tu luyện và 72 trang Ngoại thư ghi phù lục, trận pháp, luyện đan, chế khí cùng tạp học. Các trang Nội thư từng gây nên cuộc tranh đoạt kéo dài hàng vạn năm tại Linh giới và được đồn là con đường phi thăng Tiên giới, nhưng công pháp chỉ phù hợp với Nhân Tộc, khiến Yêu Tộc phải từ bỏ sau nhiều lần chịu tổn thất. Hàn Lập tiếp tục chất vấn căn cứ xác định bộ hài cốt từng mang ngọc thư là Tiên Nhân, nhưng thánh thú chỉ có thể viện dẫn nhận định của các tiền bối đại thần thông hai tộc."},{"chuong":1163,"tieuDe":"Trọng Lâm Cố Địa","tomTat":"Thiên Lan Thánh Thú phân thân giải thích rằng ngoại thư Kim Khuyết Ngọc Thư được viết bằng Ngân Khoa Văn, còn nội thư dùng Kim Mô Văn, nhờ đó Hàn Lập xác định tàn trang trong tay thuộc ngoại thư. Hai bên thỏa thuận rằng phân thân thánh thú sẽ truyền dạy linh văn cho Hàn Lập để đổi lấy quyền mượn tàn thư và cùng chia sẻ tâm đắc nghiên cứu. Trong hai tháng đi tới Nại Tinh Đảo, Hàn Lập học được khoảng bảy tám phần Ngân Khoa Văn. Trên đường, hắn ghé lại Tiểu Hoàn Đảo, hồi tưởng thời mình còn là tu sĩ cấp thấp trước khi tiếp tục hành trình. Tới Nại Tinh Đảo, hắn không đi qua bến cảng mà cưỡng ép xuyên qua bạch vụ cấm chế, khiến nhóm tu sĩ Trúc Cơ trấn thủ tìm kiếm nhưng không phát hiện được dấu vết. Hàn Lập dùng pháp bàn dò tìm rồi tới Cố Gia Trang, nơi hắn gặp hai đệ tử của vợ chồng Văn Tư Nguyệt và biết họ đang tạm trú trên một ngọn núi gần đó. Sau khi nhắc lại cơ duyên với gia chủ Cố gia hơn hai trăm năm trước và yêu cầu hậu nhân Cố gia tới gặp, hắn dùng thần niệm xác định khí tức của vợ chồng Văn Tư Nguyệt rồi lập tức bay tới."},{"chuong":1164,"tieuDe":"Trở Về Thiên Nam","tomTat":"Hàn Lập tới động phủ của gia đình Văn Tư Nguyệt và nhận thấy Điền Cầm Nhi đã giải độc, khôi phục dung mạo. Ông tuyên bố sẽ kiểm tra khả năng lĩnh ngộ trận pháp của nàng và chỉ thu làm đệ tử nếu kết quả khiến mình hài lòng. Sau một ngày một đêm, một đạo thanh hồng mang theo một nam một nữ rời khỏi ngọn núi. Một tháng sau, bối cảnh chuyển tới linh quáng của Quỷ Linh Môn tại Việt Quốc, nơi Mạnh sư đệ tới thay Phạm sư huynh trấn giữ. Qua cuộc trò chuyện, Mạnh sư đệ cho biết Quỷ Linh Môn đã suy yếu và phải tập trung lực lượng đề phòng Ngự Linh Tông cùng Ma Diễm Môn. Phạm sư huynh dẫn hắn tới cấm địa cũ chứa Thượng cổ Truyền Tống Trận, đồng thời tiết lộ đầu trận tại Thiên Nam vẫn nguyên vẹn nhưng phía bên kia đã xảy ra vấn đề. Sau khi xem xét trận pháp, Mạnh sư đệ buông lời sát ý và Phạm sư huynh lập tức bị một đạo kiếm quang chém rơi đầu."},{"chuong":1165,"tieuDe":"Gặng Hỏi","tomTat":"Một nhóm tu sĩ Trúc Cơ của Ma Diễm Môn dùng Liễm Tức Phù giả làm đệ tử Luyện Khí, phối hợp với Mạnh sư đệ phản bội Quỷ Linh Môn để sát hại người trông coi động phủ. Qua cuộc trò chuyện của chúng, Quỷ Linh Môn được tiết lộ là đã suy yếu nặng và đang bị Ma Diễm Môn, Ngự Linh Tông cùng Huyết Sát Tông liên thủ tiến công. Khi nhóm xâm nhập định rời đi, Truyền Tống Trận bất ngờ vận hành và đẩy bật mọi pháp khí đang cố phá trận. Hàn Lập cùng Điền Cầm Nhi xuất hiện sau chuyến truyền tống từ Loạn Tinh Hải, nhưng lập tức bị trung niên tu sĩ Ma Diễm Môn ra lệnh tập kích. Hàn Lập phá nát toàn bộ pháp khí rồi dùng kim sắc kiếm khí giết sạch nhóm Ma Diễm Môn, chỉ tha Mạnh sư đệ vì người này đã lên tiếng ngăn đồng bọn. Sau khi xác nhận thân phận của kẻ sống sót, Hàn Lập ép hắn thuật lại những đại sự tại Thiên Nam trong một trăm năm, trong đó có việc Huyền Diệu Môn bị Hỏa Linh Tông diệt môn. Cuối cùng, Hàn Lập hỏi riêng tình hình Lạc Vân Tông và chỉ nhận được tin chưa chắc chắn rằng một vị Lữ tiền bối dường như đang chấp chưởng tông môn."},{"chuong":1166,"tieuDe":"Hóa Vũ Môn","tomTat":"Sau khi xác nhận Trình trưởng lão đã tọa hóa, Hàn Lập đánh ngất đại hán họ Mạnh, phá hủy cổ truyền tống trận nối với Loạn Tinh Hải rồi sửa ký ức người này để che giấu thân phận và nguyên nhân trận bị phá. Hắn thiêu hủy thi thể các tu sĩ Ma Diễm Môn, đưa Điền Cầm Nhi rời động quật và xóa thêm dấu vết, trong khi về sau Ma Diễm Môn liên kết hai tông môn khác tập kích Quỷ Linh Môn. Trên đường tới Khê Quốc, Hàn Lập đi qua Nguyên Vũ Quốc và tạm đổi lộ trình để trở lại ngọn núi nơi Tân Như Âm từng ẩn cư. Nơi đây đã trở thành địa bàn của Hóa Vũ Môn, trúc lâu cũ không còn và nhiều lầu các đã được dựng lên. Hàn Lập dùng một hỏa cầu phá thủng cấm chế, buộc Quan Thanh cùng hắc phu lão giả dẫn môn nhân ra nghênh tiếp. Khi nhận ra hắn là đại tu sĩ Nguyên Anh hậu kỳ, hai người lập tức kính sợ và cho biết môn phái do Hoàng Dược Chân Nhân đứng đầu đã chuyển tới đây từ bảy mươi hai năm trước. Trước câu hỏi về những cư dân cũ, Quan Thanh gọi Phụng Chí tới trả lời, nhưng lão giả Trúc Cơ này vừa xuất hiện đã lộ vẻ hoảng hốt."},{"chuong":1167,"tieuDe":"Kiếp Trước, Kiếp Này?","tomTat":"Theo lệnh của nho sinh, Phụng Chí tới gặp Hàn Lập và được xác nhận là hậu nhân của Tiểu Mai, đồng thời nhận ra Hàn Lập chính là người từng tặng Trúc Cơ Đan cho mẹ mình. Khi biết Hóa Vũ Môn đang tạm trú tại nơi ở cũ của bạn mình, Hàn Lập yêu cầu toàn bộ môn phái rời đi, khiến hai tu sĩ Kết Đan lập tức cho hàng trăm đệ tử thu dọn. Sau khi Hàn Lập rời khỏi, hai người suy đoán hắn là đại tu sĩ thứ tư mới xuất hiện tại Thiên Nam. Phụng Chí tiếp đó dẫn Hàn Lập và Điền Cầm Nhi tới trúc lâu cũ của Tân Như Âm, nơi Điền Cầm Nhi bất ngờ rơi vào trạng thái mơ màng và hành động như đã quen thuộc mọi đồ vật. Hàn Lập ở lại quan sát nàng suốt một ngày rồi rời đi, đồng thời để lại cho Phụng Chí một bình đan dược. Khi đã đi xa, Điền Cầm Nhi hỏi về quan hệ giữa mình với trúc lâu, còn Hàn Lập trực tiếp nêu ra khả năng liên quan tới luân hồi cùng kiếp trước, kiếp này, khiến nàng biến sắc."},{"chuong":1168,"tieuDe":"Hồi Tông","tomTat":"Hàn Lập kể cho Điền Cầm Nhi về Tân Như Âm, người từng mang Long Ngâm Chi Thể và có thiên phú trận pháp tương tự nàng, từ đó cho biết mình có năm phần tin rằng nàng là Tân Như Âm chuyển thế. Dù không nhớ tiền kiếp, Điền Cầm Nhi vẫn quyết tâm bái sư, còn Hàn Lập hứa sẽ chính thức thu nàng làm môn hạ sau khi trở về Lạc Vân Tông và bồi dưỡng nàng thành trận pháp đại sư. Sau nhiều tháng lên đường, hai người tới Vân Mộng Sơn Mạch; vì xúc động trước lúc gặp lại Nam Cung Uyển, Hàn Lập phát tiếng thét dài kinh động cả ba tông. Lữ Lạc, Hỏa Long đồng tử, trưởng lão họ Phùng và hai trưởng lão Nguyên Anh mới tới nghênh đón, đồng thời xác nhận Hàn Lập đã tiến giai Nguyên Anh hậu kỳ. Người của Cổ Kiếm Môn và Bách Xảo Viện hẹn ba ngày sau tới Lạc Vân Tông bái kiến, còn Lữ Lạc báo rằng tông môn tuy phát triển nhờ uy danh Hàn Lập nhưng chưa có thêm tu sĩ Nguyên Anh. Điền Cầm Nhi hành lễ với Lữ Lạc và được ông trao một pháp khí hộ thân hình tinh cầu phát hồng quang. Trên đường về tông, Hàn Lập biết Trình trưởng lão đã tọa hóa, còn Nam Cung Uyển từng tỉnh lại nhưng vẫn ở trong động băng tu luyện nên chưa thích hợp giải khai phong ấn."},{"chuong":1169,"tieuDe":"Trụy Ma Dị Biến","tomTat":"Hàn Lập trở về Lạc Vân Tông với tu vi Nguyên Anh hậu kỳ và được hàng trăm môn nhân long trọng nghênh đón tại sơn môn. Lữ Lạc lập tức chuẩn bị đại điển nhằm công bố địa vị đại tu sĩ của hắn, qua đó đưa Lạc Vân Tông vào hàng siêu cấp tông môn tại Thiên Nam. Hàn Lập biết Tống Ngọc, Liễu Ngọc và Mộ Phái Linh đã vào ngoại vi Trụy Ma Cốc tìm linh thảo, đồng thời nhận ra kế hoạch cũ dành cho Mộ Phái Linh không còn phù hợp sau khi nàng tiến lên Kết Đan trung kỳ. Hắn tới cấm địa và gặp lại Nam Cung Uyển, người đã khôi phục dung mạo rồi tỉnh lại trong màn băng bích. Ở vùng sâu Trụy Ma Cốc, một ma thi đã hấp thu ma khí còn lại của Cổ Ma, tiến lên Nguyên Anh trung kỳ và luyện Huyền Âm ma khí tới hai tầng cuối. Ma thi dự định vào Ma Uyên vạn trượng để tiếp tục tăng tiến, sau đó giết Hàn Lập và cắn nuốt Nguyên Thần của hắn. Bên ngoài cốc, một nữ tử áo trắng thu lấy tử sắc linh thảo sau khi linh thảo hóa thành quái điểu, bị ba đạo kiếm quang đánh rơi rồi trở lại nguyên hình."},{"chuong":1170,"tieuDe":"An Bài","tomTat":"Liễu Ngọc, Mộ Phái Linh và Tống Ngọc tìm kiếm gần nửa tháng tại vùng ngoài Trụy Ma Cốc nhưng vẫn chưa phát hiện Huyễn linh thảo, nên quyết định mạo hiểm tiến tới những khu vực có thể tồn tại không gian liệt phùng. Tại Lạc Vân Tông, Hàn Lập báo cho Lữ Lạc biết Nam Cung Uyển đã được giải trừ Phong Hồn Chú, song nàng vẫn phải ở trong băng bích thêm vài năm để tu luyện Xá Nữ Thiên Nguyệt Quyết. Hàn Lập từ chối chuyển động phủ khỏi Tử Mẫu Phong, để lại khôi lỗi cấp Nguyên Anh cho tông môn và tiếp quản việc gia cố cấm địa bảo vệ Nam Cung Uyển. Hắn nhờ Lữ Lạc hỗ trợ Điền Cầm Nhi áp chế dương khí phản phệ do Long Ngâm Chi Thể, đồng thời dự định tìm linh đan thuộc tính âm cho nàng. Sau đó, Hàn Lập mở động phủ riêng, giao điển tịch trận pháp, đồng bài mở cấm chế và nhiều pháp khí thượng giai cho Điền Cầm Nhi. Khi mọi việc đã được thu xếp, hắn trở về động phủ cũ, ổn định linh thảo, linh thú và linh trùng rồi bắt đầu tế luyện bộ Thanh Trúc Phong Vân Kiếm thứ hai bằng giáp tinh, đồng thời cân nhắc thêm Vạn Niên Huyền Ngọc để tăng uy năng băng hàn."},{"chuong":1171,"tieuDe":"Áp Phục Lưỡng Tông","tomTat":"Sau bốn ngày bốn đêm bế quan tế luyện lại vật lấy từ Đại Tấn, Hàn Lập xuất quan và theo Lữ Lạc tới gặp các trưởng lão Cổ Kiếm Môn cùng Bách Xảo Viện. Hắn triệt tiêu khí tức đến mức năm tu sĩ Nguyên Anh không thể cảm ứng, khiến tất cả phải công nhận hắn đã trở thành đại tu sĩ Nguyên Anh hậu kỳ. Hàn Lập còn nhìn thấu bình cảnh của Minh Hinh, phá tan sự hoài nghi của nữ trưởng lão Cổ Kiếm Môn. Dựa vào uy thế ấy, Lữ Lạc đề nghị tam tông mở rộng khỏi Vân Mộng Sơn, trước mắt khống chế toàn bộ tu tiên giới Khê Quốc, đồng thời ngầm đẩy hai tông còn lại xuống địa vị phụ thuộc. Ở ngoài Trụy Ma Cốc, Mộ Phái Linh, Liễu Ngọc và Tống Ngọc vẫn không tìm được Huyễn Linh Thảo tại địa điểm cuối cùng có khả năng xuất hiện. Tống Ngọc cho rằng nội cốc có thể còn linh thảo và nhắc tới lộ tuyến Hàn Lập từng đi qua an toàn, nhưng Mộ Phái Linh phản đối vì hiểm nguy cửu tử nhất sinh."},{"chuong":1172,"tieuDe":"Bị Bắt","tomTat":"Tống Ngọc tiết lộ rằng Tử Linh từng cùng Hàn Lập vượt nội cốc và đã cung cấp một lộ tuyến tương đối an ổn, khiến nàng, Mộ Phái Linh và Liễu Ngọc quyết định mạo hiểm tìm Huyễn Linh Thảo trong phạm vi gần cửa vào. Sau năm ngày vượt qua băng kính, ba người tìm kiếm quanh một ngọn núi xanh suốt một ngày một đêm nhưng chỉ thu được những linh dược khác, nên Tống Ngọc quyết định lập tức rút lui. Trên đường trở về, họ bị một đám mây đen kèm tiếng sấm truy đuổi và Liễu Ngọc nhận ra kẻ bên trong có thể là ma đạo tu sĩ. Tống Ngọc dùng viên châu tạo bạch vân tăng độn tốc, còn Liễu Ngọc phóng bảy tám con Lục Dực Sương Công cản địch, nhưng toàn bộ linh trùng bị tơ đen xuyên thủng rồi bị hắc hỏa thiêu thành tro. Ma tu ngưng tụ mây đen thành bàn tay khổng lồ, thu mất pháp vật chống trả và bắt sống cả ba nữ tu. Hắn dự định dùng họ làm con tin để khiến một người chưa rõ danh tính phải dè chừng. Khi tỉnh lại tại một nơi có nhiều cột đá phát bạch quang, Tống Ngọc định vận dụng pháp lực nhưng lập tức kinh hãi, mất sức và co quắp trên mặt đất."},{"chuong":1173,"tieuDe":"Nguyên Anh Và Thiên Sát Ma Thi","tomTat":"Tống Ngọc tỉnh lại trong một động quật bí mật, phát hiện pháp lực của mình đã bị phong tỏa và hai người đồng hành là Mộ Phái Linh cùng Liễu Ngọc vẫn còn sống. Kẻ bắt giữ mang thân thể khô lâu với hai cánh tay vàng bạc, sau đó thừa nhận mình là đệ nhị Nguyên Anh của Hàn Lập đã sinh thần thức độc lập. Hắn kể rằng sau khi bị một đại tiên sư đánh trọng thương và mất liên hệ với bản thể, mình đã phiêu bạt nhiều năm, trở lại Trụy Ma Cốc rồi chiếm thân Thiên Sát ma thi. Nhờ ma khí, thi khí và Âm La Phiên, hắn luyện Huyền Âm ma khí hơn phân nửa, đột phá Nguyên Anh trung kỳ và nuôi ý định cắn nuốt nguyên thần Hàn Lập để thay thế bản thể. Mộ Phái Linh nhận diện hắn nhờ ngọc bội chứa khí tức mà Ngân Nguyệt từng để lại, còn Tống Ngọc chất vấn khả năng hắn có thể thắng được Hàn Lập. Hắn tuyên bố giữ ba nữ tu làm con tin để kiềm chế bản thể, rồi kích hoạt pháp trận phóng hắc khí khiến cả ba hôn mê lần nữa. Sau khi cuộc đối thoại kết thúc, ánh mắt phức tạp của hắn cho thấy ký ức và tình cảm kế thừa từ Hàn Lập vẫn còn gây ảnh hưởng."},{"chuong":1174,"tieuDe":"Uy Chấn Thiên Nam","tomTat":"Lạc Vân Tông gửi thiệp mời tới các tông môn lớn để tổ chức đại điển mừng một trưởng lão tiến giai Nguyên Anh hậu kỳ, khiến các thế lực nhanh chóng nhận ra người đó là Hàn Lập. Thái Chân Môn chuyển tin tới các trưởng bối ở Kim Hà Cốc, Hợp Hoan Lão Ma quyết định đích thân dự lễ, còn sáu phái tại Bắc Lương tìm cách nối lại giao tình cũ với Hàn Lập trong lúc Hoàng Phong Cốc đã mất chỗ dựa Nguyên Anh. Ba tháng sau, gần một trăm tu sĩ Nguyên Anh cùng nhiều tu sĩ Kết Đan tập trung tại Vân Mộng Sơn dự đại điển. Hàn Lập mời các nhân vật mạnh nhất vào một nơi bí mật rồi chủ động đồng thời luận bàn với Ngụy Vô Nhai và Hợp Hoan Lão Ma. Bằng nhiều thần thông cùng vài bảo vật uy lực kinh người, hắn dễ dàng đánh bại cả hai đại tu sĩ, khiến họ tổn thương nguyên khí trong khi bản thân dường như vẫn chưa dùng hết thực lực. Tin tức lan khắp Thiên Nam, đưa Hàn Lập lên vị thế đại tu sĩ thứ tư và làm danh xưng Thiên Nam đệ nhất tu sĩ bắt đầu lưu truyền. Cuối chương, Chí Dương thượng nhân bí mật gặp Ngụy Vô Nhai gần Thất Linh đảo để trực tiếp xác minh lời đồn về trận thua."},{"chuong":1175,"tieuDe":"Luyện Sí","tomTat":"Ngụy Vô Nhai tiết lộ rằng mình và Hợp Hoan lão ma từng liên thủ vẫn không thể thắng Hàn Lập, đồng thời cảnh báo Chí Dương rằng Hàn Lập đã có khả năng tiêu diệt đại tu sĩ Nguyên Anh hậu kỳ. Biết đại hạn chỉ còn vài năm, ông khuyên Chí Dương từ bỏ hư danh, tránh gây họa cho tông môn và chuyên tâm tìm cơ hội tiến vào Hóa Thần. Chí Dương vẫn đến Lạc Vân Tông gặp Hàn Lập, nhưng sau nửa ngày liền trở về và tuyên bố bế quan sinh tử, còn Hàn Lập từ đó được công nhận là Thiên Nam đệ nhất tu sĩ. Uy danh ấy giúp Lạc Vân Tông nhanh chóng chiếm hơn phân nửa Khê Quốc, khiến các tông môn khác phải quy thuận hoặc rời đi, trong khi Cổ Kiếm Môn và Bách Xảo Viện gần trở thành thế lực phụ thuộc. Tại động phủ ở Tử Mẫu Phong, Hàn Lập luyện lại Phong Lôi Sí đã dung nhập Côn Bằng Chi Vũ nhưng phát hiện uy lực chỉ đạt cấp phỏng chế linh bảo. Thiên Lan thánh thú phân thân giải thích rằng thiên địa pháp tắc phong thuộc tính trong linh vũ chưa được kích phát và đề xuất chuyển tu công pháp phong thuộc tính hoặc tìm cực phẩm linh thạch cùng thuộc tính, song cả hai cách đều không khả thi với Hàn Lập lúc này. Hàn Lập không truy cứu sai sót luyện chế mà thuận thế yêu cầu đối phương bồi thường bằng việc giám định một nhóm tài liệu bí ẩn. Thiên Lan thánh thú nhận ra hai món hiếm gặp ngay cả tại Linh Giới và lập tức hút chúng tới để kiểm tra."},{"chuong":1176,"tieuDe":"Hỏa Linh Thi Và Phá Diệt Pháp Mục","tomTat":"Hàn Lập đưa khối vật chất trong suốt, con mắt đen cùng những vật liệu khác cho Thiên Lan Thánh Thú phân thân giám định. Đồng tử xác định khối trong suốt là Hỏa Linh Ti, một vật liệu hiếm có thể dùng luyện Chiến Linh Giáp hỏa thuộc tính hoặc trực tiếp làm bảo vật chiến đấu. Con mắt đen được nhận diện là Phá Diệt Pháp Mục dị chủng mang huyết mạch Thử Liệt thú, có khả năng khắc chế ảo thuật, độn thuật và làm suy yếu cách giới lực, nên đặc biệt hữu ích cho kế hoạch tiến vào Linh Giới của Hàn Lập. Đồng tử còn nhận ra ba khối Ly Mộng tinh thạch nhưng không xác định được lai lịch yêu đan đen trắng lấy từ lạn nhục yêu thú trong Trụy Ma Cốc. Để bồi thường tổn thất của Phong Lôi Sí, lão truyền cho Hàn Lập phương pháp tinh luyện Hỏa Linh Ti và khẩu quyết tu luyện Phá Diệt Pháp Mục. Hàn Lập lập tức đồng ý rồi tĩnh tọa ghi nhớ hai phương pháp. Nửa ngày sau, một lầu các trong nội khu Lạc Vân Tông nhận được hồng quang mang ngọc giản cùng lệnh bài, khiến quản sự áo lam biến sắc và trở nên đặc biệt ngưng trọng."},{"chuong":1177,"tieuDe":"Tung Tích","tomTat":"Theo lệnh của Đại trưởng lão, các quản sự Lạc Vân Tông tạm gác công việc và gom đủ vật liệu luyện khí trong vòng ba ngày, sau đó giao chúng tới động phủ của Hàn Lập tại Tử Mẫu Phong. Hàn Lập dùng hỏa hồng tiểu đỉnh tạo hơn mười hỏa nha, nung vật thể trung tâm và dung nhập phụ liệu để cô đọng Hỏa Linh Ti trong suốt hai tháng, bất chấp cảnh báo của Đồng tử về nguy cơ thất bại. Khi việc luyện khí kết thúc, Lữ Lạc báo rằng nhóm Bạch sư điệt đã vào Trụy Ma Cốc gần nửa năm nhưng chưa trở về, còn những dấu vết thu được chỉ cho thấy họ đã biến mất kỳ lạ tại khu vực này. Vì vụ việc liên quan tới Mộ Phái Linh và đệ tử ký danh của mình, Hàn Lập đồng ý đích thân điều tra, đồng thời nghi Thiên Sát ma thi thất lạc năm xưa có thể liên quan. Sau khi xem xét tình hình Nam Cung Uyển trong cấm địa, hắn một mình rời Lạc Vân Tông và tiến về Trụy Ma Cốc. Hơn một tháng sau tại Xương Châu thuộc Đông Dụ Quốc, ba huynh đệ mang phi xoa tới gặp Hậu lão ca, một trung niên nho sinh và một thanh niên bí ẩn. Thấy hai người lớn tuổi đều kính cẩn với thanh niên và không thể dùng thần niệm dò ra pháp lực của hắn, cả ba huynh đệ lập tức biến sắc."},{"chuong":1178,"tieuDe":"Trở Lại Trụy Ma Cốc","tomTat":"Hàn Lập gặp Triệu thị huynh đệ của Kim Hải Tông và xác nhận họ từng nhìn thấy Bạch Dao Di cùng hai nữ tu khác ở sâu trong ngoại cốc Trụy Ma Cốc. Sau khi đối phương đánh dấu địa điểm gặp mặt vào ngọc giản, ông nhận ra nơi ấy đã rất gần nội cốc và lập tức lên đường. Các đệ tử Lạc Vân Tông sau đó xác nhận ba người mất tích là Bạch Dao Di, Liễu Ngọc và Mộ Phái Linh, trong đó Liễu Ngọc là đệ tử ký danh còn Mộ Phái Linh là thị thiếp của Hàn Lập. Trên đường đi, Hàn Lập trao đổi với Thiên Lan thánh thú phân thân, cho biết mình mới xác định Kim Khuyết Ngọc Thư ghi một bộ phù triện tiên gia nhưng chưa thể lĩnh hội, đồng thời tái khẳng định lời hứa trợ giúp đối phương hóa hình. Khi tới Trụy Ma Cốc, ông nhận thấy nhiều khe không gian và cấm chế ngoại vi đã suy yếu, khiến truyền tống trận cũ của Quỷ Linh Môn không còn tác dụng. Hàn Lập bỏ qua nhóm tu sĩ Kết Đan tại cốc khẩu, nhanh chóng vượt ngoại cốc theo vị trí được đánh dấu rồi lần theo tuyến đường cũ từng đi cùng Tử Linh. Cuối cùng, ông tiến vào khe băng khổng lồ trong nội cốc để bắt đầu tìm kiếm ba nữ tu."},{"chuong":1179,"tieuDe":"Huyết Nguyệt Mịch Linh Bí Thuật","tomTat":"Sau khi rời băng phùng, Hàn Lập dùng Phệ Kim Trùng phối hợp Thần Thức Hoá Thiên rà soát nội cốc và xác nhận tam nữ từng dừng lại hái linh dược tại một ngọn núi, nhưng sau đó mất dấu. Hắn đổi sang thả mười hai con Lục Dực Sương Công nhằm cảm ứng ấu trùng Liễu Ngọc mang theo, qua đó tìm được một đoạn xúc tu màu đen nhiễm Huyền Âm Ma Khí tinh thuần. Từ khí tức quen thuộc và việc Mộc Linh Anh biết toàn bộ Huyền Âm đại pháp, Hàn Lập suy đoán đệ nhị Nguyên Anh đã trở lại Thiên Nam, có liên quan đến sự mất tích của tam nữ và có thể đã đoạt xá Thiên Sát Ma Thi. Để tiếp tục truy tìm, hắn lấy tinh huyết Mộ Phái Linh từng lưu lại khi gieo cấm thần cấm chế, kết hợp Bạch sắc ngọc bàn, Xích Hồng Tiểu Kỳ và tinh huyết bản thân để lần đầu thi triển Huyết Nguyệt Mịch Linh bí thuật. Việc thi thuật khiến hắn hao tổn đáng kể, nhưng Huyết Nguyệt đã bay dẫn đường suốt nửa ngày. Cuối cùng, huyết quang đưa Hàn Lập tới một bồn địa hoang vắng có hồ dung nham đỏ rực rồi chỉ xuống phía dưới. Xác định mục tiêu đang ẩn dưới hồ, Hàn Lập quyết định vượt qua dung nham để tiếp tục truy tìm."},{"chuong":1180,"tieuDe":"Giải Cứu","tomTat":"Hàn Lập dùng Tử La Cực Hoả lặn sâu xuống hồ dung nham, dựa vào Minh Thanh Linh Mục và ngọc bàn để tìm kiếm. Sau khi phá lớp đá cùng quang mạc cấm chế dưới đáy hồ, hắn đi qua một địa đạo dài và tới động quật ngầm nơi Mộ Phái Linh, Liễu Ngọc cùng Tống Ngọc đang bị giam. Hàn Lập dùng kim sắc điện hồ tiêu diệt hắc vụ hóa xà, nhìn thấu Mê Huyễn Chi trận rồi dùng kiếm khí làm trận pháp ngừng vận hành. Cùng lúc đó tại Ma Uyên, một hắc ảnh cao lớn phát hiện viên châu lam sắc nứt ra, biết cấm chế đã bị phá và quyết định đào tẩu, hoàn thành ma khí ngưng thể rồi tìm thân thể khác. Hàn Lập cho ba nữ tu uống đan hoàn, giúp họ lần lượt tỉnh lại và lấy ngân châm phong cấm pháp lực khỏi cơ thể họ. Tống Ngọc ban đầu nghi hắn là Yêu Anh giả trang, còn Mộ Phái Linh dùng cấm chế thần thức để xác nhận thân phận thật của hắn. Chương kết thúc khi Hàn Lập hỏi liệu Mộc Linh Anh thất lạc có phải kẻ bắt giữ họ hay không, khiến Liễu Ngọc kinh ngạc nhắc tới Yêu Anh."},{"chuong":1181,"tieuDe":"Tái Ngộ Thất Linh Đảo","tomTat":"Liễu Ngọc xác nhận kẻ từng bắt ba nữ tu là đệ nhị Nguyên Anh thất lạc của Hàn Lập, đồng thời giúp hắn nhận ra phân hồn đã đoạt xá thân thể Thiên Sát Ma Thi và đạt tu vi khoảng Nguyên Anh trung kỳ. Hàn Lập cho Mộ Phái Linh, Liễu Ngọc và Tống nữ trở về tông môn, còn mình ở lại Trụy Ma Cốc truy tìm đối phương; trong lúc đó, ba người biết hắn đã tiến giai Nguyên Anh hậu kỳ, trở thành Đại tu sĩ và Đại trưởng lão Lạc Vân Tông. Sau sáu bảy ngày chờ đợi, hắn thả hàng vạn Phệ Kim Trùng tảo quét Nội Cốc nhưng chỉ tìm được một số Cổ Bảo và những động phủ thượng cổ đã bị vét sạch. Từ thân thể Ma Thi, Huyền Âm Đại Pháp và nhu cầu tăng tiến nhanh của phân hồn, Hàn Lập suy ra đối phương đang thực hiện Ma Khí Quán Thể tại Vạn Trượng Ma Uyên. Đệ nhị Nguyên Anh quả thực đang ở Ma Uyên, nhưng vì không biết bản thể đã thành Đại tu sĩ nên đánh giá sai tốc độ truy đuổi và dự định chỉ lưu lại thêm tối đa nửa tháng. Hàn Lập mất khoảng một tháng tới Vô Biên Hải rồi thêm hai ngày tới Thất Linh Đảo, sau đó ghé Linh Miết Đảo và triệu tập hai đội tu sĩ Lạc Vân Tông đang đồn trú. Khi hai đội do Khuê Hoán và một phụ nhân Kết Đan kỳ dẫn đầu tới nơi, hắn bất ngờ lộ vẻ kinh ngạc và cổ quái."},{"chuong":1182,"tieuDe":"Tiến Nhập Vạn Trượng Ma Uyên","tomTat":"Hàn Lập gặp lại Khuê Hoán, biết người đệ tử có tư chất bình thường năm xưa đã tiến vào Kết Đan kỳ nhờ vô tình ăn một loại linh thảo vô danh, trong khi Vương sư huynh đã tọa hóa từ lâu. Qua lời Khuê Hoán và phụ nhân trông coi Thất Linh Đảo, hắn nhận ra cơ chế tuần tra luân phiên có thể khiến những dị biến quanh phong ấn bị bỏ sót. Hàn Lập giao bộ trận kỳ và trận bàn, lệnh họ dẫn ba mươi sáu đệ tử dựng Huyền Cương Thiên Sát trận tại cửa vực để trì hoãn bất cứ thứ gì thoát ra. Đến chính ngọ, hắn dùng Tam Diễm Phiến mở một khe trên phong ấn, ép ma khí trở xuống rồi tiến vào Vạn Trượng Ma Uyên trước khi quang mạc tự khép lại. Trong vực sâu, hắn kích phát Ích Tà Thần Lôi chống ma khí và vận Huyền Mẫu Hóa Anh Đại Pháp để truy tìm Nguyên Anh thứ hai. Sau khi xuống sâu bảy tám nghìn trượng mà chưa có phản ứng, Hàn Lập bất ngờ phát hiện dấu hiệu khả nghi và đổi hướng truy tới. Cuối cùng, Minh Thanh Linh Mục giúp hắn nhìn thấy một nhân ảnh cao lớn đang gào thét điên cuồng, và ánh mắt hai bên lập tức chạm nhau."},{"chuong":1183,"tieuDe":"Ma Hóa","tomTat":"Thiên Sát Ma Thi bất ngờ đánh lén Hàn Lập trong ma khí, nhưng hắn dùng Ngân Sắc Thuẫn Bài đỡ ma trảo rồi lấy kim kiếm chém đứt một cánh tay của nó. Hàn Lập nhận ra Nguyên Anh thứ hai vì nóng vội thực hiện Ma Khí Quán Thể trong khi Đại Diễn Quyết mới đạt tầng hai nên đã bị ma khí xâm nhập và đánh mất thần trí. Ma Thi hút ma khí tái tạo cánh tay, dùng hắc sắc quang trụ đối kháng Tam Sắc Hỏa Diễm, song cuối cùng bị Hàn Lập dùng Phong Lôi Sí đánh văng vào biển lửa và thiêu hủy thân thể. Nguyên Anh thứ hai thoát khỏi ma thể với thần trí đã khôi phục, sau đó tự bạo Âm La Phiên thành lưới hắc ti rộng vài dặm để cản đường. Hàn Lập gia trì kim sắc điện hồ lên kim kiếm, phá thủng hắc võng rồi tiếp tục truy kích. Trên mặt biển, khi các tu sĩ đang chuẩn bị vận hành phong ấn cửa Ma Uyên, một hắc cự kiếm xuyên thủng bạch sắc quang mạc và một đạo ô quang lập tức thoát ra ngoài."},{"chuong":1184,"tieuDe":"Thu Anh","tomTat":"Đệ nhị Nguyên Anh được giải trừ trạng thái ma hóa, khôi phục linh trí rồi tự bạo Xích Huyết Kiếm và Âm La Phiên để thoát khỏi sự truy đuổi của Hàn Lập. Khi vừa ra ngoài phong ấn Ma Uyên, nó bị Khuê Hoán, một phụ nhân và ba mươi sáu đệ tử Lạc Vân Tông dùng ngũ sắc quang hà vây khốn, nhưng vẫn phá thủng trận và thi triển thuấn di bỏ chạy. Hàn Lập dùng Phong Lôi Sí đuổi theo, thi triển bí thuật hắc nhãn xác định vị trí mục tiêu rồi dùng Hư Thiên Đỉnh trói, phong bế linh lực và thu đệ nhị Nguyên Anh vào trong. Sau đó, hắn thưởng hai bình đan dược cho Khuê Hoán cùng các đệ tử, đồng thời yêu cầu tăng cường người canh giữ Ma Uyên. Các tu sĩ Lạc Vân Tông và môn hạ của Hồng Bào tu sĩ phối hợp gia cố lại phong ấn đã suy yếu. Hơn mười ngày sau, Hàn Lập trở về Tử Mẫu Phong, gặp Liễu Ngọc và biết các môn hạ đã thay phiên chờ mình. Hắn hé lộ Điền Cầm Nhi mang Long Ngâm chi thể, cho biết việc nhận nàng còn có nguyên nhân khác rồi sai Liễu Ngọc triệu tập mọi người để bàn chuyện quan trọng."},{"chuong":1185,"tieuDe":"Trong Phủ — An Bài Môn Sự","tomTat":"Hàn Lập xác nhận đã bắt được đệ nhị Nguyên Anh và dự định xóa thần thức tự chủ của nó để luyện hóa lại. Biết Mộ Phái Linh, Liễu Ngọc và Tống nữ từng liều lĩnh tiến vào Nội Cốc tìm Huyễn Linh Thảo nhằm luyện Huyễn Diệt Đan, hắn trách phạt bằng lời rồi cấp đan dược thay thế, chia cho mỗi người hai viên. Hàn Lập chính thức thu Liễu Ngọc làm đồ đệ, truyền bí thuật, ban ba món cổ bảo và giao nàng hỗ trợ Lữ Lạc quản lý Lạc Vân Tông trong thời gian hắn bế quan. Hắn cũng nhờ Tống nữ tìm một người có thần thức thiên sinh cường đại để thu làm môn hạ, đồng thời ban Âm Nguyên Hoàn giúp nàng phá bình cảnh. Sau đó, Hàn Lập muốn giải quyết dứt khoát thân phận không rõ ràng của Mộ Phái Linh vì Điên Phượng Bồi Nguyên Công không còn cần thiết và Nam Cung Uyển sắp giải Phong Hồn Chú. Mộ Phái Linh không chọn rời đi hoặc ở lại như đồ đệ mà xin trở thành thị thiếp chân chính, song Hàn Lập từ chối vì Nam Cung Uyển, sự chênh lệch thọ nguyên và những lần bế quan kéo dài. Cuộc đối thoại kết thúc khi hai người vẫn chưa thống nhất được an bài cuối cùng."},{"chuong":1186,"tieuDe":"Đồng Hóa","tomTat":"Hàn Lập cho Mộ Phái Linh thêm vài năm cân nhắc con đường ngưng kết Nguyên Anh, đồng thời cấp đan dược để nàng thử đột phá Kết Đan trung kỳ và giao nàng tiếp tục chỉ điểm Điền Cầm Nhi. Sau khi hai người rời đi, hắn điều khiển khôi lỗi hình người biến thành một bản sao giống hệt mình rồi bố trí nó ẩn nấp trong động phủ. Hàn Lập hỏi Thiên Lan thánh thú phân thân về đệ nhị Nguyên Anh và nhắc lại lời hứa giúp thánh thú vượt biến hóa lôi kiếp sau khi hoàn tất việc thu hồi phân anh. Trong mật thất đã được phong kín, đệ nhị Nguyên Anh giả vờ hôn mê và tìm cách thuấn di trốn thoát nhưng bị thanh ti từ Hư Thiên Đỉnh bắt lại, sau đó bị ngân châm phong bế pháp lực. Nó phản đối vì quá trình đồng hóa sẽ xóa bỏ ý thức tự chủ, song Hàn Lập vẫn làm nó hôn mê để tiếp tục kế hoạch. Đệ nhất Nguyên Anh xuất khiếu, dùng hắc sắc quang hà và hai luồng thanh sắc quang trụ cưỡng ép quán chú vào đối phương. Chương kết thúc khi đệ nhị Nguyên Anh vẫn đang đau đớn chịu đồng hóa và kết quả cuối cùng chưa được xác định."},{"chuong":1187,"tieuDe":"Độ Kiếp","tomTat":"Sau nửa tháng bế quan, Hàn Lập dùng bí thuật phụ thể của Đại Diễn Bảo Kinh đưa đệ nhị Nguyên Anh vào Khôi lỗi hình người, giúp nó có thể trực tiếp điều khiển Khôi lỗi từ xa. Hắn còn cài thủ đoạn làm Khôi lỗi tê liệt để đề phòng đệ nhị Nguyên Anh tái sinh nguyên thần tự chủ và phản chủ. Theo đề nghị của Thiên Lan thánh thú, Hàn Lập rời Tử Mẫu Phong, thăm Nam Cung Uyển rồi chọn một vùng hoang vu tại giao giới Khê Quốc và Hoa Vũ Quốc làm nơi độ kiếp. Thiên Lan thánh thú điều tức ba ngày, nhận một giọt Hàn tuỷ từ Hàn Lập và nhờ hắn hộ pháp trong ba đợt lôi kích cuối, còn Hàn Lập bố trí cấm chế pháp trận quanh khu vực. Thiên Lan thánh thú cũng bí mật tiết lộ một lợi ích đi kèm hoá hình lôi kiếp, khiến Hàn Lập quyết định dùng pháp khí đang mang theo để thử nắm bắt cơ hội. Cuối cùng, nó giải trừ che giấu, phóng thích yêu khí bát cấp dẫn phát thiên tượng rồi tung hôi bạch sắc cụ phong quét sạch đợt lôi điện và mây mù mở đầu."},{"chuong":1188,"tieuDe":"Liên Hoàn Thiên Lôi","tomTat":"Yêu phong quanh Thiên Lan thánh thú bị cự kiếm hồ quang bổ nứt, để lộ nguyên hình ngưu thủ giao thân có cánh tím và bốn tay giữa điện võng bao phủ mười dặm. Hàn Lập dùng Ích Tà Thần Lôi bảo vệ bản thân, đồng thời quan sát đối phương lần lượt dùng hôi bạch yêu khí và ngân bạch yêu khí chống các đợt thiên lôi ngày càng mạnh. Từ đợt thứ tư, Thiên Lan thánh thú phóng lớn thân hình và đánh ngược phần lớn lôi điện, khiến Hàn Lập nghi nó đã luyện hóa hàn tủy được tặng. Khi biết ba đợt cuối vượt quá khả năng tự chống đỡ của đối phương, Hàn Lập nhận lời hộ pháp và chuẩn bị ba pháp khí để can thiệp. Sau đợt thứ bảy, lớp ngân sắc yêu khí của Thiên Lan thánh thú đã hao hụt quá nửa. Trong lúc đợt lôi điện thứ tám giáng xuống, Hàn Lập phát hiện sinh vật ẩn dưới đất và dùng mười đạo hồng ti ép nó hiện thân. Yêu thú xuất hiện là một Độc Giác Khâu màu vàng sẫm có hình thể khổng lồ cùng chiếc sừng hút điện võng, khác hẳn đặc điểm thông thường của giống loài này."},{"chuong":1189,"tieuDe":"Quái Dị Kim Giác","tomTat":"Độc Giác Khâu dùng kim giác hấp thu thiên lôi rồi chuyển luồng lôi điện sang công kích Hàn Lập, khiến hắn nhận ra yêu thú biến dị này đã khai mở linh trí. Hàn Lập dùng lôi điện, phi kiếm vàng và Hỏa linh ti vây công, nhưng kim giác vừa đánh bật cự kiếm vừa hấp thu được cả ngọn lửa. Hắn đổi sang Kiếm quang phân hóa, hợp nhất nhiều đạo kiếm quang thành một đòn lớn và chém đôi cự thú. Hai nửa cơ thể Độc Giác Khâu tiếp tục hoạt động độc lập, song nửa thân trên bị Hỏa linh ti cùng kiếm quang tiêu diệt còn nửa thân dưới bị Phệ Kim Trùng truy sát dưới lòng đất. Hàn Lập thu lấy kim giác có chú văn huyền ảo, dùng pháp quyết thu nhỏ và dán cấm chú trước khi cất vào túi trữ vật. Khi hắn quay lại pháp trận, Thiên Lan thánh thú đã vượt qua đợt lôi điện thứ tám, còn trên mây đen xuất hiện một vầng trăng tròn tỏa ánh sáng trắng ngà và hương khí kỳ dị."},{"chuong":1190,"tieuDe":"Thủ Dịch","tomTat":"Khi dị tượng trăng tròn nhỏ xuống linh dịch có thể giúp Thiên Lan thánh thú phân thân phục hồi, Hàn Lập lập tức dùng hồ lô, bình ngọc và viên bát để thu lấy. Hắn vận dụng Bát Linh Xích chống hồ quang, rồi dùng Thất Thần Thứ cùng tinh huyết giúp ba pháp khí vượt qua cấm chế trước lúc trăng tròn biến mất. Hoàng sắc hồ lô sau khi trở về tỏa ra hương thơm nhàn nhạt, cho thấy việc thu vật đã có kết quả. Tiếp đó, một điện giao bạc khổng lồ giáng xuống, buộc Hàn Lập dùng ngân sắc tiểu thuẫn giúp yêu thú tiêu giảm khoảng một nửa uy lực. Theo yêu cầu của Thiên Lan thánh thú phân thân, hắn thu hồi bảo vật để nó phun yêu đan tự chống phần lôi kiếp còn lại. Chứng kiến yêu đan ngăn được điện giao, Hàn Lập tin mình có thể tiếp tục hỗ trợ trong hai đợt cuối, nhưng thành bại vẫn tùy thuộc vào sức chịu đựng của yêu thú."},{"chuong":1191,"tieuDe":"Hóa Giới Châu Cùng Tật Phong Cửu Biến","tomTat":"Hàn Lập dùng ngân sắc tiểu thuẫn hỗ trợ Thiên Lan thánh thú phân thân chống đỡ hai đợt lôi kích cuối, giúp nó vượt qua lôi kiếp và tái tổ thân thể thành tiểu đồng áo vàng. Trong lúc chờ hóa hình, hắn phát hiện Phệ Kim Trùng đã ăn sạch tàn thi cự khâu biến dị rồi thu đàn trùng trở lại túi linh thú. Trở về động phủ tại Tử Mẫu Phong, Hàn Lập được biết chiếc sừng của cự khâu là tài liệu hấp linh có thể dùng để luyện chiến giáp hoặc Hóa Giới Châu. Thiên Lan thánh thú phân thân cảnh báo Phá Diệt pháp mục không đủ để bảo đảm an toàn khi vượt không gian tiết điểm, đồng thời truyền cho hắn phương pháp luyện chế Hóa Giới Châu. Hàn Lập tiếp đó đề nghị cho đối phương mượn tàn trang Kim Khuyết Ngọc Thư để đổi lấy việc cải biến Tật Phong Cửu Biến thành công pháp thích hợp với con người và Phong Lôi Sí. Khi hắn tiết lộ Minh Vương Quyết đã luyện tới tầng hai và công pháp này có bảy tầng, Thiên Lan thánh thú phân thân nhận ra nó giống một bộ luyện thể pháp quyết Phật môn bảy tầng khác mà mình biết."},{"chuong":1192,"tieuDe":"Chung Thành Quyến Chúc","tomTat":"Lạc Vân Tông tổ chức song tu đại điển long trọng cho Hàn Lập và Nam Cung Uyển, thu hút khoảng năm sáu ngàn tu sĩ ngoại lai tới Vân Mộng Sơn. Hai người ra mặt cảm tạ quần tu, uống rượu giao bôi rồi rời đi, để Lữ Lạc tiếp tục chủ trì buổi lễ trong nhiều ngày. Sau đại điển, Nam Cung Uyển cho biết nàng đã tu luyện Xá Nữ Thiên Nguyệt quyết trong thời gian bị phong ấn, đột phá Nguyên Anh trung kỳ và giải trừ hoàn toàn những cấm chế ẩn giấu của Phong Hồn Chú. Hàn Lập khuyên nàng củng cố căn cơ rồi dùng Bồi Anh Đan để tìm cơ hội tiến lên Nguyên Anh hậu kỳ. Mộ Phái Linh tới báo nữ tử họ Yến cùng hai trưởng lão Quỷ Linh Môn và Hạm Vân Chi vẫn lưu lại xin gặp, khiến Hàn Lập quyết định bố trí hai nhóm ở hai tòa khách quý để lần lượt tiếp kiến. Nam Cung Uyển giải thích đã nhận Mộ Phái Linh làm nghĩa muội, đồng thời để ngỏ khả năng truyền thụ cho nàng hoặc để nàng trở thành thị thiếp của Hàn Lập. Do Xá Nữ Thiên Nguyệt quyết cần pháp trận tụ tập âm nguyệt lực gây bất lợi cho người khác, đôi đạo lữ thống nhất sẽ tách động phủ khi tu luyện nhưng vẫn sống chung vào thời gian bình thường."},{"chuong":1193,"tieuDe":"Tụ Linh Châu","tomTat":"Mộ Phái Linh dẫn Hàn Lập đến khu lầu khách quý, nơi Yến Như Yên, Chung trưởng lão và một đại hán họ Yến đang chờ để cầu viện. Hàn Lập nhận ra Yến Như Yên đã tiến vào Nguyên Anh kỳ và biết rằng Yến gia hiện thay Vương gia chấp chưởng Quỷ Linh Môn sau cái chết của Vương môn chủ cùng việc Vương Thiền bị giam. Do bị nhiều tông môn liên thủ gây sức ép, Quỷ Linh Môn đứng trước nguy cơ tan rã và đề nghị nhường Việt quốc để đổi lấy việc Hàn Lập bảo toàn truyền thừa. Phía Quỷ Linh Môn lần lượt dâng Huyết Chi Đan, Huyết Hoàn và một hộp gỗ được cho là chứa Mộc Linh Châu. Hàn Lập không mấy động tâm trước hai món đầu nhưng lập tức nghiêm túc khi biết Mộc Linh Châu có thể tập trung linh khí mộc thuộc tính và hỗ trợ tu luyện vượt Linh nhãn vật thông thường. Chương kết thúc khi hắn phá phù triện cấm chế và mở hộp để kiểm tra vật bên trong."},{"chuong":1194,"tieuDe":"Ám Mưu","tomTat":"Hàn Lập kiểm tra Tụ Linh Châu do ba người Quỷ Linh Môn mang tới, xác nhận dị bảo có thể rút ngắn hơn phân nửa thời gian tu luyện công pháp mộc thuộc tính. Trước khi nhận lời cứu viện, hắn đặt thêm điều kiện rằng mình không được gặp lại Vương Thiền, và hai trưởng lão Quỷ Linh Môn chấp thuận hy sinh người này để bảo toàn truyền thừa. Hàn Lập thu ba món bảo vật rồi hứa tự mình chuyển tín hàm của Ngự Linh Tông tới các tông phái liên quan. Trên đường trở về, Hoàng bào đại hán đề nghị thanh trừ toàn bộ đệ tử Vương gia, còn Yến Như Yên quyết định bế quan một trăm năm và không muốn biết kết cục của người chồng cũ. Chung trưởng lão giao quyền xử lý Vương gia cho đại hán họ Yến, đồng thời tiết lộ Tụ Linh Châu vốn do Hợp Hoan lão ma trao và chỉ điểm dùng làm lễ vật đả động Hàn Lập. Dù nghi ngờ đây là âm mưu, hai trưởng lão cho rằng đã quá muộn để đổi ý và dự định đóng cửa Quỷ Linh Môn một trăm năm sau khi thoát nạn. Trong cấm địa Hợp Hoan Tông, một bóng người thần bí biết dị bảo đã tới tay Hàn Lập và ám chỉ nó sẽ gây bất lợi khi hắn đột phá bình cảnh Hóa Thần."},{"chuong":1195,"tieuDe":"Mộc Sinh Châu","tomTat":"Tại Quý Tân Lầu, Thiên Lan thánh thú phân thân cảnh báo Hàn Lập rằng Tụ Linh Châu chỉ là bảo vật bán thành phẩm, tuy giúp pháp lực tiến nhanh lúc đầu nhưng sẽ làm suy yếu khả năng cảm ứng các loại linh khí khác và gây trở ngại cho việc đột phá bình cảnh. Đồng tử tiết lộ có thể dùng tài liệu mộc thuộc tính cùng một số vật liệu quý hiếm để chuyển hóa viên châu thành Mộc Sinh Châu, qua đó cung cấp một lần thi triển bất diệt chi thể. Hai bên đạt thành giao dịch: Hàn Lập cung cấp linh dược củng cố cảnh giới, còn đồng tử giao danh sách tài liệu và phương pháp luyện chế. Hàn Lập nghi ngờ có thế lực đứng sau việc Quỷ Linh Môn đưa viên châu cho mình, nhưng chưa thể xác định thủ phạm giữa Hóa Ý Môn, Hợp Hoan Tông và Thái Nhất Môn. Vì không muốn bắt người khi chưa có chứng cứ và trở thành mục tiêu chung của giới tu sĩ Thiên Nam, hắn quyết định giả vờ không biết để chờ đối phương tiếp tục lộ dấu vết. Sau đó, Hàn Lập rời Quý Tân Lầu và đến gặp lại Hạm Vân Chi cùng Đổng Huyên Nhi, trong khi mục đích chuyến bái phỏng của hai người vẫn chưa được nói rõ."},{"chuong":1196,"tieuDe":"Nhị Nữ","tomTat":"Hàn Lập hội ngộ Hạm Vân Chi, cho phép nàng gọi mình là Hàn đại ca và cùng nàng ôn lại Thái Nam tiểu hội cùng Huyết Sắc Thí Luyện. Đổng Huyên Nhi tiết lộ mình là huyết mạch đích truyền của Vân Lộ lão ma, đồng thời giải thích Dịch mộng quyết đã khiến hình ảnh Hàn Lập trở thành Tâm Ma cản trở con đường tu luyện của nàng. Vì tình đồng môn cũ, Hàn Lập đồng ý dùng thần niệm truyền độ bí thuật giúp nàng vượt cửa ải nhưng tuyên bố sau đó hai người không còn liên quan. Đổng Huyên Nhi nhờ vậy tiến lên Kết Đan hậu kỳ, còn Hạm Vân Chi nhận bảo vật, đan dược và thư gửi Đại trưởng lão Ngự Linh Tông trước khi hai người lần lượt rời Lạc Vân Tông. Nam Cung Uyển báo tin Tử Linh đã ngưng kết Nguyên Anh và đi du lịch Đại Tấn. Hàn Lập quyết định chờ tài liệu luyện khí rồi bế tử quan để đạt Nguyên Anh hậu kỳ đỉnh phong, hoàn thành Đại Diễn Quyết và hợp nhất Cực Hàn Chi Diễm với Ngũ Tử Đồng Tâm Ma, trong khi Nam Cung Uyển cũng hướng tới Nguyên Anh hậu kỳ. Chương khép lại tại một động phủ ở Tử Mẫu Phong, nơi một thiếu nữ đang đọc thẻ ngọc nghe tiếng cười của Hàn Lập rồi mỉm cười hiểu ý."},{"chuong":1197,"tieuDe":"Bế Quan","tomTat":"Sau hơn một trăm hai mươi năm bế quan tại Tử Mẫu Phong, Hàn Lập đang luyện hóa Ngũ Ma cùng năm loại Cực Hàn Chi Diễm thì Nhân hình Khôi Lỗi tiến vào mật thất và chuyển giao một Vạn Lý phù của Lăng Ngọc Linh. Tin cầu viện từ Loạn Tinh Hải khiến hắn quyết định tạm dừng bế quan, vừa thực hiện giao dịch cũ với Thiên Tinh Song Thánh vừa tìm phương pháp tu luyện Nguyên Từ Thần Quang. Trong thời gian bế quan, pháp lực của hắn tăng mạnh nhưng chưa đạt Nguyên Anh hậu kỳ đại thành, còn linh nhãn đã được Minh Thanh linh thủy cường hóa tới giới hạn. Đại Diễn Quyết tiến vào tầng cuối, Minh Vương Quyết đạt tầng ba đại thành và Tật Phong Cửu Biến được lĩnh hội hoàn toàn, giúp thần thức cùng thân thể của hắn tăng tiến rõ rệt. Lục Dực Sương Công đã đạt thất cấp đại thành, Thổ Giáp Long tiến sát bát cấp Hóa Hình, trong khi Phệ Kim Trùng vẫn chưa đủ điều kiện hoàn thành bước tiến hóa cuối. Hàn Lập cũng luyện thành Mộc Sinh Châu rồi dung nhập vào cơ thể, đồng thời chế thêm hai pháp bảo từ độc câu Song vĩ nhân diện hạt và Hỏa Long trụ. Sau khi thu năm quỷ đầu vào ngọc bình đen nhánh và giải trừ cấm chế mật thất, hắn chính thức xuất quan để chuẩn bị tới Loạn Tinh Hải."},{"chuong":1198,"tieuDe":"Tinh Cung Lai Tấn","tomTat":"Sau hơn trăm năm, cục diện Việt Quốc đã thay đổi khi Ngự Linh Tông liên kết các tông môn khác đuổi Quỷ Linh Môn suy yếu khỏi nước này. Trở lại Lạc Vân Tông, Hàn Lập biết tông môn đã phát triển thành đại tông, nữ tử họ Tống kết thành Nguyên Anh, Điền Cầm Nhi đạt Trúc Cơ trung kỳ và Mộ Phái Linh tiến lên Kết Đan hậu kỳ. Hắn thu thiếu niên Thạch Kiên làm đệ tử, giao bản sao Đại Diễn Bảo Kinh và an bài cho người này tu luyện Đại Diễn Quyết để kế tục đạo thống Đại Diễn Thần Quân. Tin cầu viện của Lăng Ngọc Linh cho thấy Tinh Cung đang bị Nghịch Tinh Minh áp chế, khiến Hàn Lập quyết định khẩn trương trở lại Loạn Tinh Hải. Hắn bí mật vào mỏ linh thạch hoang phế tại Đại Hạp Cốc, dựng lại thượng cổ Truyền Tống Trận và để mười hai Lục Dực Sương Công thủ hộ đầu trận phía Thiên Nam. Sau khi truyền tống đến một đảo nhỏ tại Loạn Tinh Hải, Hàn Lập chém hỏng đầu trận phía sau rồi lập tức bay đi cứu viện Tinh Cung."},{"chuong":1199,"tieuDe":"Loạn Tinh Hải","tomTat":"Trên đường tới Thiên Tinh Thành, Hàn Lập nhận thấy tu sĩ qua lại đều cảnh giác và những cuộc chém giết xuất hiện ngày càng nhiều, cho thấy cuộc chiến giữa Tinh Cung và Nghịch Tinh Minh đã lan rộng. Hắn chặn cuộc giao đấu giữa Tất Tốn và một đại hán Kết Đan, dùng tu vi che giấu ở mức Nguyên Anh sơ kỳ để khiến hai người cung kính cung cấp tình báo. Qua lời họ, Hàn Lập biết nhân loại đã mất toàn bộ ngoại hải vào tay yêu thú và phải phá hủy các Truyền Tống Trận trước khi rút về nội hải. Mấy chục năm trước, Thiên Tinh Song Thánh tập kích tổng đàn Nghịch Tinh Minh rồi tự bạo Nguyên Từ Thần Quang, đồng quy vu tận với Vạn Tam Nương và Lục Đạo Cực Thánh. Lăng Ngọc Linh kế nhiệm cung chủ Tinh Cung và từng dẫn dắt thế lực này phản công thắng lợi, nhưng Vạn Thiên Minh sau đó tiến giai Nguyên Anh hậu kỳ, thống hợp Chính Ma và đảo ngược thế cục. Hiện Nghịch Tinh Minh đã ban Nghịch Tinh Lệnh, tập kết đại quân quanh Thiên Tinh Thành và chuẩn bị một trận quyết chiến nhằm tiêu diệt Tinh Cung. Thu được những tin tức cần thiết nhưng vẫn chưa biết chính xác thời điểm khai chiến, Hàn Lập dừng hỏi và cúi đầu trầm ngâm."},{"chuong":1200,"tieuDe":"Tinh Cung Chi Chiến 1","tomTat":"Hàn Lập hiểu rằng Lăng Ngọc Linh dùng Vạn Lý Phù gọi mình tới nhằm đối phó Vạn Thiên Minh, người đã tiến vào Nguyên Anh hậu kỳ và đang uy hiếp Tinh Cung. Hắn không coi Vạn Thiên Minh là đối thủ tương xứng, nhưng đặc biệt chú ý tới Nguyên Từ Sơn vì đây là kỳ vật độc nhất có thể hỗ trợ tu luyện Nguyên Từ Thần Quang. Sau hơn một tháng lên đường, Hàn Lập tới hải vực gần Thiên Tinh thành và bắt gặp đoàn viện quân Bạch Thủy Kiếm Tông bị Nghịch Tinh Minh phục kích. Phần lớn đoàn tu sĩ bị tiêu diệt, còn Lỗ huynh cùng hai tu sĩ Kết Đan hợp độn phá vây nhưng bị Càn Khôn võng giam giữ. Hàn Lập bất ngờ xuất hiện, giải cứu ba người và dùng hồng tuyến giết chết người trung niên cầm đầu toán phục kích khi y bỏ chạy. Những tu sĩ Nghịch Tinh Minh còn lại mất ý chí phản kháng, buộc phải xác nhận Thiên Tinh thành đang bị bao vây. Hàn Lập tiếp tục chất vấn cách Nghịch Tinh Minh có thể phong tỏa một đại thành tập trung hàng vạn tu sĩ."},{"chuong":1201,"tieuDe":"Tinh Cung Chi Chiến 2","tomTat":"Đại hán mặt ngựa tiết lộ với Hàn Lập rằng Vạn Thiên Minh đã dùng một trăm lẻ tám Phong Hỏa đồng trụ dựng Phong Hỏa Thiên Tuyệt trận vây Thiên Tinh thành. Hàn Lập giải thoát ba tu sĩ Bạch Thủy Kiếm Tông khỏi Càn Khôn võng rồi truy đuổi hai tu sĩ Chấp Pháp đường đang dùng Hoàng Sa Tu Di Phiên thuấn di bỏ chạy. Hắn đánh trọng thương và giết cả hai trước khi họ hoàn thành thủ đoạn liều mạng, sau đó thu hai cổ bảo cùng Càn Khôn võng. Những tu sĩ Chấp Pháp đường còn lại bị năm nhóm Phệ Kim Trùng truy sát và thôn phệ, khiến ba người Bạch Thủy Kiếm Tông kinh hãi. Hàn Lập khuyên họ rút lui vì tu vi không đủ vượt qua vòng vây rồi một mình tiếp tục lên đường. Hắn thi triển ẩn độn thuật vượt qua nhiều toán phục binh của Nghịch Tinh Minh và tới sát Thiên Tinh thành, nơi cự đảo đang bị quang hà xanh đỏ bao phủ. Trên mặt biển trước thành, Hàn Lập phát hiện một hạm đội linh thuyền đông đảo với đủ kiểu dáng, kích thước và vật liệu."},{"chuong":1202,"tieuDe":"Tinh Cung Chi Chiến 3","tomTat":"Hàn Lập nhận ra ba cự trụ trước mặt là Phong Hỏa Trụ và ước lượng Nghịch Tinh Minh đã bố trí hàng nghìn tu sĩ cùng cường giả Nguyên Anh trấn giữ trận điểm. Sau khi đánh giá Phong Hỏa Thiên Tuyệt trận khó vây được mình, hắn vòng qua linh thuyền rồi trực tiếp xông vào cấm chế. Trên lâu thuyền, Trữ hiền chất trò chuyện với Long tiền bối và Hoa đạo hữu, qua đó làm rõ việc Vạn Thiên Minh dùng Thiên Thụy đảo cùng nhiều tài liệu quý hiếm để mời các tu sĩ Nguyên Anh trợ chiến. Khi Phong Hỏa Trụ báo động có người xâm nhập, Long và Hoa lên Thiên Phong Xa, dùng pháp bàn truy tung cùng bí thuật ẩn nấp để bí mật tiếp cận Hàn Lập. Hai người không nhận ra hắn và cho rằng liên thủ đủ sức đối phó một tu sĩ Nguyên Anh trung kỳ. Ngay trước lúc cuộc phục kích bắt đầu, Hàn Lập nhìn thẳng lên vị trí ngọc xa, hiện đôi cánh rồi biến mất. Long tiền bối lập tức rót pháp lực vào Thiên Phong Xa để dựng thanh quang bảo vệ, còn Hoa đạo hữu tung Bát Quái Kính hai màu đen trắng lên trên đầu chuẩn bị ứng chiến."},{"chuong":1203,"tieuDe":"Tinh Cung Chi Chiến (4)","tomTat":"Hàn Lập điều khiển hơn mười kim sắc tiểu kiếm phá tan quang tia từ Kính Bát Quái và quang đoàn bảo vệ Ngọc xa, buộc Hoa đạo hữu cùng Long tiền bối chia hướng bỏ chạy. Hắn dùng công kích thần thức làm Hoa đạo hữu không kịp thúc giục bảo vật, lấy hỏa tác trói đối phương và dùng Bát Linh Xích giam cầm Xích Ngỗ Đại Linh điểu. Hoa đạo hữu bị chém đầu, thiêu hủy thân thể, còn Nguyên Anh vừa thoát ra đã bị kim võng lôi hồ đánh tan. Long tiền bối chứng kiến đồng bạn tử vong liền tự đoạn một cánh tay, dùng huyết vụ thi triển độn thuật cực nhanh và thoát khỏi tầm truy tìm. Hàn Lập không tiếp tục truy sát, giết linh điểu không thể thuần hóa rồi toàn lực tới Thiên Tinh Thành, nơi Nghịch Tinh Minh đang công kích quang mạc bảo vệ thành. Các thủ vệ Tinh Cung kiểm tra lệnh bài khách khanh và báo tin cho cung chủ thay vì lập tức mở cấm chế. Lăng Ngọc Linh đích thân tới xác nhận Hàn Lập, bác bỏ nghi ngờ giả mạo và ra lệnh cho các thủ vệ dùng trận kỳ, trận bàn mở cửa thành."},{"chuong":1204,"tieuDe":"Tinh Cung Chi Chiến 5","tomTat":"Hàn Lập vượt qua cấm chế tiến vào Thiên Tinh Thành và được Lăng Ngọc Linh đón tới Thánh Điện trên đỉnh Thánh Sơn. Nàng cho biết Vạn Thiên Minh đã tiến lên Nguyên Anh hậu kỳ, giúp Nghịch Tinh Minh đảo ngược thế cờ, cắt dần các thế lực ngoại vi và vây ép Tinh Cung. Lăng Ngọc Linh muốn Hàn Lập đối kháng Vạn Thiên Minh, đồng thời mượn uy thế khó dò của hắn để trấn nhiếp Mã trưởng lão cùng phe trưởng lão chưa phục tân cung chủ. Hơn hai mươi trưởng lão Tinh Cung tập hợp tại Thánh Điện, trong đó Hàn Lập gặp lại Triệu trưởng lão và Tây Môn trưởng lão. Tây Môn trưởng lão lo sợ vì từng suýt giết Hàn Lập tại Hư Thiên Điện, nhưng Hàn Lập tạm thời không truy cứu chuyện cũ. Trước toàn thể trưởng lão, Hàn Lập khẳng định giao ước ba lần tương trợ chỉ buộc hắn cứu Lăng Ngọc Linh khi nàng gặp nguy hiểm đến tính mạng và trong phạm vi năng lực của mình. Hắn từ chối coi việc liều mạng giao chiến với Vạn Thiên Minh vì sự tồn vong của Tinh Cung là nghĩa vụ, khiến cả Thánh Điện lặng ngắt."},{"chuong":1205,"tieuDe":"Tinh Cung Chi Chiến (6)","tomTat":"Lăng Ngọc Linh mời Hàn Lập trợ giúp Tinh Cung, nhưng hắn chỉ chấp nhận tham chiến nếu nhận được thù lao đủ sức khiến mình động tâm. Nàng dùng phương pháp tu luyện Nguyên Từ Thần Quang và Nguyên Từ Thần Sơn làm điều kiện, đổi lại Hàn Lập nhận trách nhiệm kiềm chế Vạn Thiên Minh trong trận quyết chiến. Trước khi rời Thạch Điện, Hàn Lập bí mật lưu ấn ký thần niệm lên Tây Môn trưởng lão, kẻ từng dùng phi kiếm suýt lấy mạng hắn. Sau đó, Lăng Ngọc Linh bác bỏ nghi vấn Hàn Lập cấu kết với Nghịch Tinh Minh và xác định hộ thành đại trận không thể chống đỡ lâu, buộc Tinh Cung phải quyết chiến. Hàn Lập phái khôi lỗi hình người bí mật truy sát Tây Môn trưởng lão, đồng thời tìm Triệu trưởng lão trao đổi công pháp Mộc hệ để tạo biểu hiện rằng mình vẫn ở cùng người khác. Nửa ngày sau, Nguyên Thần Linh Đăng của Tây Môn trưởng lão tắt; các trưởng lão Tinh Cung khám xét động phủ nhưng chỉ thấy mật thất trống rỗng, không có người hay thi thể. Các đệ tử thân tín cho biết Đỗ lão giả từng tiến vào động phủ, song thân phận và quan hệ của người này với Tây Môn trưởng lão vẫn chưa được xác nhận."},{"chuong":1206,"tieuDe":"Tinh Cung Chi Chiến 7","tomTat":"Cao tầng Tinh Cung nhận ra Hàn Lập có thể liên quan đến sự biến mất của Tây Môn trưởng lão, nhưng vì e ngại thực lực của hắn nên chỉ xử lý hậu sự sơ sài và ngầm biến chuyện này thành điều cấm kỵ. Năm ngày sau, Hàn Lập tới Thánh Điện, nơi uy thế từ việc Nhân hình Khôi Lỗi giải quyết một tu sĩ Nguyên Anh sơ kỳ khiến các trưởng lão cùng hơn ba mươi tu sĩ Kết Đan hậu kỳ đều kính sợ. Lăng Ngọc Linh công bố kế hoạch tiến công ba mươi sáu Phong Hỏa trụ trọng yếu, với mục tiêu phá quá nửa số trụ để làm Phong Hỏa Thiên Tuyệt Trận tự tan. Hàn Lập được xếp cùng nàng, Mã trưởng lão và Triệu trưởng lão vào đội đánh mắt trận, nhưng tuyên bố mình chỉ phụ trách đối phó Vạn Thiên Minh. Trước khi xuất quân, hắn tiếp tục tham ngộ khẩu quyết Nguyên Từ Thần Quang nhưng mới lĩnh hội được một phần nhỏ và hy vọng Nguyên Từ Thần Sơn sẽ hỗ trợ việc tu luyện. Các đội tu sĩ rời Thánh Điện để hội quân với lực lượng Trúc Cơ tại bốn cửa Thiên Tinh Thành. Bên ngoài Thạch Điện, Hàn Lập phát hiện bốn thân giao long kéo Cự xa Lục Giao thực chất chứa tinh hồn Thâm hải Tinh mãng. Lăng Ngọc Linh cho biết cỗ xe do cha nàng luyện chế, có không gian huyền diệu và công hiệu phá địch, nên được đưa ra sử dụng trong trận chiến quyết định sự tồn vong của Tinh Cung."},{"chuong":1207,"tieuDe":"Tinh Cung Chi Chiến 8","tomTat":"Hàn Lập cùng các trưởng lão Tinh Cung đi thú xa tới đại môn Thiên Tinh Thành, nơi hơn hai ngàn tu sĩ thấp giai đang hoàn tất chuẩn bị giữa lúc quang mạc hộ thành liên tục bị phong hỏa chi lực công kích. Trước cuộc quyết chiến, Lăng Ngọc Linh thừa nhận Tinh Cung chỉ có khoảng một nửa cơ hội thắng và giao cho Hàn Lập ngọc giản ghi địa điểm của những người thân cận với nàng. Nàng dùng lần tương trợ thứ hai trong giao ước để nhờ hắn đưa họ rời khỏi Tinh Hải nếu Tinh Cung đại bại, và Hàn Lập chấp nhận lời gửi gắm. Sau khi mọi lực lượng sẵn sàng, mấy vạn tu sĩ Tinh Cung đồng loạt rời quang tráo, tiến vào Phong Hỏa Thiên Tuyệt Trận và giao chiến với quân Nghịch Tinh Minh quanh các Phong Hỏa trụ. Phù lục hộ thân được chuẩn bị từ trước giúp lực lượng thấp giai của Tinh Cung giảm thương vong khi vượt qua phong hỏa chi lực. Trên một cự trụ, Long tu sĩ thuật lại lần chạm trán Hàn Lập và khẳng định hắn là tu sĩ Nguyên Anh hậu kỳ. Vạn Thiên Minh dựa vào dung mạo cùng tình báo cũ để nhận ra Hàn Lập là người từng bị truy sát vì Hư Thiên Đỉnh, đồng thời nghi hắn có liên quan đến sự mất tích của Diệu Hạc chân nhân."},{"chuong":1208,"tieuDe":"Tinh Cung Chi Chiến 9","tomTat":"Vạn Thiên Minh tiết lộ Diệu Hạc và Hoàng Côn thực ra đã mất tích tại Bích Linh đảo, còn Nguyên Thần mệnh đăng của họ cũng tự tắt đúng vào thời điểm Hàn Lập xuất hiện. Dù không có chứng cứ trực tiếp, hắn nghi Hàn Lập là hung thủ, nhận định đối phương đã trở thành đại tu sĩ và tuyên bố mình có kế sách ứng phó. Theo tín hiệu của Vạn Thiên Minh, Lam thị Song ma rời Ma Nghiệt đảo tái xuất, trở thành viện thủ bí mật bảo vệ trận nhãn. Cùng lúc đó, Cự xa Lục Giao dẫn theo khoảng vài nghìn tu sĩ Tinh Cung tiến ra, khiến hai phe hình thành thế giằng co quanh Phong Hỏa cự trụ. Mã trưởng lão và Triệu trưởng lão xác nhận Song ma đều là tu sĩ Nguyên Anh trung kỳ, có hung danh hiển hách và đủ sức tự bảo vệ trước đại tu sĩ khi liên thủ. Hàn Lập cùng Lăng Ngọc Linh vì thế nhận ra cán cân lực lượng đã trở nên bất lợi, phe Tinh Cung có thể chỉ duy trì được thế bất bại. Trước khi giao chiến, Vạn Thiên Minh một mình tiến ra và công khai đề nghị trả gấp đôi mọi ưu đãi của Tinh Cung để đổi lấy việc Hàn Lập đứng ngoài đại chiến."},{"chuong":1209,"tieuDe":"Tinh Cung Chi Chiến 10","tomTat":"Vạn Thiên Minh đưa ra điều kiện hậu hĩnh nhằm thuyết phục Hàn Lập đổi ý, nhưng Hàn Lập từ chối vì muốn giữ lời hứa năm xưa và chỉ chấp nhận bỏ qua nếu đối phương rút lui. Hai người rời chiến trường để giao thủ riêng, khiến Lăng Ngọc Linh và Triệu trưởng lão lo lắng nhưng không dám can ngăn vì sợ ảnh hưởng sĩ khí. Khi họ đi khỏi, Lam thị nam ma, Lam thị nữ ma cùng các tu sĩ hai phe đồng loạt xuất thủ, mở ra trận hỗn chiến trên phạm vi rộng ngoài Thiên Tinh Thành. Vạn Thiên Minh dẫn Hàn Lập tới một vùng biển cách chiến trường gần ngàn dặm rồi thả hai cỗ luyện thi từ túi da màu đen. Hàn Lập kiểm tra xung quanh, lấy Bát Linh Xích và Tam Diễm Phiến, đồng thời chuẩn bị dùng đôi cánh thanh bạch áp sát để tung đòn toàn lực. Trước khi hắn ra tay, ma khí xám trắng bùng lên và một người mặc phục sức Vạn Thiên Minh nhưng có diện mạo hoàn toàn khác bước ra cùng sáu ma ảnh. Hàn Lập nhận ra Lục Cực Chân Ma Công và kinh ngạc trước chân dung vừa xuất hiện."},{"chuong":1210,"tieuDe":"Tinh Cung Chi Chiến 11","tomTat":"Hàn Lập nhận ra kẻ mang hình dạng Vạn Thiên Minh đang thi triển Lục Cực Chân ma công và chất vấn đối phương có phải Lục Đạo Cực Thánh đã đoạt xá hay không. Lục Đạo không giải đáp mà gọi hai phân niệm thánh ma nhập vào luyện thi, biến chúng thành hai ma vật có thần thông tương đương tu sĩ Nguyên Anh hậu kỳ. Khi hai ma vật giáp công, Hàn Lập dùng đôi cánh thanh bạch thuấn di thoát hiểm rồi lấy Thanh sắc Mộc Xích khóa song giác ma vật. Hắn lần lượt dùng Nguyên Cương Thuẫn và Kim Cương Tráo chống Huyết Cốt Thứ, sau đó kích phát Tam Diễm Phiến tiêu diệt song giác ma vật. Lục Đạo lập tức điều động tứ nhãn ma vật, bốn hư ảnh yêu ma còn lại và Ô Hắc Bát Giác Chùy mở đợt vây công mới. Thanh sắc nhân ảnh xuất hiện đánh bật tứ nhãn ma vật, còn thanh sắc tiểu đỉnh phun quang tia giữ ma chùy đứng yên giữa không trung."},{"chuong":1211,"tieuDe":"Tinh Cung Chi Chiến 12","tomTat":"Hàn Lập dùng kim hồ tiêu diệt bốn ma ảnh, đồng thời lấy thanh ti từ Hư Thiên Đỉnh kiềm chế Ô Hắc Bát Giác Chùy. Nguyên Anh thứ hai tự chủ điều khiển nhân hình khôi lỗi, dùng hỏa tiễn và Thúy Lục Tiểu Tiễn dẫn dụ ma vật hình nhím vào hướng phục kích của Ma Tủy Phi Đao. Phi đao xuyên qua huyết sắc quang tráo, chém đầu ma vật, sau đó ma ảnh bị thu lấy để bổ trợ việc tu luyện Cực Âm Đại Pháp còn tàn thi hóa thành tro. Chứng kiến hai ma vật cấp Nguyên Anh hậu kỳ đều bị tiêu diệt, Lục Đạo Cực Thánh mất ý chí giao chiến và dùng bản mệnh pháp bảo hóa thành hắc phong đào tẩu. Hàn Lập vận dụng Phong Lôi Sí đuổi vượt đối thủ rồi chặn đường. Sau khi thi triển tầng thứ ba Minh Vương Quyết, Hàn Lập áp sát qua hư không, chém rơi Xích Hồng Thuẫn Bài cùng nửa cánh tay của Lục Đạo và dùng tử sắc tinh băng phong kín vết chặt."},{"chuong":1212,"tieuDe":"Tinh Cung Chi Chiến 13","tomTat":"Sau khi dùng Tật Phong Cửu Biến chặt đứt tay Lục Đạo Cực Thánh, Hàn Lập nhận ra thân thể trở nên nặng nề và được Đồng tử cảnh báo rằng Minh Vương Quyết tầng ba chỉ đủ sức hỗ trợ khoảng hai hoặc ba lần thi triển. Biết không thể thoát khỏi độn tốc Phong Lôi hợp nhất, Lục Đạo Cực Thánh gọi quái mãng hai đầu, dựng phòng ngự và tế Tam Thần Bạch Cốt Phiên phỏng chế để tử chiến. Hàn Lập thả Ngũ Tử Đồng Tâm Ma ra áp chế hắc khí, buộc lão ma dùng tinh huyết tăng cường cốt phiên và ngưng tụ Hắc Giao cầm chân hai ma. Trong lúc đối phương tập trung điều khiển tà khí, đệ nhị Nguyên Anh ẩn trong nhân hình khôi lỗi bí mật dùng Ma Tủy Phi Đao xuyên qua Hắc Phong và phá thủng quang tráo. Hàn Lập đồng thời gọi Bát Linh Xích rồi dùng Phong Lôi Sí biến mất, còn Lục Đạo Cực Thánh phải phóng hắc mang chặn phi đao và hóa thành hai hư ảnh chạy về hai hướng."},{"chuong":1213,"tieuDe":"Tinh Cung Chi Chiến 14","tomTat":"Ô Hắc Song Thủ Quái Mãng phun khói độc phối hợp với Lục Đạo Cực Thánh, nhưng độc tố hoàn toàn vô hiệu trước Nhân hình Khôi Lỗi không có huyết nhục và hô hấp. Khôi Lỗi dùng thất sắc phật quang giữ cứng linh thú rồi chém rơi cả hai đầu, trong khi Hàn Lập dùng Minh Thanh Linh Mục nhìn thấu Phân Ảnh Thuật và xác định chân thân Lục Đạo. Sau khi phá Lam Sắc Ngọc Tán, Hàn Lập áp sát, xuyên thủng thân thể lão ma và buộc đối phương tự nổ phần thân dưới để bản mệnh Nguyên Anh đào thoát. Nhân hình Khôi Lỗi đã chặn sẵn đường chạy, dùng Ô Hắc Phi Đao chém đôi Nguyên Anh rồi phóng tiểu tiễn Kim Lôi Trúc mang Ích Tà Thần Lôi tiêu diệt toàn bộ sáu phân hồn. Lục Đạo Cực Thánh vì thế thần hình câu diệt, còn Lục Sắc Ngọc Bình do lão mang theo rơi vào tay Hàn Lập nhưng chưa được mở nắp kiểm tra. Trên chiến trường còn lại, Cốt Phiên mất người điều khiển nên suy giảm uy lực, tạo cơ hội để Ngũ Tử Đồng Tâm Ma hợp thành Ngũ Sắc Hỏa Hải và dùng băng nhận cắt nát Hắc Giao."},{"chuong":1214,"tieuDe":"Linh Căn Và Ngũ Hành Hợp Nhất","tomTat":"Ngũ Tử Đồng Tâm Ma hóa thành năm mặt quỷ khổng lồ, cắn nuốt hai trong ba đầu khô lâu và áp đảo đầu còn lại. Thiên Lan thánh thú phân thân hiện trên Hư Thiên Đỉnh, nhận xét Ngũ Sắc Hàn Diễm của Hàn Lập dễ bị hiểu nhầm thành công pháp ngũ hành tại Linh Giới. Nó tiết lộ ngũ hành hợp nhất là mấu chốt tiến vào Luyện Hư Kỳ, đồng thời giải thích hai cách bổ sung thuộc tính còn thiếu bằng Đan Linh căn và Khí Linh căn. Hàn Lập còn biết tu sĩ Linh Giới từ Nguyên Anh trở lên phải chịu thiên kiếp định kỳ, khiến thọ nguyên lâu dài không đồng nghĩa với bất tử. Sau khi cân nhắc con đường tu luyện tương lai, hắn mở Lục Sắc Ngọc Bình và bắt lại một Nguyên Anh nữ tu đang định bỏ trốn. Nữ tu hỏi tung tích Lục Đạo Cực Thánh, rồi kinh hãi và dường như nhận ra Hàn Lập khi nghe hắn xác nhận đã giết lão ma."},{"chuong":1215,"tieuDe":"Phá Trận","tomTat":"Nguyên Anh nữ tu bị giam trong Lục Sắc Ngọc Bình nhận ra Hàn Lập và xác nhận mình là Ôn phu nhân, người từng gặp hắn tại Hư Thiên Điện. Sau khi nhìn thấy tàn thi Lục Đạo Cực Thánh và biết đại thù đã được báo, nàng cho biết Nguyên Anh đã suy kiệt đến mức không thể sống lại rồi tự tán để cầu luân hồi. Hàn Lập thu Lục Sắc Ngọc Bình cùng túi trữ vật của Lục Đạo, tiêu hủy tàn thi lão ma và để Ngũ Tử Đồng Tâm Ma ăn hết Tam Thần Bạch Cốt Phiên phỏng chế. Trở lại mắt trận Phong Hỏa Thiên Tuyệt Đại Trận, hắn thấy Nghịch Tinh Minh đang tạm chiếm thượng phong nhờ Lam Thị Song Ma áp đảo lực lượng Tinh Cung. Hàn Lập phái Ngũ Tử Đồng Tâm Ma tập kích Song Ma, đồng thời chia Kim Sắc Trùng Vân thành mười đoàn tỏa ra chiến trường. Sau đó hắn dùng Phong Lôi Sí âm thầm tiếp cận Phong Hỏa Cự Trụ, bắn kiếm khí giết sạch nhóm tu sĩ Kết Đan canh giữ. Chương kết thúc khi Hàn Lập hợp hơn mười Kim Sắc Tiểu Kiếm thành một cự kiếm dài vài trượng và phóng nó về phía cự trụ."},{"chuong":1216,"tieuDe":"Nguyên Từ Thần Sơn","tomTat":"Hàn Lập dùng Cự Kiếm hóa thành Kim sắc Giao chém đôi Phong Hỏa Cự Trụ, phá hủy mắt trận của Phong Hỏa Thiên tuyệt đại trận và khiến sĩ khí Nghịch Tinh Minh sụp đổ. Các đoàn Phệ Kim trùng do hắn điều khiển tiếp tục thôn phệ pháp khí, pháp bảo cùng hơn mười tu sĩ, làm quân địch tan tác; Lam Thị Song Ma phá vây nhưng bị Hàn Lập chặn đường và tiêu diệt. Trong những tháng tiếp theo, Tinh Cung phản công tới tổng đàn, còn Hàn Lập giết hai trong ba tu sĩ Nguyên Anh trung kỳ vây công mình. Sau nửa năm, Lăng Ngọc Linh vừa chiêu hàng tu sĩ cấp thấp vừa truy sát các trưởng lão còn lại, giúp Tinh Cung tái lập quyền thống trị Nội Tinh Hải và khiến Nghịch Tinh Minh tan rã. Nửa năm sau nữa, nàng dẫn Hàn Lập vào cấm địa Thánh Sơn và kể rằng Nguyên Từ Thần Sơn được cha mẹ mình tìm thấy tại Ngoại Hải rồi đưa về luyện hóa bằng Nguyên Từ Thần Quang. Thiên Tinh Song Thánh đến khi qua đời vẫn chưa luyện hóa được một nửa ngọn núi, trong khi Ngũ hành chi lực của nó có thể khiến tu sĩ phản phệ linh lực và tổn hại tu vi. Lăng Ngọc Linh dùng Tuyết Bạch Ngọc bài mở cấm chế, còn hai người lần lượt dùng Lam Sắc Ngọc Câu và Kim Cương Trảo hộ thân. Dù đã chuẩn bị, Hàn Lập vẫn phải vận Thanh Nguyên Kiếm Quyết trấn áp mộc linh lực rối loạn, còn Lăng Ngọc Linh cũng bị khí huyết quay cuồng."},{"chuong":1217,"tieuDe":"Ngũ Hành Chi Lực","tomTat":"Lăng Ngọc Linh dẫn Hàn Lập vào động quật khổng lồ cất giữ Nguyên Từ Sơn và kể rằng cha mẹ nàng từng mất hơn mười năm đưa ngọn núi từ Ngoại Hải về. Hàn Lập dùng Minh Thanh Linh Mục, thần niệm cùng nhiều pháp quyết khảo sát nhưng đều bị Ngũ Hành chi lực của núi ngăn cản. Khi hắn đặt tay lên sơn thể và cưỡng ép rót pháp quyết, Nguyên Từ Sơn hút ngược nguyên linh lực, buộc hắn phải vận hộ tráo và đánh mạnh vào vách núi để thoát ra. Hàn Lập quyết định lưu lại vài ngày tìm phương pháp thu núi, nhận Ngọc Bài từ Lăng Ngọc Linh rồi đóng kín Ngọc Môn và bố trí mê vụ che phủ động quật. Sau khi Thiên Lan thánh thú phân thân hiện thân, Hàn Lập phân tích rằng Nguyên Từ Thần Quang tuy có thể hỗ trợ đột phá Hóa Thần nhưng cũng có nguy cơ khiến người luyện bị Nguyên Từ Sơn ràng buộc. Không muốn bị giữ lại Thiên Tinh Thành và phải gia nhập Tinh Cung, hắn ưu tiên tìm cách mang núi đi mà không luyện công pháp, còn Thiên Lan thánh thú đề nghị hắn thử tu luyện rồi từ từ dời núi."},{"chuong":1218,"tieuDe":"Xích Hồn Phiên","tomTat":"Hàn Lập thử dùng phù triện, pháp bàn và nhiều loại pháp quyết nhưng vẫn không thể thu nhỏ Nguyên Từ Sơn để mang qua Truyền Tống Trận về Thiên Nam. Không muốn bị ngọn núi ràng buộc hoặc khiến Lạc Vân Tông gặp họa, hắn quyết định ưu tiên mượn Hàn Diễm của Ngũ Ma để thử đột phá Hóa Thần, còn Nguyên Từ Thần Quang chỉ là phương án dự phòng. Tinh Cung công bố hắn trở thành Khách khanh trưởng lão và sẽ bế quan trăm năm tại Thánh Sơn, qua đó chấn nhiếp các thế lực ở Loạn Tinh Hải, nhưng thực tế hắn đã bí mật rời Thiên Tinh Thành. Hàn Lập thừa nhận mình chỉ nhận hư danh để đổi lấy mấy trăm vạn linh thạch và không có ý định chiếm đoạt Tinh Cung vì mục tiêu quan trọng nhất vẫn là tu luyện rồi phi thăng Linh Giới. Trên đường rời đi, hắn lấy phần Hắc Phong Kỳ tàn khuyết cho Đồng tử kiểm tra và biết đây vốn là không gian linh bảo thuộc Tiên giới, có thể được luyện lại thành bảo vật cấp thấp hơn. Đồng tử đề xuất luyện nó thành Xích Hồn Phiên, nhưng muốn bảo vật đủ sức chứa Nguyên Từ Sơn thì phải tế luyện mấy trăm vạn sinh hồn."},{"chuong":1219,"tieuDe":"Đánh Sâu Vào Hóa Thần Kỳ","tomTat":"Đồng tử cho Hàn Lập biết Xích Hồn Phiên chân chính cần tới hàng ngàn vạn sinh hồn và có thần thông không gian, nhưng Hàn Lập từ chối con đường đồ thành diệt đảo để thu thập nguyên liệu. Hắn chuyển sang dự tính tế luyện tinh hồn trong các Quỷ La Phiên, đồng thời cân nhắc nhưng tạm gác Vạn Yêu Phiên của Xa lão yêu vì không muốn đối đầu với một yêu thú Hóa Thần kỳ. Đồng tử đồng ý truyền phương pháp luyện chế Xích Hồn Phiên, còn Hàn Lập quyết định chỉ thu các Quỷ La Phiên còn lại sau khi tu vi và hàn diễm của Ngũ Ma đạt yêu cầu. Hắn dùng thượng cổ Truyền Tống Trận trở về Thiên Nam, thu lại Lục Dực Sương Công, phá hủy trận rồi quay về Tử Mẫu Phong và giao Liễu Ngọc thu thập tài liệu phụ trợ. Trong hơn năm mươi năm tiếp theo, Hàn Lập tu luyện tầng cuối Thanh Nguyên Kiếm Quyết cùng hàn diễm của Ngũ Ma, chỉ tạm ngừng để cùng Nam Cung Uyển du lịch hơn nửa năm. Cuối chương, sấm sét vang trời và thiên địa nguyên khí trong phạm vi mấy trăm dặm hội tụ thành linh vân trên động phủ của hắn, khiến Nam Cung Uyển cùng các cao tầng Lạc Vân Tông đồng loạt tới quan sát."},{"chuong":1220,"tieuDe":"Một Lần Nữa Đi Xa","tomTat":"Sau nhiều lần ngưng kết Nguyên Anh thất bại, Liễu Ngọc từ bỏ hy vọng tiến giai và chuyên tâm trợ giúp Lữ Lạc quản lý Lạc Vân Tông. Tại Tử Mẫu Phong, Nam Cung Uyển cùng các tu sĩ quan sát thiên tượng khi Hàn Lập lần đầu trùng kích Hóa Thần, nhưng Linh Vân không thể hạ xuống dung hợp và cuối cùng tan vỡ. Hàn Lập triệu tập Nam Cung Uyển, Lữ Lạc, nữ tử họ Tống và Liễu Ngọc, thông báo rằng hắn sẽ rời Thiên Nam để tìm kiếm cơ duyên mới. Ba tháng sau, hắn rời Lạc Vân sơn mạch, còn tông môn chỉ công bố đại trưởng lão ra ngoài du ngoạn. Việc Hàn Lập chưa thành Hóa Thần khiến nhiều tông môn Thiên Nam âm thầm nhẹ nhõm vì không phải đối diện một cường giả có thọ nguyên vượt xa hiện tại. Chương cũng xác nhận Ngụy Vô Nhai đã tọa hóa hơn một trăm năm trước, khiến Cửu Quốc Minh rung chuyển sau khi tin tức bị phong tỏa được công bố. Kết cục của Ngụy Vô Nhai càng khiến Hàn Lập kiên định rằng quyền thế và thần thông đều vô nghĩa nếu không thể vượt qua giới hạn thọ nguyên để đạt tới trường sinh."},{"chuong":1221,"tieuDe":"Thiên Cơ Điện","tomTat":"Hàn Lập bay qua Mộ Lan thảo nguyên để trở lại Đại Tấn, quyết định vừa đoạt những Quỷ La Phiên còn lại vừa tìm cơ hội sát diệt Phòng tông chủ nhằm trừ hậu họa cho Nam Cung Uyển và Lạc Vân Tông. Trước khi bắt đầu tu luyện Nguyên Từ Thần Quang và bị ràng buộc tại một nơi, hắn muốn xử lý các việc quan trọng, trong đó có tìm Thái Dương Tinh Hỏa để phối hợp với hàn tủy luyện Hồi Dương Thủy. Hắn còn định lấy bí thuật của Thiên Cơ Các để luyện không gian Linh Miểu Viên thành giới tử không gian dùng cất giữ bảo vật hoặc làm nơi tu luyện an toàn. Hơn nửa năm sau, Trương đạo hữu mang hình dạng hoàng y đại hán cầm dù trắng tiến vào bí cảnh của Thiên Cơ Các trong một tiểu sơn thành thuộc Đại Tấn. Sau khi vượt qua nhiều tầng cấm chế, ông tới Đại Ngọc môn và yêu cầu Tào Phong Duy lập tức báo việc trọng đại cho Các chủ. Tào Phong Duy từ chối vì Các chủ đang tiếp khách quý, nhưng Trương đạo hữu cảnh báo rằng để Hàn Lập chờ có thể khiến Thiên Cơ Các gặp đại họa. Ngay sau đó, giọng Hàn Lập vang lên trên đầu hai người và tự xác nhận mình chính là nhân vật được nhắc tới."},{"chuong":1222,"tieuDe":"Khách Ngoài Ý Muốn","tomTat":"Hàn Lập bí mật tiến vào giới tử không gian của Thiên Cơ Điện, khiến Tào Vĩ Phong điều động khôi lỗi nghênh chiến trước khi bạch diện trung niên kịp ngăn lại. Sau khi xác nhận hắn là đại tu sĩ Nguyên Anh hậu kỳ, Tào Vĩ Phong nhận lỗi, thu khôi lỗi và dẫn đường lên tổng điện. Trên đường đi, Hàn Lập nhớ lại hành trình nửa năm vượt Mộ Lan thảo nguyên và quyết định không trả thù Đột Ngột tộc vì các tu sĩ cao giai của họ đã tập trung tại Thiên Lan Thánh Điện. Hắn tới Đại Tấn để mua bí pháp luyện chế giới tử không gian, nhưng chưởng quỹ phân hào không có thẩm quyền nên phải trở về tổng điện thỉnh thị; thay vì chờ đợi, Hàn Lập đã dùng bí thuật truy tung để bám theo. Tào Vĩ Phong dùng Truyền Âm Phù báo trước, khiến Thiên Cơ Điện nổi chuông và hơn mười tu sĩ ra nghênh tiếp. Hàn Lập dùng thân pháp vượt lên trước cửa điện, làm một số tu sĩ hoảng hốt đề phòng. Lão giả mập mạp quát họ lui xuống, gọi Hàn Lập là đạo hữu, còn Hàn Lập hỏi lại ông có phải Thiên Cơ Các Các chủ hay không."},{"chuong":1223,"tieuDe":"Phật Tông Cao Nhân","tomTat":"Hàn Lập gặp Sán Khổ, người chấp chưởng Thiên Cơ Các, cùng tăng nhân trẻ tuổi Diễm Trúc tại Thiên Cơ Điện. Khi biết Hàn Lập muốn mua phương pháp luyện chế giới tử không gian, Sán Khổ từ chối vì việc truyền bí pháp sẽ phá vỡ vị thế độc quyền của Thiên Cơ Ốc và Thiên Cơ Phủ. Ông đề xuất một bộ khí cụ bày giới tử pháp trận có thể cải tạo khe không gian, nhưng phương án này tiêu hao nhiều linh thạch và chỉ duy trì được hai đến ba nghìn năm. Do khe không gian mình phát hiện vốn bất ổn, Hàn Lập bác bỏ giải pháp thay thế và kiên quyết đòi bí pháp chân chính. Đúng lúc Sán Khổ do dự, Nguyên Trí đại sư của Lôi Âm Tông đột ngột tiến vào, yêu cầu Hàn Lập luận bàn với mình trước khi tiếp tục xét chuyện bí pháp. Khi Nguyên Trí dò hỏi lai lịch, Diễm Trúc bất ngờ ám chỉ rằng sư huynh mình chắc chắn từng nghe thanh danh Hàn Lập, khiến những người có mặt đều chú ý."},{"chuong":1224,"tieuDe":"Giao Thủ","tomTat":"Diễm Trúc nhận ra Hàn Lập là người từng can dự các biến cố tại Côn Ngô Sơn và Tiểu Cực Cung, khiến Nguyên Trí cùng Sán Khổ hiểu rõ hơn lai lịch và chiến tích của hắn. Diễm Trúc giải thích rằng Âm La Tông và Tiểu Cực Cung tuy đã tra ra xuất thân Thiên Nam của Hàn Lập nhưng đều tổn thất lực lượng cấp cao, lại bị các thế lực khác dòm ngó nên không tiện tiếp tục đối đầu. Nguyên Trí vẫn nhất quyết muốn luận bàn để tìm cơ hội lĩnh ngộ, còn Hàn Lập chỉ chấp thuận sau khi Sán Khổ đồng ý giao bí thuật luyện chế giới tử không gian nếu hắn chiếm thế thượng phong. Hai đại tu sĩ rời Thiên Cơ Điện và bắt đầu giao chiến trên không, Nguyên Trí vận chuyển tầng bốn Minh Vương Quyết trong khi Hàn Lập tung Thanh Trúc Phong Vân Kiếm phân hóa thành hàng trăm kiếm quang. Nguyên Trí dùng thiền trượng luyện từ vạn năm hỏa san hô hóa thành xích giao chống lại kim hà kiếm quang, đồng thời lấy Phật châu xanh tạo quang mạc hộ thân. Nhận ra đối phương có vật liệu đủ sức kháng phi kiếm khảm Canh Tinh, Hàn Lập chia kiếm quang thành hai phần, vừa kiềm chế xích giao vừa vòng sang công kích trực tiếp Nguyên Trí."},{"chuong":1225,"tieuDe":"Tung Hoành Nhân Giới","tomTat":"Hàn Lập hợp hơn trăm đạo kiếm quang thành một băng kiếm khổng lồ nhờ hàn khí của Huyền Ngọc, buộc Nguyên Trí đại sư dùng bạch sắc quang liên né tránh rồi triệu kim cương hư ảnh chống đỡ. Nguyên Trí cùng hư ảnh giữ cự kiếm giữa không trung, phun kim sắc hà quang đẩy lui điện mãng và định vận dụng lực lượng kim cương Bát Nhã bẻ gãy kiếm. Qua màn giao phong, Hàn Lập nhận ra kim cương hư ảnh do pháp lực của tăng nhân tạo thành và được Minh Vương Quyết hỗ trợ, khác với ma ảnh của Lục Cực Chân Ma công vốn vay ma khí từ Cổ Ma thủy tổ. Hắn thi triển Hoá kiếm vi ti, khiến cự kiếm phân thành nhiều tơ vàng linh động để thoát khỏi sự khống chế rồi thu phi kiếm về. Hai bên thừa nhận thần thông của nhau và tạm kết thúc giai đoạn đấu kiếm thăm dò vì đây không phải trận sinh tử. Hàn Lập sau đó đồng thời bố trí hồng ti, tế Tam Diễm Phiến phóng tam sắc hỏa điểu và thúc viên châu trắng tạo biển hàn diễm tím. Nguyên Trí lấy ra một bình nhỏ màu xám bạc, để kim cương hư ảnh đỡ đòn hỏa ti và tập trung đề phòng tam sắc hỏa điểu đang mang theo linh lực đáng sợ."},{"chuong":1226,"tieuDe":"Vô Đề","tomTat":"Hàn Lập biến mười đạo hỏa ti thành hỏa liên, khóa chặt Kim cương hư ảnh của Nguyên Trí dù đối phương liên tục thu nhỏ pháp bảo và dùng kiếm quang phá vây. Nguyên Trí tiếp đó dùng ngân bình phóng thất sắc Phật quang thu tam sắc hỏa điểu, nhưng Hàn Lập kích nổ hỏa điểu ngay trong bình, khiến pháp bảo bạo liệt. Tam sắc hỏa diễm lan ra thiêu hủy bạch liên và Kim cương hư ảnh, làm Nguyên Trí chịu phản phệ nặng vì bổn mạng pháp bảo liên kết máu huyết với ông. Trước tử sắc hỏa mãng do Tử La Cực Hỏa biến thành, Nguyên Trí chủ động nhận thua và dùng đan dược trị thương. Sán Khổ giữ lời, sai một tu sĩ Kết Đan kỳ mang lệnh bài đi lấy bí thuật luyện chế giới tử không gian cho Hàn Lập. Sau trận đấu, Nguyên Trí xác định vũ phiến của Hàn Lập là phỏng chế phẩm linh bảo, rồi cùng mọi người trở vào Thiên Cơ Điện thưởng thức Tân long ngâm."},{"chuong":1227,"tieuDe":"Nửa Đường Chặn Giết","tomTat":"Sau khi rời Thiên Cơ Điện, Hàn Lập xem ngọc giản ghi Bí thuật luyện chế giới tử không gian và được Đồng tử giải thích rằng thành phẩm tại Nhân Giới khác xa chí bảo không gian chân chính của Linh Giới. Không muốn xông vào tổng đàn Âm La Tông đầy cấm chế và sát thủ, hắn quyết định phục kích tông chủ bên ngoài. Hơn nửa năm sau, các tu sĩ áo đen Âm La Tông chỉ huy hơn một nghìn đồng giáp luyện thi tiêu diệt toàn bộ bảy mươi ba người Huyết Cốt Môn xâm nhập. Tất Hỏa trưởng lão đến cứu viện nhưng bị Phòng tông chủ truy sát và hủy thân thể, chỉ có Nguyên Anh chạy thoát. Khi môn hạ Âm La Tông đã rời đi, Hàn Lập hiện thân và cho biết mình đã giám thị vùng phụ cận tổng đàn suốt khoảng nửa năm để chờ cơ hội này. Phòng tông chủ nhận ra Hàn Lập đã tiến giai Nguyên Anh hậu kỳ và tuyên bố sẽ báo thù cho vợ cùng các trưởng lão đã chết. Hai bên bước vào thế tử chiến, còn Phòng tông chủ vận hắc khí gọi những thân ảnh cao lớn ra giữa tiếng quỷ khóc."},{"chuong":1228,"tieuDe":"Trảm Sát Đại Tu Sĩ","tomTat":"Hàn Lập thả Ngũ Tử Đồng Tâm Ma đối đầu ba ô giáp Thi Vương của Phòng tông chủ, dùng biển ma diễm ngũ sắc đánh tan thi độc và vây khốn cả ba luyện thi. Phòng tông chủ tiếp tục tung ti võng vàng cùng một viên cầu đen có lai lịch bất thường, nhưng Hàn Lập lần lượt dùng Thanh Sắc Tiểu Đỉnh và Bát Linh Xích kiềm chế hai bảo vật. Một thân ảnh mang khuôn mặt Hàn Lập nhưng không có sinh khí xuất hiện làm nghi binh, tạo cơ hội để Hàn Lập thật từ trên cao phát động Tam Diễm Phiến. Trước đợt phản kích bằng chiến giáp, điện xà, ngọc bản và mũi nhọn vàng, Hàn Lập vận dụng Tật Phong Cửu Biến để né tránh. Hắn sau đó bất ngờ thi triển Kinh Thần Thứ đã tu đến tầng cuối, khiến thần thức của vị đại tu sĩ đau đớn dữ dội trong khoảnh khắc. Khi Phòng tông chủ vừa hồi phục và quay đầu vì nhận ra điều bất thường, một luồng hắc mang quỷ dị đánh trúng cổ khiến ông ngã xuống, nhưng chương chưa xác nhận rõ sinh tử."},{"chuong":1229,"tieuDe":"Mưu Đồ Với Âm La Tông","tomTat":"Hàn Lập phối hợp Kinh Thần Thứ với Ma Tuỷ Phi Đao, lợi dụng lúc thần niệm của Phòng tông chủ co về thân thể để đánh lén và chém rời đầu đối phương. Thi thể tông chủ tự bạo thành huyết vân che chở Nguyên Anh đào thoát, nhưng huyết vân nhanh chóng bị Tịch Tà Thần Lôi tiêu diệt. Hàn Lập dùng Phong Lôi Sí thi triển Lôi độn truy đuổi, hai lần vận dụng Phá Diệt Pháp Mục phá thuấn di rồi dùng tiểu kiếm vàng vây khốn Nguyên Anh. Hư Thiên Đỉnh phóng thanh ti trói mục tiêu, giúp Hàn Lập đánh ngất, phong cấm và thu Nguyên Anh vào đỉnh để sưu hồn. Trong khi đó, Ngũ Tử Đồng Tâm Ma dùng ma diễm cực hàn áp chế và cắn nuốt gần hết ba thi vương, còn Hàn Lập thu dọn các bảo vật trên chiến trường. Tin tức thu được cho thấy tổng đàn Âm La Tông chỉ còn năm sáu trưởng lão trấn giữ, vì vậy Hàn Lập quyết định đánh phủ đầu nơi này rồi lần lượt xử lý những trưởng lão còn ở bên ngoài. Hắn nhận định Âm La Tông đã mất đại tu sĩ tọa trấn nên khó giữ địa vị thập đại tông môn và sẽ sớm bị các cừu gia thừa cơ công kích."},{"chuong":1230,"tieuDe":"Lôi Chấn Tử (1)","tomTat":"Hàn Lập lấy viên cầu đen vừa thu được đặt cạnh viên cầu lửa từng đoạt từ Ma Cưu tại Huyền Ngọc Động, phát hiện chúng lần lượt chứa ma khí tinh thuần và hỏa linh lực mạnh mẽ. Đồng tử xác nhận cả hai đều là Lôi Chấn Tử thứ phẩm, còn tên Diệt Tiên Châu chỉ là cách gọi tại Nhân giới. Vật này có uy lực đủ khiến tu sĩ Hóa Thần kỳ trúng đòn khó giữ thân thể nguyên vẹn, nhưng chỉ cần ít pháp lực nên ngay cả phàm nhân cũng có thể sử dụng. Do phương pháp luyện chế không đổi mà uy lực quá lớn, bí pháp chế tạo Lôi Chấn Tử rất hiếm người nắm giữ; đồng tử cũng chưa chịu tiết lộ mục đích ban đầu của nó. Hàn Lập cất cả hai viên làm thủ đoạn dự phòng cho tương lai. Trong lúc đó, năm quỷ đầu do Ngũ Tử Đồng Tâm Ma hóa thành áp đảo tam thi Nguyên Anh trung kỳ, cắn nuốt thân thể và hút dần thi khí của chúng."},{"chuong":1231,"tieuDe":"Lôi Chấn Tử (2)","tomTat":"Sau khi biết số phận của tam thi đã được định đoạt, Hàn Lập cân nhắc kế hoạch lẻn vào Âm La Tông và tin rằng sự am hiểu các cấm chế sẽ giúp mình hành động thuận lợi. Trong nửa năm kế tiếp, tông chủ cùng bảy tám trưởng lão Nguyên Anh của Âm La Tông lần lượt mất tích, còn các Nguyên Thần Đăng tương ứng đều tắt, xác nhận họ đã chết. Hơn phân nửa lực lượng trưởng lão Nguyên Anh bị tổn thất khiến thực lực tông môn suy yếu quá nửa, tạo cơ hội cho nhiều tông môn Chính–Ma phụ cận tiến vào xâm lấn lãnh địa. Tại một vùng núi hoang ở Hoắc Châu, các tu sĩ Luyện Khí kỳ quan sát Lâm sư huynh dùng Thanh Linh Kiếm dần áp chế thiếu niên điều khiển phi đao đỏ lửa. Giữa lúc cuộc tỷ thí diễn ra, một cô gái và thiếu niên đứng xem bất ngờ phát hiện trên không có nam tử mang đôi cánh phủ hồ quang xanh trắng. Khi người này quay lại, họ kinh hãi nhìn thấy trên khuôn mặt y còn có một con mắt đen thui, đờ đẫn và không biểu cảm."},{"chuong":1232,"tieuDe":"Ngoài Ý Muốn","tomTat":"Một nam tử có con mắt thứ ba phát hiện Phong Lão Quái đang ẩn trong hư không, còn Hàn Lập dựa vào đôi cánh sau lưng liên tục né tránh bàn tay ánh sáng của lão. Phong Lão Quái là tu sĩ Hóa Thần và là tổ tiên cách mười đời của trưởng lão Âm La Tông vừa bị Hàn Lập giết ngay trước mặt lão. Sau biến cố đó, lão hiển lộ tu vi chân thật và truy sát Hàn Lập gần một tháng, buộc hắn từ bỏ kế hoạch tiếp tục săn các trưởng lão Âm La Tông để đoạt Quỷ La Phiên. Hàn Lập nhiều lần thoát thân nhờ Phong Lôi Sí, Tật Phong Cửu Biến và Phong Lôi độn nhưng vẫn không tìm ra cách Phong Lão Quái xác định chính xác vị trí của mình. Kế hoạch dùng Vạn Niên Linh Dịch kéo cạn pháp lực đối phương cũng thất bại vì Phong Lão Quái có linh dịch tương tự và vẫn duy trì được thổ linh khí. Khi lượng Tịch Tà Thần Lôi trong Thanh Trúc Phong Vân Kiếm không thể tiếp tục duy trì Phong Lôi Sí lâu hơn, Hàn Lập quyết định ngừng chạy và trực tiếp thử sức với tu sĩ Hóa Thần. Phong Lão Quái dù đã hao tổn nhiều năm thọ nguyên cùng gần nửa bình linh dịch vẫn không chịu dừng lại, vừa vì báo thù và thể diện, vừa vì nảy lòng tham với những bảo vật của Hàn Lập."},{"chuong":1233,"tieuDe":"Gặp Lại Hướng Chi Lễ","tomTat":"Sau thời gian bị truy đuổi, Hàn Lập cân nhắc các át chủ bài rồi quyết định ngừng chạy và trực tiếp đối đầu Phong lão quái. Phong lão quái dùng Vạn Nhận Bàn tạo hàng nghìn phi đao màu lam hợp thành thế núi đao, còn Hàn Lập gọi bảy mươi hai phi kiếm và dùng Bát Linh Xích hóa thành hoa sen bạc phòng thủ. Nhận ra Bát Linh Xích, Phong lão quái xác định Hàn Lập từng xuất hiện tại Côn Ngô Sơn và ép hỏi về vật Linh Lung có thể đã để lại liên quan đến Không Gian Tiết Điểm. Hàn Lập giữ kín thông tin, không chịu giao đồ và sẵn sàng tiếp tục giao chiến. Đúng lúc ấy, Hướng Chi Lễ xuất hiện, ngăn hai bên động thủ và công nhận Hàn Lập là sư đệ trên danh nghĩa theo quan hệ cũ tại Hoàng Phong Cốc. Lão đề nghị Phong lão quái bỏ qua ân oán, đồng thời tiết lộ Hàn Lập sở hữu hai kiện Thông Thiên Linh Bảo cùng vài kiện phỏng chế linh bảo, khiến đối phương biến sắc."},{"chuong":1234,"tieuDe":"Hợp Tác","tomTat":"Hàn Lập cảnh giác khi biết Hướng Chi Lễ nắm rõ việc hắn sở hữu Bát Linh Xích và Hư Thiên Đỉnh, nhưng Hướng Chi Lễ cho rằng Thông Thiên Linh Bảo không đủ để tu sĩ Hóa Thần bất chấp mọi giá tranh đoạt. Khi Phong lão quái vẫn muốn ra tay, Hàn Lập thừa nhận đã giết Càn tiểu tử, Hàn Ly cùng những người liên quan tới Âm La Tông rồi lấy ra hai viên Diệt Tiên Châu để chứng minh mình có khả năng đồng quy vu tận. Sức uy hiếp ấy khiến Phong lão quái tạm gác ân oán và chấp nhận để Hướng Chi Lễ định đoạt. Hướng Chi Lễ công nhận Hàn Lập đủ tư cách giao tiếp ngang hàng, đồng thời đề nghị ba người hợp tác tìm không gian tiết điểm nhằm chuẩn bị con đường rời nhân giới. Ông cho biết nhóm tu sĩ Hóa Thần tại Đại Tấn hiện rất ít người và các tiết điểm đã tìm thấy đều bị phong bạo ngăn cản hoặc quá bất ổn để sử dụng. Cuộc trao đổi còn hé lộ Tiểu Cực Cung từng phá hủy một cửa vào có thể dẫn nổ Hư Linh Điện, cũng như ước định buộc Xa lão yêu không được tùy tiện rời Vạn Yêu Cốc gây họa. Cuối cùng, Hướng Chi Lễ tiết lộ Xa lão yêu đang nắm một tiết điểm mà tu sĩ nhân tộc không thể vượt qua, còn hắn có thể dựa vào bản thể mạnh mẽ để tiến vào."},{"chuong":1235,"tieuDe":"Ma Đà Sơn","tomTat":"Hướng Chi Lễ tiết lộ Xa lão yêu dự định tiến vào một không gian tiết điểm trong một hai trăm năm tới, khiến mọi người nghi ngờ thọ nguyên của lão đã gần cạn. Hàn Lập đồng ý giao ngọc giản chứa toàn bộ tư liệu mình có về không gian tiết điểm và phương pháp bố trí nghịch hành thông đạo truyền tống trận, đổi lại quyền được báo tin để tự khảo sát khi có phát hiện thích hợp. Sau khi nhận tư liệu, Hướng Chi Lễ trao cho hắn hai Vạn lý phù và đưa hắn vào phạm vi quy tắc hạn chế của giới Hóa Thần vì chiến lực đã vượt xa tu sĩ Nguyên Anh hậu kỳ thông thường. Chuyện Hàn Lập tiêu diệt nhiều tu sĩ Nguyên Anh của Âm La Tông được bỏ qua, còn các tu sĩ Hóa Thần khác từ nay cũng không được tùy ý ra tay với hắn. Hướng Chi Lễ tiếp đó mời Hàn Lập cùng Phong lão quái tới Ma Đà Sơn dự lễ Hô Khánh Lôi nạp ba thị thiếp. Khi biết Ma Đà Sơn có Ma Luyện Thiên Nguyên Đan, loại linh dược thất truyền có ích cho việc đột phá Hóa Thần, Hàn Lập bắt đầu nghiêm túc cân nhắc chuyến đi. Trên đỉnh Ma Đà Sơn được cấm chế duy trì khí hậu bốn mùa như xuân, Ma cung đã mở đại tiệc với khách quý và các cung trang nữ tử ca múa. Tại chủ tọa đại điện, một Mộc Quan lão giả xanh xao, ốm yếu ngồi tựa trên ghế với vẻ đắc ý."},{"chuong":1236,"tieuDe":"Khách Tới Ma Cung","tomTat":"Hô Khánh Lôi mở yến tiệc tại Ma cung và bày tỏ nỗi lo Thiên Ma Tông sẽ bị chèn ép nếu ông tọa hóa trước khi hậu bối xuất hiện tu sĩ Hóa Thần. Ông lấy sự suy sụp của Âm La Tông làm lời cảnh tỉnh, bởi nhiều trưởng lão Nguyên Anh cùng Phòng tông chủ đã chết, khiến tông môn này bị loại khỏi hàng ngũ thập đại ma tông. Khi khách dự tiệc hỏi về lễ nạp thiếp, Hô Khánh Lôi tiết lộ cả ba nữ tu đều xuất sắc và sai người mời họ ra mắt, nhưng một đạo truyền âm phù báo khách tới đã cắt ngang. Hướng Chi Lễ và Phong lão quái dẫn Hàn Lập vượt qua cấm chế hộ sơn để vào Ma cung, khiến Hô Khánh Lôi cùng các khách nhân ra nghênh đón. Hướng Chi Lễ công khai giới thiệu Hàn Lập là thành viên mới trong hàng ngũ của các tu sĩ Hóa Thần, dù hắn vẫn mang tu vi Nguyên Anh hậu kỳ. Hô Khánh Lôi ban đầu phản đối tư cách của Hàn Lập, nhưng sau khi nghe Hướng Chi Lễ truyền âm thì chuyển từ giật mình sang hưng phấn và cuối cùng gật đầu chấp nhận."},{"chuong":1237,"tieuDe":"Thị Thiếp","tomTat":"Sau khi nghe Hướng Chi Lễ truyền âm về chiến tích của Hàn Lập tại Côn Ngô Sơn và Âm La Tông, Hô Khánh Lôi thay đổi thái độ, thừa nhận hắn đủ tư cách giao tiếp ngang hàng với các tu sĩ Hóa Thần. Hàn Lập gặp lại Khổ Trúc lão nhân, người từng tranh đoạt Ô Phượng Chi Linh với hắn nhưng hiện vẫn mắc kẹt tại bình cảnh Nguyên Anh trung kỳ đỉnh phong. Trước câu hỏi công khai của một lam bào nho sinh, Hàn Lập thẳng thắn xác nhận chính mình đã giết tông chủ Âm La Tông, khiến toàn điện xôn xao. Hô Khánh Lôi sau đó gọi ba thị thiếp vào dâng rượu và thúc giục khách nhân lấy lễ vật chúc mừng; Hàn Lập chuẩn bị hai bình đan dược có tác dụng tinh tiến tu vi Nguyên Anh kỳ. Một trong ba thị thiếp là Tử Linh, người quen cũ của Hàn Lập. Hai người chấn động khi nhận ra nhau, để lộ mối quan hệ sâu đậm trước ánh mắt của toàn bộ khách dự tiệc. Sắc mặt Hô Khánh Lôi lập tức trở nên âm trầm khi chứng kiến phản ứng của họ."},{"chuong":1238,"tieuDe":"Giúp Đỡ","tomTat":"Hô Khánh Lôi ép Tử Linh mời Hàn Lập một chén rượu để đoạn tuyệt quan hệ cũ trước khi nàng trở thành thị thiếp trong Ma cung. Uống cạn chén rượu, Hàn Lập lập tức vạch trần cấm chế trong cơ thể Tử Linh và buộc nàng nói rõ rằng mình từng bị các trưởng lão Thiên Ma Tông bắt sống, hoàn toàn không tự nguyện với cuộc hôn phối này. Bất chấp sự phẫn nộ và uy áp của Hô Khánh Lôi, Hàn Lập kiên quyết đòi đổi một điều kiện ngang giá lấy tự do cho Tử Linh, đồng thời truyền pháp lực bảo vệ nàng. Hắn dùng Diệt Tiên Châu cùng phần tư liệu không gian tiết điểm còn giữ lại để khiến Hô Khánh Lôi dè chừng, trong khi Hướng Chi Lễ cũng bí mật yêu cầu lão không được lấy mạng hắn. Hô Khánh Lôi lần lượt đòi hai kiện linh bảo và Diệt Tiên Châu nhưng đều bị Hàn Lập từ chối. Cuối cùng, Hàn Lập đề nghị dùng Hàn Tủy, nguyên liệu chủ yếu để luyện Hồi Dương Thủy có thể kéo dài thọ nguyên hàng trăm năm, khiến Hô Khánh Lôi thay đổi thái độ và nghiêm túc cân nhắc cuộc trao đổi."},{"chuong":1239,"tieuDe":"Hàn Lập Trao Đổi","tomTat":"Phong Lão Quái cảnh báo Hô Khánh Lôi rằng Hàn Lập có thể sở hữu nhiều hơn một viên Diệt Tiên Châu, còn Hướng Chi Lễ yêu cầu không được giết hắn nếu không chắc có thể bắt sống. Khi được cho cơ hội rút lại lời muốn đưa Tử Linh rời Ma cung, Hàn Lập vẫn kiên quyết từ chối, khiến Hô Khánh Lôi phóng linh áp Hóa Thần khắp đại điện. Hàn Lập truyền pháp lực bảo vệ Tử Linh trước áp lực ấy và bình thản tiếp tục đối mặt với lão ma. Hô Khánh Lôi thu hồi khí thế rồi đòi hai kiện Thông Thiên linh bảo, sau đó đổi sang Diệt Tiên Châu, nhưng cả hai điều kiện đều bị Hàn Lập bác bỏ. Hàn Lập chuyển sang hỏi về thọ nguyên của đối phương và tiết lộ mình có một phần hàn tủy, nguyên liệu chủ yếu để luyện Hồi Dương Thủy. Hắn đề nghị dùng hàn tủy đổi lấy tự do của Tử Linh, đồng thời chỉ ra rằng Thiên Ma Tông vẫn có hy vọng tìm được Thái Dương Tinh Hỏa để hoàn thành linh dược. Cơ hội kéo dài thọ nguyên thêm bốn đến năm trăm năm khiến Hô Khánh Lôi hết giận và trầm ngâm cân nhắc, nhưng lão chưa đưa ra quyết định cuối cùng."},{"chuong":1240,"tieuDe":"Một Kích","tomTat":"Hô lão ma xác định Hàn Tủy Hàn Lập mang tới có nguồn gốc từ Huyền Ngọc Động và chấp nhận lượng vật liệu đủ luyện chế khoảng hai viên Hồi Dương Thủy. Tuy nhiên, ngoài giao dịch đã định, lão buộc Hàn Lập phải trực diện tiếp một kích, không được tránh né hoặc sử dụng Diệt Tiên Châu, mới để Tử Linh rời Ma Đà Sơn. Tử Linh sợ Hàn Lập mất mạng nên cam chịu ở lại Ma cung, nhưng Hàn Lập vẫn nhận lời. Hô lão ma rút hắc ti cấm chế khỏi đan điền Tử Linh, giúp nàng khôi phục pháp lực, rồi nhận và kiểm tra bình ngọc chứa Hàn Tủy. Hàn Lập trấn an Tử Linh bằng kinh nghiệm từng ngạnh kháng một kích của Cổ ma thủy tổ, sau đó đưa nàng ra ngoài điện. Hướng Chi Lễ khuyên Phong lão quái tập trung tìm không gian tiết điểm để phi thăng Linh giới, nhưng cả hai vẫn lo Hô lão ma nhân cơ hội giết Hàn Lập nên cùng ra giám sát. Chương kết thúc khi Hàn Lập và Hô lão ma đã đối diện nhau trên không, còn một kích quyết định vẫn chưa được tung ra."},{"chuong":1241,"tieuDe":"Núi Thúy Phong","tomTat":"Phong lão quái tiết lộ với Hướng Chi Lễ rằng Hô lão ma vừa chiếm được một dị bảo có uy lực không kém linh bảo, khiến Hướng Chi Lễ phải đánh giá lại nguy cơ đối với Hàn Lập. Một quyển trục cổ tỏa thúy quang được lấy ra, phóng thành mười tám tiểu sơn xanh biếc rồi tăng lớn sau khi nhận linh lực. Hàn Lập dựng ba tầng phòng hộ bằng Bát Linh Xích, Hư Thiên Đỉnh và Kim Cương Tráo, đồng thời gọi Đề Hồn thú cùng Ngũ Tử Đồng Tâm Ma nghênh chiến. Chuỗi sơn phong liên tiếp ép xuống làm cự xoa và song cốt nhận vỡ nát, nhưng Ngũ Tử Đồng Tâm Ma bất ngờ phun ngũ sắc quang diễm để tạm thời ngăn thúy mang. Khi lớp quang diễm tan vỡ, Hàn Lập tiếp tục dùng Tam Diễm Phiến và linh vân do thanh ti của Hư Thiên Đỉnh biến thành, song hai ngọn núi kế tiếp lại khiến hắn rơi vào thế yếu. Cuối chương, Hàn Lập chuyển ngân sắc cự liên lên đỉnh đầu, khiến thất sắc Phật quang xuất hiện và Bát Linh Xích bắt đầu cuồng trướng để chuẩn bị chống đỡ."},{"chuong":1242,"tieuDe":"Bát Linh Xích Cùng Đề Hồn Thú","tomTat":"Hàn Lập dùng Điện Mãng, Tử Giao và Ngân Liên chống lại cự sơn do tám ngọn núi hợp thành, nhưng các đòn công kích ban đầu chỉ khiến nó khẽ rung chuyển. Hắn phải hao tổn tinh huyết thúc phát lục sắc mộc thước, triệu ra tám linh thú hư ảnh hợp lực giữ cự sơn giữa không trung. Hô lão ma âm thầm phóng hàng trăm Thương Viên yêu hồn, song Đề Hồn Thú dùng hoàng hà đánh tan rồi nuốt sạch toàn bộ đàn yêu hồn. Khi Hàn Lập đang cân nhắc tiếp tục phá núi, Hướng Chi Lễ hóa ra linh trảo nâng cự sơn và buộc Hô lão ma tuân thủ ước hẹn chỉ giao thủ một kích. Hô lão ma thừa nhận Hàn Lập đã đỡ được đòn, thu bảo vật và tuyên bố vẫn tổ chức lễ nạp hai người thiếp còn lại sau ba ngày. Hàn Lập cùng các tu sĩ đồng ý lưu lại dự lễ, còn Tử Linh xin đi cùng hắn nhưng được báo phải chờ thêm vài ngày mới có thể rời Ma cung."},{"chuong":1243,"tieuDe":"Hoả Ngục","tomTat":"Hàn Lập và Tử Linh quyết định ở lại Ma cung dự nạp thiếp đại điển để tránh làm mất lòng Hô lão ma; sau đại lễ, họ cùng Hướng Chi Lễ lập tức rời đi. Trên đường, Hàn Lập và Tử Linh xác lập tình cảm, nhưng nàng không muốn làm thị thiếp nên lựa chọn độc thân, chuyên tâm cầu đại đạo rồi dứt khoát từ biệt. Hàn Lập tôn trọng quyết định của nàng, tự ổn định lại tâm cảnh và tiếp tục hành trình. Sau nhiều tháng, hắn tới Hoả Ngục, một trong thất đại cấm địa của Đại Tấn, nhằm tìm Thái Dương Tinh Hoả để luyện dương thuỷ kéo dài thọ nguyên. Trước biển hồng vụ có khả năng áp chế thần niệm và ăn mòn linh quang hộ thể, hắn dùng bộ Hoả Long Trụ dựng lồng lửa để mở đường đi sâu. Khi đang suy xét về yêu thú cao giai cùng mối nguy hiểm chưa rõ trong cấm địa, Hàn Lập bất ngờ cảm ứng được dị thường và phóng kim quang vào màn khói."},{"chuong":1244,"tieuDe":"Pháp Trận, Tế Đàn Và Cự Đỉnh","tomTat":"Hàn Lập tiếp tục tiến sâu vào hồng sắc vụ hải, dùng Hỏa Linh Ti và phi kiếm tiêu diệt nhiều yêu thú hỏa thuộc tính cản đường. Khi gặp một hỏa sát linh có thể liên tục phục hồi, hắn thử kiếm khí và bí thuật áp súc Tử La Cực Hỏa nhưng vẫn không thể triệt để tiêu diệt nó. Thái Âm Chân Hỏa bất ngờ hóa thành hỏa điểu, chủ động nuốt sạch hỏa sát linh, rồi tiếp tục thôn phệ thêm hai con khác trên đường. Sau ba ngày và một lần thận trọng vượt qua hỏa hồ đầy những cột lửa phun bất ngờ, Hàn Lập tới ngọn núi lửa khổng lồ lơ lửng giữa không trung. Hắn sai đệ nhị Nguyên Anh điều khiển nhân hình khôi lỗi mang trận kỳ và trận bàn đi bố trí, đồng thời đặt tế đàn noãn ngọc tại trung tâm miệng núi lửa. Cuối cùng, Hàn Lập phóng lớn Càn Lam Đỉnh, dùng Kiền Lam Băng Diễm đóng băng khu vực rồi kích hoạt hơn mười cột sáng lam, tạo thành một nhà lao phong kín không gian chung quanh."},{"chuong":1245,"tieuDe":"Hoả Tinh Xuất Hiện","tomTat":"Hàn Lập hoàn tất cạm bẫy quanh pháp trận bằng tiểu đỉnh màu lam, Nhân hình khôi lỗi và mười hai con Lục Dực Sương Công rồi dùng Tử La Cực Hỏa chìm xuống dung nham. Do thần niệm bị môi trường cực nhiệt hạn chế, hắn thả Thái Âm Hỏa Điểu tìm Thái Dương Tinh Hỏa bằng sự hấp dẫn giữa hai loại linh hỏa. Sau một tháng tìm kiếm không ngừng và tiêu hao nhiều pháp lực, Hàn Lập cuối cùng cảm ứng được biến động, lập tức triển khai Ngũ Tử Đồng Tâm Ma cùng Hỏa Long Trụ để mai phục. Thái Âm Hỏa Điểu xuất hiện với một luồng ngân quang truy đuổi phía sau, để lộ Thái Dương Tinh Hỏa đã hóa thành con ngựa nhỏ trắng noãn có cánh bạc. Nhờ mượn sức dung nham, hỏa linh này dần áp đảo Thái Âm Hỏa Điểu và truy đuổi nó tới gần miệng núi lửa. Hàn Lập không trực tiếp tấn công mà đưa Tuyết Tinh Châu tới để hỏa điểu nuốt vào, mượn Tử La Cực Hỏa tăng mạnh tốc độ. Thái Âm Hỏa Điểu nhờ đó kéo giãn khoảng cách, dẫn Thái Dương Tinh Hỏa bay khỏi miệng núi lửa theo hướng cạm bẫy đã bố trí."},{"chuong":1246,"tieuDe":"Bắt Giữ Thái Dương Tinh Hoả","tomTat":"Thái Âm Hỏa Điểu dụ Thái Dương Tinh Hoả mang hình thái Ngân Sí Tiểu Mã rời khỏi lòng đất và tiến vào lồng giam, nơi Nhân hình khôi lỗi lập tức phát động pháp trận. Hàn giao do Kiền Lam Băng Diễm hoá thành, Ngũ Tử Đồng Tâm Ma và Thái Âm Hỏa Điểu liên tục truy kích, trong khi lam băng cùng quang võng chặn các đường đào thoát. Hai con Lục Dực Sương Công ép hoả linh đổi hướng, tạo cơ hội cho Ma Tuỷ Phi Đao chém đôi thân thể và làm nó tổn thương nguyên khí. Hàn Lập dùng hoả ti trói mục tiêu nhưng lần phong cấm đầu tiên thất bại khi hoả linh giành quyền điều động các hoả ti để thiêu huỷ phù triện. Hắn lập tức thi triển Kinh Thần Thứ làm Thái Dương Tinh Hoả mê muội rồi ngưng tụ tử sắc quang diễm thành bàn tay bắt giữ và đóng băng nó. Thái Âm Chân Hoả, Hàn giao và năm loại hàn diễm của Ngũ Tử Đồng Tâm Ma cùng gia tăng sức áp chế, giúp Hàn Lập dán phù triện thành công. Thái Dương Tinh Hoả cuối cùng ngừng giãy dụa, mất hình thái Ngân Sí Tiểu Mã và trở lại thành một đoàn quang diễm bị phong trong tử băng."},{"chuong":1247,"tieuDe":"Tiên Đằng Sống Lại","tomTat":"Hàn Lập dùng Thái Âm Hỏa Điểu, tử băng và kim sắc điện quang phong ấn Thái Dương Tinh Hỏa rồi thu nó vào Hư Thiên Bảo Đỉnh. Hoàn thành mục đích tại Đại Tấn, hắn trở về Lạc Vân Tông và lần lượt luyện hóa linh hỏa thành dương thủy, luyện khe không gian thành giới tử không gian, đồng thời chế tạo Xích Hồn Phiên từ tàn phiến Hắc Phong Kỳ cùng linh hồn trong các cây Quỷ La Phiên. Hắn uống một bình dương thủy, giữ phần dành cho Nam Cung Uyển đang bế quan và chuẩn bị các điều kiện tiến giai Hóa Thần, trong đó có ba viên Ma Nguyên Đan đổi từ Hô lão ma. Sau mười năm tu luyện, Nguyên từ thần quang chỉ đạt đỉnh tầng một, khiến hắn xác định phải đến Tinh Cung thu hồi Nguyên Từ Sơn. Thiên Lan Thánh Thú phân thân còn khuyên hắn dùng yêu đan kim thuộc tính cấp hóa hình để bổ khuyết linh căn, nhưng Hàn Lập tạm chọn phương án tìm pháp khí kim thuộc tính thay thế. Khi xuất quan và trao đổi thần niệm với đệ nhị Nguyên Anh, hắn bất ngờ nhận được tin Huyền Thiên Tiên Đằng đã sống lại."},{"chuong":1248,"tieuDe":"Huyền Thiên Chi Bảo","tomTat":"Nhận tin từ Nhân hình khôi lỗi, Hàn Lập tới dược viện và phát hiện cành khô Huyền Thiên Tiên Đằng đã hồi sinh, mọc kín các cột đá bạch ngọc. Hắn nhận ra đường vân trên lá giống những ký tự chưa hoàn chỉnh và quyết định không hỏi Thiên Lan Thánh Thú phân thân để tránh làm lộ cơ duyên tới Linh giới. Tin rằng lục dịch từ thần bí bảo bình có thể rút ngắn thời gian tiên đằng sinh linh hoa hoặc linh quả, Hàn Lập bố trí nhiều lớp cấm chế bảo vệ rồi giao Nhân hình khôi lỗi trấn giữ động phủ. Vài tháng sau, hắn trở lại Thiên Tinh Thành và âm thầm vượt qua nhiều tầng cấm chế để gặp Lăng Ngọc Linh. Biết công pháp của nàng đang đình trệ, Hàn Lập vẫn nói rõ mục đích chính của chuyến đi là thu hồi Nguyên Từ Sơn. Trong thông đạo dưới chân Thánh sơn, hắn dùng tầng thứ nhất của Nguyên từ thần quang làm suy yếu lực ngũ hành quanh thân. Lăng Ngọc Linh tiếp tục mời hắn lưu lại Tinh Cung tu luyện, nhưng Hàn Lập dứt khoát từ chối và quyết định thử phương pháp mang ngọn núi đi."},{"chuong":1249,"tieuDe":"Mai Phục Tại Hoang Đảo","tomTat":"Hàn Lập dùng huyết vân của Xích Hồn Phiên thu toàn bộ Nguyên Từ Sơn vào không gian bên trong, khiến Lăng Ngọc Linh từ bỏ hy vọng giữ hắn lại Tinh Cung bằng điều kiện tu luyện Nguyên từ thần quang. Hắn đồng ý lưu lại trao đổi tâm đắc tu luyện, đồng thời nhờ Lăng Ngọc Linh điều tra chính xác hành tung của Kim Giao Vương. Sau hai năm dò xét, Tinh Cung phát hiện Kim Giao Vương sẽ tới một vùng biển tại Ngoại hải để thu hái Long Lân Quả đang vào kỳ thành thục. Hàn Lập theo một nữ đệ tử Tinh Cung tới hoang đảo, cho người dẫn đường rời đi rồi bố trí năm bộ xương mang ma khí và mười hai Lục Dực Sương Công quanh đảo. Sau khi hoàn tất mai phục, hắn che giấu toàn bộ tung tích và chờ mục tiêu xuất hiện. Kim Giao Vương tới nơi cùng một tu sĩ áo xanh được gọi là Phong huynh, thoáng cảm thấy dấu vết thần niệm dò xét nhưng không tìm ra bất thường. Hai người tiếp tục tiến vào khu vực mai phục trong lúc bàn về Long Lân Quả và khả năng có cường giả đe dọa Kim Giao Vương."},{"chuong":1250,"tieuDe":"Long Lân Quả","tomTat":"Kim Giao Vương tiết lộ rằng Long Lân Quả có thể cải tạo và cường hóa thân thể nếu được sử dụng thường xuyên trong nhiều năm, nhưng số lượng linh quả quá ít để dễ dàng đạt đến hiệu quả tối đa. Phong Hi cho biết mình nắm giữ phương pháp di dời linh thảo, linh mộc do một thượng cổ Yêu Tộc để lại và đồng ý giúp nhổ cây để đổi lấy linh dược. Trước khi việc di dời bắt đầu, Kim Giao Vương dùng bảo châu màu vàng kim khuếch đại thần thức và phát hiện Hàn Lập đang ẩn nấp trên hoang đảo. Phong Hi nhận ra Hàn Lập là tu sĩ từng bị mình truy sát, còn Kim Giao Vương nhận ra kẻ đã sát hại thân phụ và lấy đi cực phẩm linh thạch. Hàn Lập công khai tuyên bố mục tiêu là yêu đan của Kim Giao Vương, khiến yêu vương lập tức hóa thành hình thái chiến đấu và dùng trường thương vàng tấn công. Hàn Lập dùng ngân liên chặn đòn, vận dụng Phong Lôi Sí lùi lại rồi thúc giục Hư Thiên Bảo Đỉnh thu mất cặp đoản qua của Phong Hi."},{"chuong":1251,"tieuDe":"Lực Áp Nhị Yêu","tomTat":"Cặp đoản qua của Phong Hi vừa được lấy ra đã bị tiểu đỉnh của Hàn Lập thu mất, khiến Kim Giao Vương nghi ngờ đó là Hư Thiên Đỉnh và đề nghị hai yêu tu liên thủ. Kim Giao Vương hiện thêm hai cánh tay, còn Phong Hi chuyển sang hình thái bán yêu rồi cùng phát động giáp công, nhưng Hàn Lập dùng ngân liên, thất sắc phật quang và Tam sắc Vũ phiến giữ vững phòng tuyến. Kim sắc tiểu kiếm liên tục truy ép Phong Hi, phá tan cự trảo màu xanh và xuyên thủng màn sáng của ngọc bát, trong khi Kim Giao Vương cũng không thể phá được ngân liên. Khi nhận ra tình thế bất lợi, Phong Hi bị hơn mười con Lục Dực Sương Công chặn đường, còn Kim Giao Vương hóa thành kim hồng tháo chạy. Hàn Lập lập tức dùng hồng ti hóa thành vô số dây lửa, tạo biển lửa trói giữ Kim Giao Vương. Ngũ Tử Đồng Tâm Ma sau đó lao vào biển lửa, khiến Kim Giao Vương phát ra tiếng rống thê lương và kinh sợ."},{"chuong":1252,"tieuDe":"Thối Cốt Quyết","tomTat":"Phong Hi định hóa huyết bỏ chạy nhưng bị Bát Linh Xích giam cứng, Lục Dực Sương Công đóng băng rồi bị Hàn Lập diệt cả thân thể lẫn yêu hồn. Kim Giao Vương tự bạo huyết nhục, cho tinh hồn nhập vào Kim sắc Cốt Giao mang Giao Đan chạy trốn, song vẫn bị Hàn Lập phá độn, chém vỡ cốt thân và thu hồn. Hàn Lập lấy được Giao Đan thuộc tính Kim, Kim sắc Cốt, thượng cổ ngọc giản của Phong Hi và Thối Cốt Quyết, nhưng tạm chưa luyện pháp quyết này vì quá tốn thời gian. Dựa vào phương pháp trong ngọc giản, hắn tới một tiểu đảo hoang vắng, phá cấm chế và thu nhỏ Long Lân Quả Linh Thụ để mang đi. Sau nửa năm trở về Thiên Nam, Hàn Lập triệu tập Nam Cung Uyển, Lữ Lạc cùng những người thân tín để bí mật bố trí việc rời tông. Một năm sau, hắn cùng Nam Cung Uyển, Mộ Phái Linh và vài đệ tử thân truyền biến mất khỏi Lạc Vân Tông, còn Liễu Ngọc tiếp tục ở lại. Qua thời gian dài Hàn Lập trở thành nhân vật truyền thuyết, trong khi Lạc Vân Tông củng cố nền tảng, vươn lên thành siêu cấp đại tông phái và hưng thịnh nhiều vạn năm."},{"chuong":1253,"tieuDe":"Tiến Giai Hóa Thần Kỳ","tomTat":"Sau đại chiến Cổ Ma, Ngoại Cốc của Trụy Ma Cốc dần mất cấm chế và bị tu sĩ tìm bảo càn quét, trong khi Nội Cốc bị bạch sắc mê vụ cùng khe nứt không gian biến thành cấm địa của Thiên Nam. Trong một sơn cốc bí mật, đệ nhị Nguyên Anh của Hàn Lập điều khiển nhân hình Khôi Lỗi chăm sóc Dược Viên, sử dụng tiểu bình thần bí thúc giục linh thực và cấp phát linh dược cho bản thể. Ba trăm năm sau khi rời Lạc Vân Tông, Hàn Lập đã bố trí một Thượng Cổ Kỳ Trận che phủ phân nửa Nội Cốc rồi bế quan trong không gian giới tử. Nhờ tế luyện Yêu Đan của Kim Giao Vương thành Đan Linh Căn hệ Kim, hắn khắc phục thiếu hụt của Nguyên Từ Thần Quang, tu công pháp đến đại thành và luyện hóa hoàn toàn Nguyên Từ Sơn. Hàn Lập tiếp tục dùng Ma Nguyên Đan, linh dược, Cực Phẩm Linh Thạch và năm loại Cực Hàn Chi Diễm để đột phá Hóa Thần sơ kỳ. Khi trở lại Loạn Tinh Hải, hắn biết Nam Cung Uyển đã đạt Nguyên Anh hậu kỳ, Thạch Kiên kết thành Nguyên Anh và môn nhân đã kiểm soát hơn mười hòn đảo. Mộ Phái Linh lại thất bại khi kết Anh, bị tâm ma cùng pháp lực phản phệ dẫn đến tử vong, khiến Hàn Lập tự mình tới tế mộ nàng. Sau hơn mười năm ở bên Nam Cung Uyển trên đảo, Hàn Lập rời Loạn Tinh Hải và quay về Thiên Nam tiếp tục tu luyện."},{"chuong":1254,"tieuDe":"Ngũ Long Hải","tomTat":"Hàn Lập đưa Thạch Kiên trở về Thiên Nam và giao hắn tới cực Tây đoạt lại ngôi giáo chủ Thiên Trúc Giáo để kế thừa y bát Đại Diễn Thần Quân. Sau hơn trăm năm khổ tu tại Trụy Ma Cốc, Hàn Lập đạt đỉnh phong Hóa Thần sơ kỳ và luyện Thanh Nguyên Kiếm Quyết tới đại viên mãn, nhưng Giáng Vân Đan mất hiệu lực cùng thiên địa nguyên khí loãng khiến hắn không thể tiến lên trung kỳ. Trong thời gian đó, Hướng Chi Lễ, Phong lão quái và Hô lão quái tìm được không gian tiết điểm rồi cùng tiến vào, song ba bổn mạng Nguyên Thần Đăng lần lượt tắt nên kết cục của họ vẫn chưa rõ. Nhờ vị trí Hướng Chi Lễ để lại, Hàn Lập xác định tiết điểm nằm tại Ngũ Long Hải và bắt đầu chuẩn bị con đường rời Nhân Giới. Tới hải vực xa lạ này, hắn dùng Minh Thanh Linh Mục phát hiện một tiểu hội trao đổi trong thạch đình trên đảo và đề nghị dùng yêu đan đổi hải đồ cùng tin tức. Hàn Lập chỉ ra nội đan Lôi Kình Thú của Phạm tu sĩ đã thất thoát yêu lực rồi đưa ra một viên có phẩm tướng tốt hơn, khiến Phạm tu sĩ nổi giận và chất vấn lai lịch của hắn."},{"chuong":1255,"tieuDe":"Hải Vụ","tomTat":"Tôn tu sĩ và Phạm tu sĩ nghi Hàn Lập cố ý chia rẽ nhóm khi chê phẩm chất Lôi Kình thú yêu đan, nhưng hắn chỉ ra yêu lực đã thất thoát vì quá trình săn giết kéo dài. Bích tiên tử từ cách hắn xưng hô ngang hàng với Hướng Chi Lễ suy ra thân phận Hóa Thần, khiến những người trong thạch đình lập tức chuyển sang sợ hãi và cung kính. Do Bích tiên tử từng được Hướng Chi Lễ chỉ điểm, Hàn Lập trao cho nàng một viên yêu đan quý hiếm để đổi lấy hải đồ và thông tin về Ngũ Long Hải. Sau khi xác định vị trí không gian tiết điểm và biết vùng biển này không có tu sĩ Hóa Thần, hắn lên đường nhưng vẫn hạn chế độn tốc để tránh khuấy động thiên địa nguyên khí và tổn hại thọ nguyên. Hơn một tháng sau, Hàn Lập tiến vào vùng hải vụ, dùng hai đạo kim hồ phá lớp che giấu và phát hiện một tiểu đảo có kiến trúc. Ba tu sĩ Kết Đan phụng mệnh Hướng Chi Lễ nhận ra hắn qua bức họa được lưu lại, vui mừng trước lời hứa sẽ có môn hạ tới thay phiên trấn thủ rồi dẫn hắn đi xem không gian tiết điểm."},{"chuong":1256,"tieuDe":"Không Gian Tiết Điểm","tomTat":"Hàn Lập được ba môn hạ của Hướng Chi Lễ dẫn tới cửa vào không gian tiết điểm trong vụ hải và biết phong ấn tại đây đang suy yếu. Ba người dự đoán tiết điểm chỉ còn ổn định khoảng một trăm năm, khiến hắn quyết định lưu lại khảo sát và chuẩn bị tiến vào Linh Giới trong thời hạn này. Hàn Lập tiếp quản tiểu đảo, liên lạc Nam Cung Uyển để điều Điền Cầm Nhi cùng bốn tu sĩ Kết Đan tới thay ca, đồng thời thưởng cho những người trấn thủ cũ rồi cho họ rời đi. Điền Cầm Nhi nghiên cứu nhiều tháng và triển khai phương pháp gia cố phong ấn chỉ có khoảng hai ba thành chắc chắn, còn Hàn Lập tới Ngũ Long Hải thu thập vật liệu quý hiếm. Sau năm sáu năm, chu kỳ chấn động của tiết điểm rút xuống khoảng nửa năm một lần, khiến Hàn Lập dù đã tiến giai Hóa Thần vẫn phải tính chuyện đi khắp Nhân Giới tìm thêm bí thuật và bảo vật phòng hộ. Cuối chương, Phượng tiên tử tìm tới vụ hải, dùng bạch sắc hàn phong phá thế công của cấm chế và định ra tay với bốn tu sĩ Kết Đan. Hàn Lập kịp thời truyền âm ngăn cản, khiến nàng nhận ra hắn và hạ tay xuống."},{"chuong":1257,"tieuDe":"Kế Hoạch Liên Thủ","tomTat":"Băng Phượng đến tiểu đảo tìm không gian tiết điểm và kinh ngạc khi biết Hàn Lập cũng đã tiến giai Hóa Thần. Hàn Lập đề nghị hai người liên thủ vượt giới, dùng kết quả bất lợi của Hướng Chi Lễ, tình trạng chưa rõ của Xa lão yêu và thời hạn tồn tại khoảng trăm năm của tiết điểm để thuyết phục nàng. Băng Phượng đồng ý lưu lại quan sát nhưng chưa hoàn toàn tin tưởng hắn. Hàn Lập gọi Điền Cầm Nhi đến và đề nghị Băng Phượng ban bản mệnh Hàn Nguyên để hóa giải hạn chế Long Ngâm chi thể cho đệ tử, song nàng chỉ để ngỏ khả năng giúp đỡ. Sau nửa tháng quan sát, Hàn Lập rời đảo để tìm phương pháp chống cách giới chi lực. Thiên Lan thánh thú phân thân sau đó hiện thân, yêu cầu hắn thực hiện lời hứa giải trừ khống chế của tiểu đỉnh và cảnh báo nguy cơ thi triển tiên gia phù lục tại Nhân Giới. Cuối cùng, Hàn Lập nhận một kim sắc mộc hạp cùng ngọc giản xanh biếc chứa kết quả nghiên cứu liên quan đến tàn trang Kim Khuyết Ngọc Thư."},{"chuong":1258,"tieuDe":"Thao Túng Thiên Hạ","tomTat":"Hàn Lập kiểm tra tàn khuyết Ngọc Bài và ngọc giản do Thiên Lan thánh thú phân thân trao đổi, xác nhận chúng không phải đồ giả rồi bắt đầu dùng bí thuật giải trừ liên hệ giữa đối phương với Hư Thiên Đỉnh. Trong nhiều năm tiếp theo, hắn liên tục thay đổi dung mạo và thân phận, đi khắp Nhân Giới thu gom bí thuật không gian cùng những bảo vật phòng hộ mạnh để chuẩn bị vượt không gian tiết điểm. Bảy mươi năm sau, tại Thiên Sa Đại Lục, Hàn Lập lấy Kim Thước Hoàn khỏi trọng địa một tông môn và bị hai lão giả Nguyên Anh đuổi kịp. Khi đề nghị dùng linh thạch mua lại bảo vật bị khước từ, hắn thi triển hôi sắc hà quang tước quyền khống chế Xích hồng tiểu kiếm và Kim Chuyên, đồng thời phá tan bạch sắc đại thủ của đối phương. Hàn Lập sau đó trả lại hai pháp bảo để thể hiện rằng mình không có ý giết người rồi mang Kim Thước Hoàn rời đi, khiến hai lão giả từ bỏ truy kích. Hắn đánh giá Kim Thước Hoàn thuộc ba bảo vật phòng hộ tốt nhất mới thu được và quyết định quay về sau khi được cảnh báo rằng không gian tiết điểm có thể sụp đổ. Cuối chương, thu hoạch lớn nhất trong những năm bôn ba của Hàn Lập được xác nhận không phải bảo vật, bí thuật hay sự lĩnh ngộ Kim Khuyết Ngọc Thư, nhưng vẫn chưa được tiết lộ."},{"chuong":1259,"tieuDe":"Hồi Đảo","tomTat":"Trong hơn mười năm du hành Nhân Giới, Hàn Lập định kỳ dùng Long Lân Quả phối hợp Thối Cốt Quyết, khiến xương cốt và khí lực tăng mạnh, đồng thời luyện Minh Vương Quyết tới tầng thứ tư. Nguyên Từ Thần Quang sau khi đại thành chuyển từ màu ngũ hành sang màu xám, tuy nguyên nhân chưa rõ nhưng uy lực vẫn đủ khiến tu sĩ cao hơn chàng một cấp khó đối phó. Tại Thiên Sa Đại Lục, Thiên Lan thánh thú phân thân cho biết đã giải trừ phần trói buộc cuối cùng trong Hư Thiên Đỉnh rồi chia tay Hàn Lập để tìm sinh linh có khí tức đồng loại. Hai năm sau, Hàn Lập trở về tiểu đảo trong Vụ hải thuộc Ngũ Long Hải và đoàn tụ với Nam Cung Uyển cùng các môn hạ. Điền Cầm Nhi báo rằng Hàn Nguyên do Băng Phượng ban tặng đã giải trừ hoàn toàn Long Ngâm Chi Thể, giúp nàng có thể chuẩn bị thử ngưng kết Nguyên Anh. Nam Cung Uyển dự định giao cho Hàn Lập một trọng bảo phòng ngự và mời Băng Phượng tới để cùng thương lượng kế hoạch liên thủ tiến vào không gian tiết điểm."},{"chuong":1260,"tieuDe":"Lục Đinh Thiên Giáp Phù","tomTat":"Băng Phượng đồng ý cùng Hàn Lập vượt không gian tiết điểm với điều kiện hai người hạ cấm chế lẫn nhau, đồng thời hẹn gặp lại sau đúng ba mươi năm. Nam Cung Uyển dự định ở lại Nhân Giới, dựa vào thọ nguyên do Hồi Dương Thủy mang lại để tiến giai Hóa Thần và tìm một tiết điểm khác. Nàng kể việc trở lại Huyết Sắc cấm địa sau khi đạt Nguyên Anh hậu kỳ, dùng lệnh bài vào bảo tháp nhận y bát của Thượng Cổ tu sĩ và thu được bảo vật từ một bộ tàn cốt. Trong số đó có Lục Đinh Thiên Giáp Phù, đạo phù có thể tự hút thiên địa linh khí, tạo sáu tầng hào quang rồi hóa thành chiến giáp màu lục. Nam Cung Uyển trao đạo phù duy nhất cho Hàn Lập để hắn phòng thân trong chuyến vượt tiết điểm, sau đó hai người sống bên nhau trong quãng thời gian còn lại. Ba năm sau, Nhân hình Khôi Lỗi dùng Vạn Lý Phù báo rằng Huyền Thiên Tiên Đằng đã nở hoa và sắp kết quả, khiến Hàn Lập bí mật vào Nội Cốc Trụy Ma Cốc lưu lại vài tháng. Khi kỳ hạn ba mươi năm tới, nhiều tu sĩ đã tụ tập dưới một quang đoàn khổng lồ tại Vụ hải."},{"chuong":1261,"tieuDe":"Tiến Vào Không Gian Tiết Điểm","tomTat":"Hàn Lập cùng Nam Cung Uyển, Điền Cầm Nhi, Thạch Kiên và những người khác chờ dưới quang đoàn khổng lồ cho đến khi Băng Phượng tới điểm hẹn. Sau khi Hàn Lập và Băng Phượng hạ Tử Cấm lẫn nhau, Điền Cầm Nhi chỉ huy các tu sĩ giải phong ấn, khiến quang đoàn biến thành một lỗ đen sâu không thấy đáy. Hàn Lập thu hồi Nguyên Anh thứ hai khỏi Nhân hình Khôi Lỗi rồi trao khôi lỗi, lam sắc đỉnh và tam sắc diễm cho Nam Cung Uyển phòng thân. Hắn và Băng Phượng triển khai nhiều tầng pháp bảo bảo hộ, trong đó Thiên Thuyền của Băng Phượng được tiểu sơn đen dùng hôi sắc hà quang gia cố. Thiên Thuyền chở cả hai tiến thẳng vào không gian tiết điểm rồi biến mất. Sau một tháng không có động tĩnh, Nam Cung Uyển sai Điền Cầm Nhi tái phong ấn cửa tiết điểm và chuẩn bị trở về Loạn Tinh Hải. Vì Hàn Lập không để lại bản mệnh Nguyên Thần Đăng, không ai biết hắn đã tới Linh Giới hay đã vẫn lạc giữa đường, và phần Nhân giới khép lại."}];
